QT_ISI(14,{"1803":["(Alif laam raa) hanya Allahlah yang mengetahui maksudnya. (Ini) ayat-ayat ini (adalah sebagian dari ayat-ayat kitab) Alquran; idhafat di sini mengandung makna min yang berarti sebagian (yaitu Alquran yang memberi penjelasan) yang memenangkan perkara yang hak atas perkara yang batil. Lafal ayat ini diathafkan kepada lafal sebelumnya dengan ditambah sifat.",[["الٓر ۚ","Alif Laam Ra"],["تِلْكَ","These"],["ءَايَـٰتُ","(are) the Verses"],["ٱلْكِتَـٰبِ","(of) the Book"],["وَقُرْءَانٍۢ","and Quran"],["مُّبِينٍۢ","clear"]]],"1804":["(Sering kali) dapat dibaca rubbamaa dan rubamaa (berkeinginan) mengharapkan (orang-orang yang kafir itu) kelak di hari kiamat, yaitu sewaktu diperlihatkan kepada mereka keadaan diri mereka dan keadaan kaum Muslimin (seandainya mereka menjadi orang-orang muslim) lafal rubba menunjukkan makna littaktsir/sering, karena sesungguhnya mereka sering kali mengharapkan hal tersebut. Akan tetapi menurut pendapat lain menunjukkan makna littaqlil, artinya sedikit, karena sesungguhnya kengerian-kengerian pemandangan di hari kiamat membuat mereka terkejut dengan sangat, sehingga mereka tidak sadar untuk berharap seperti itu melainkan hanya dalam masa yang sedikit.",[["رُّبَمَا","Perhaps"],["يَوَدُّ","will wish"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["لَوْ","if"],["كَانُوا۟","they had been"],["مُسْلِمِينَ","Muslims"]]],"1805":["(Biarkanlah mereka) biarkanlah orang-orang kafir itu, hai Muhammad (makan dan bersenang-senang) di dunia mereka ini (dan dilalaikan) disibukkan (oleh angan-angan kosong) dengan dipanjangkan umur mereka dan lain-lainnya sehingga mereka lupa daratan akan iman (maka kelak mereka akan mengetahui) akibat daripada perbuatan mereka. Ayat ini diturunkan sebelum ada perintah untuk memerangi mereka.",[["ذَرْهُمْ","Leave them"],["يَأْكُلُوا۟","(to) eat"],["وَيَتَمَتَّعُوا۟","and enjoy"],["وَيُلْهِهِمُ","and diverted them"],["ٱلْأَمَلُ ۖ","the hope"],["فَسَوْفَ","then soon"],["يَعْلَمُونَ","they will come to know"]]],"1806":["(Dan Kami tiada membinasakan) huruf min adalah zaidah (sesuatu negeri pun) yang dimaksud adalah para penduduknya (melainkan ada baginya ketentuan) masa (yang telah ditetapkan) yang terbatas untuk pembinasaan mereka.",[["وَمَآ","And not"],["أَهْلَكْنَا","We destroyed"],["مِن","any"],["قَرْيَةٍ","town"],["إِلَّا","but"],["وَلَهَا","(there was) for it"],["كِتَابٌۭ","a decree"],["مَّعْلُومٌۭ","known"]]],"1807":["(Tiada yang dapat mendahului) huruf min adalah zaidah (suatu umat pun akan ajalnya, dan tiada pula yang dapat mengundurkannya) menangguhkan saat ajalnya dari waktu yang telah ditentukan oleh Allah.",[["مَّا","Not"],["تَسْبِقُ","(can) advance"],["مِنْ","any"],["أُمَّةٍ","nation"],["أَجَلَهَا","its term"],["وَمَا","and not"],["يَسْتَـْٔخِرُونَ","(can) delay it"]]],"1808":["(Dan mereka berkata) yaitu orang-orang kafir Mekah kepada Nabi saw. (\"Hai orang yang diturunkan Adz-Dzikru kepadanya!) yakni Alquran, menurut perkiraan (Sesungguhnya kamu benar-benar orang yang gila.\")",[["وَقَالُوا۟","And they say"],["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِى","(to) whom"],["نُزِّلَ","has been sent down"],["عَلَيْهِ","[on him]"],["ٱلذِّكْرُ","the Reminder"],["إِنَّكَ","indeed, you"],["لَمَجْنُونٌۭ","(are) surely mad"]]],"1809":["(\"Mengapa tidak) (kamu datangkan malaikat kepada kami, jika kamu termasuk orang-orang yang benar?\") di dalam ucapanmu itu yang mengatakan, bahwa kamu adalah seorang nabi, dan Alquran ini dari sisi Allah?",[["لَّوْ","Why"],["مَا","not"],["تَأْتِينَا","you bring to us"],["بِٱلْمَلَـٰٓئِكَةِ","the Angels"],["إِن","if"],["كُنتَ","you are"],["مِنَ","of"],["ٱلصَّـٰدِقِينَ","the truthful"]]],"1810":["Allah berfirman (Kami tidak menurunkan) dan menurut suatu qiraat dibaca tanazzalu dengan membuang salah satu huruf ta-nya (malaikat melainkan dengan benar) untuk membawa azab (dan tiadalah mereka ketika itu) sewaktu malaikat turun dengan membawa azab (diberi tangguh) ditangguhkan azabnya.",[["مَا","Not"],["نُنَزِّلُ","We send down"],["ٱلْمَلَـٰٓئِكَةَ","the Angels"],["إِلَّا","except"],["بِٱلْحَقِّ","with the truth"],["وَمَا","and not"],["كَانُوٓا۟","they would be"],["إِذًۭا","then"],["مُّنظَرِينَ","given respite"]]],"1811":["(Sesungguhnya Kamilah) lafal nahnu mentaukidkan atau mengukuhkan makna yang terdapat di dalam isimnya inna, atau sebagai fashl (yang menurunkan Adz-Dzikr) Alquran (dan sesungguhnya Kami benar-benar memeliharanya) dari penggantian, perubahan, penambahan dan pengurangan.",[["إِنَّا","Indeed, We"],["نَحْنُ","We"],["نَزَّلْنَا","have sent down"],["ٱلذِّكْرَ","the Reminder"],["وَإِنَّا","and indeed, We"],["لَهُۥ","of it"],["لَحَـٰفِظُونَ","(are) surely Guardians"]]],"1812":["(Dan sesungguhnya Kami telah mengutus sebelum kamu) beberapa rasul (kepada umat-umat) golongan-golongan (terdahulu.)",[["وَلَقَدْ","And certainly"],["أَرْسَلْنَا","We (had) sent"],["مِن","before you"],["قَبْلِكَ","before you"],["فِى","in"],["شِيَعِ","the sects"],["ٱلْأَوَّلِينَ","(of) the former (people)"]]],"1813":["(Dan tidak) sekali-kali (datang seorang rasul pun kepada mereka melainkan mereka selalu memperolok-olokkannya) sebagaimana kaummu memperolok-olokkanmu. Ayat ini dimaksudkan untuk menghibur hati Nabi saw.",[["وَمَا","And not"],["يَأْتِيهِم","came to them"],["مِّن","any"],["رَّسُولٍ","Messenger"],["إِلَّا","but"],["كَانُوا۟","they did"],["بِهِۦ","at him"],["يَسْتَهْزِءُونَ","mock"]]],"1814":["(Demikianlah Kami memasukkannya) artinya seperti itulah gambarannya bila Kami memasukkan ke dalam hati orang-orang kafir rasa ingkar dan memperolok-olokkan (ke dalam hati orang-orang yang berdosa) yaitu orang-orang kafir Mekah.",[["كَذَٰلِكَ","Thus"],["نَسْلُكُهُۥ","We let it enter"],["فِى","in"],["قُلُوبِ","(the) hearts"],["ٱلْمُجْرِمِينَ","(of) the criminals"]]],"1815":["(Mereka tidak beriman kepadanya) kepada Nabi saw. (dan sesungguhnya telah berlalu sunatullah terhadap orang-orang yang dahulu) artinya kebiasaan yang dilakukan oleh Allah swt. terhadap orang-orang yang tidak beriman, yaitu mengazab mereka disebabkan perbuatan dusta mereka terhadap nabi-nabi mereka. Orang-orang kafir Mekah pun akan mengalami hal yang serupa.",[["لَا","Not"],["يُؤْمِنُونَ","they believe"],["بِهِۦ ۖ","in it"],["وَقَدْ","and verily"],["خَلَتْ","have passed"],["سُنَّةُ","the way(s)"],["ٱلْأَوَّلِينَ","(of) the former (people)"]]],"1816":["(Dan seandainya Kami membukakan kepada mereka salah satu dari pintu-pintu langit, lalu mereka terus-menerus padanya) pada pintu tersebut (dalam keadaan naik) selalu naik.",[["وَلَوْ","And (even) if"],["فَتَحْنَا","We opened"],["عَلَيْهِم","to them"],["بَابًۭا","a gate"],["مِّنَ","from"],["ٱلسَّمَآءِ","the heaven"],["فَظَلُّوا۟","and they were to continue"],["فِيهِ","therein"],["يَعْرُجُونَ","(to) ascend"]]],"1817":["(Tentulah mereka berkata, \"Sesungguhnya benar-benar telah dikaburkan) telah ditutup (pandangan kami bahkan kami adalah orang-orang yang kena sihir.\") seolah-olah tampak hal itu di mata kami secara ilusi.",[["لَقَالُوٓا۟","They would surely say"],["إِنَّمَا","Only"],["سُكِّرَتْ","have been dazzled"],["أَبْصَـٰرُنَا","our eyes"],["بَلْ","Nay"],["نَحْنُ","we"],["قَوْمٌۭ","(are) a people"],["مَّسْحُورُونَ","bewitched"]]],"1818":["(Dan sesungguhnya Kami menciptakan gugusan bintang-bintang di langit) yang berjumlah dua belas, yaitu: Aries, Taurus, Gemini, Cancer, Leo, Virgo, Libra, Scorpio, Sagitarius, Capricorn, Aquarius dan Pisces. Bintang-bintang tersebut merupakan garis-garis peredaran daripada tujuh bintang yang beredar, yaitu Mars mempunyai garis edar pada bintang Aries dan bintang Scorpio; Venus mempunyai garis edar pada bintang Taurus dan bintang Libra; Utarid mempunyai garis edar pada bintang Gemini dan bintang Virgo; bulan mempunyai garis edar pada bintang Cancer; matahari mempunyai garis edar pada bintang Leo; Jupiter mempunyai garis edar pada bintang Sagitarius dan Pisces; Saturnus mempunyai garis edar pada bintang Capricorn dan Aquarius (dan Kami telah menghiasi langit itu) dengan bintang-bintang yang gemerlapan (bagi orang-orang yang memandang.)",[["وَلَقَدْ","And verily"],["جَعَلْنَا","We have placed"],["فِى","in"],["ٱلسَّمَآءِ","the heavens"],["بُرُوجًۭا","constellations"],["وَزَيَّنَّـٰهَا","and We have beautified it"],["لِلنَّـٰظِرِينَ","for the observers"]]],"1819":["(Dan Kami menjaganya) dengan meteor-meteor (dari tiap-tiap setan yang terkutuk) yang terlaknat.",[["وَحَفِظْنَـٰهَا","And We have protected it"],["مِن","from"],["كُلِّ","every"],["شَيْطَـٰنٍۢ","devil"],["رَّجِيمٍ","accursed"]]],"1820":["(Akan tetapi) tetapi (setan yang mencuri-curi berita yang dapat didengar) yang menyadapnya (maka ia pasti dikejar oleh semburan api yang terang) yakni bintang yang menyala terang dan dapat membakar atau menembus atau membuatnya cacat.",[["إِلَّا","Except"],["مَنِ","(one) who"],["ٱسْتَرَقَ","steals"],["ٱلسَّمْعَ","the hearing"],["فَأَتْبَعَهُۥ","then follows him"],["شِهَابٌۭ","a burning flame"],["مُّبِينٌۭ","clear"]]],"1821":["(Dan Kami telah menghamparkan bumi) telah membuatnya terbentang (dan Kami menjadikan padanya gunung-gunung) yang kokoh dan tegak supaya jangan bergerak-gerak mengguncangkan penduduknya (dan Kami tumbuhkan padanya segala sesuatu menurut ukuran) yang telah ditentukan secara pasti.",[["وَٱلْأَرْضَ","And the earth"],["مَدَدْنَـٰهَا","We have spread it"],["وَأَلْقَيْنَا","and [We] cast"],["فِيهَا","therein"],["رَوَٰسِىَ","firm mountains"],["وَأَنۢبَتْنَا","and [We] caused to grow"],["فِيهَا","therein"],["مِن","of"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["مَّوْزُونٍۢ","well-balanced"]]],"1822":["(Dan Kami telah menjadikan untuk kalian di muka bumi keperluan-keperluan hidup) berupa buah-buahan dan biji-bijian (dan) Kami jadikan pula untuk kalian (makhluk-makhluk yang kalian sekali-kali bukan pemberi rezeki kepadanya) yaitu berupa hamba-hamba sahaya, binatang-binatang dan berbagai macam jenis ternak; hanya Allahlah yang memberi rezeki kepada mereka.",[["وَجَعَلْنَا","And We have made"],["لَكُمْ","for you"],["فِيهَا","therein"],["مَعَـٰيِشَ","means of living"],["وَمَن","and whom"],["لَّسْتُمْ","you are not"],["لَهُۥ","for him"],["بِرَٰزِقِينَ","providers"]]],"1823":["(Dan tiada) tidak ada (sesuatu pun melainkan pada sisi Kamilah khazanahnya) huruf min adalah zaidah; yang dimaksud adalah kunci-kunci perbendaharaan segala sesuatu itu (dan Kami tidak menurunkannya melainkan dengan ukuran-ukuran yang tertentu) sesuai dengan kepentingan-kepentingannya.",[["وَإِن","And not"],["مِّن","(is) any"],["شَىْءٍ","thing"],["إِلَّا","but"],["عِندَنَا","with Us"],["خَزَآئِنُهُۥ","(are) its treasures"],["وَمَا","and not"],["نُنَزِّلُهُۥٓ","We send it down"],["إِلَّا","except"],["بِقَدَرٍۢ","in a measure"],["مَّعْلُومٍۢ","known"]]],"1824":["(Dan Kami telah meniupkan angin untuk mengumpulkan awan) menggiring mendung sehingga terkumpul lalu penuh dengan air (lalu Kami turunkan dari langit) dari mendung itu (air) air hujan (kemudian Kami beri minum kamu dengan air itu, dan sekali-kali bukanlah kalian yang menyimpannya) artinya, bukanlah kalian yang menyimpannya dengan upaya tangan kalian.",[["وَأَرْسَلْنَا","And We have sent"],["ٱلرِّيَـٰحَ","the winds"],["لَوَٰقِحَ","fertilizing"],["فَأَنزَلْنَا","and We sent down"],["مِنَ","from"],["ٱلسَّمَآءِ","the sky"],["مَآءًۭ","water"],["فَأَسْقَيْنَـٰكُمُوهُ","and We gave it to you to drink"],["وَمَآ","And not"],["أَنتُمْ","you"],["لَهُۥ","of it"],["بِخَـٰزِنِينَ","(are) retainers"]]],"1825":["(Dan sesungguhnya benar-benar Kamilah yang menghidupkan dan mematikan dan Kami pula yang mewarisi) yang tetap hidup dan mewarisi semua makhluk.",[["وَإِنَّا","And indeed, We"],["لَنَحْنُ","surely [We]"],["نُحْىِۦ","We give life"],["وَنُمِيتُ","and We cause death"],["وَنَحْنُ","and We"],["ٱلْوَٰرِثُونَ","(are) the Inheritors"]]],"1826":["(Dan sesungguhnya Kami telah mengetahui orang-orang yang terdahulu daripada kalian) yaitu makhluk-makhluk yang terdahulu sejak Nabi Adam (dan sesungguhnya Kami mengetahui pula orang-orang yang terkemudian) orang-orang yang akan datang kemudian hingga hari kiamat.",[["وَلَقَدْ","And verily"],["عَلِمْنَا","We know"],["ٱلْمُسْتَقْدِمِينَ","the preceding ones"],["مِنكُمْ","among you"],["وَلَقَدْ","and verily"],["عَلِمْنَا","We know"],["ٱلْمُسْتَـْٔخِرِينَ","the later ones"]]],"1827":["(Sesungguhnya Rabbmu, Dialah yang akan menghimpunkan mereka. Sesungguhnya Dia adalah Maha Bijaksana) di dalam pekerjaan-Nya (lagi Maha Mengetahui.) tentang makhluk-Nya.",[["وَإِنَّ","And indeed"],["رَبَّكَ","your Lord"],["هُوَ","He"],["يَحْشُرُهُمْ ۚ","will gather them"],["إِنَّهُۥ","Indeed, He"],["حَكِيمٌ","(is) All-Wise"],["عَلِيمٌۭ","All-Knowing"]]],"1828":["(Dan sesungguhnya Kami telah menciptakan manusia) yaitu Nabi Adam (dari tanah liat kering) tanah liat kering yang apabila diketuk akan terdengar daripadanya suara melenting (yang berasal dari lumpur hitam) tanah liat yang hitam (yang diberi bentuk) diubah bentuknya.",[["وَلَقَدْ","And verily"],["خَلَقْنَا","We created"],["ٱلْإِنسَـٰنَ","humankind"],["مِن","(out) of"],["صَلْصَـٰلٍۢ","sounding clay"],["مِّنْ","from"],["حَمَإٍۢ","black mud"],["مَّسْنُونٍۢ","altered"]]],"1829":["(Dan jin) maksudnya biangnya jin, yaitu iblis (Kami telah menciptakan sebelumnya) sebelum Nabi Adam diciptakan (dari api yang sangat panas) yaitu api yang sama sekali tidak berasap dan dapat menembus pori-pori.",[["وَٱلْجَآنَّ","And the jinn"],["خَلَقْنَـٰهُ","We created it"],["مِن","before"],["قَبْلُ","before"],["مِن","from"],["نَّارِ","fire"],["ٱلسَّمُومِ","scorching"]]],"1830":["(Dan) ingatlah (ketika Rabbmu berfirman kepada para malaikat, \"Sesungguhnya Aku akan menciptakan seorang manusia dari tanah liat kering yang berasal dan lumpur hitam yang diberi bentuk).",[["وَإِذْ","And when"],["قَالَ","your Lord said"],["رَبُّكَ","your Lord said"],["لِلْمَلَـٰٓئِكَةِ","to the Angels"],["إِنِّى","Indeed, I"],["خَـٰلِقٌۢ","(will) create"],["بَشَرًۭا","a human being"],["مِّن","(out) of"],["صَلْصَـٰلٍۢ","clay"],["مِّنْ","from"],["حَمَإٍۢ","black mud"],["مَّسْنُونٍۢ","altered"]]],"1831":["(Maka apabila Aku telah menyempurnakan kejadiannya) telah merampungkan bentuknya (dan Aku telah meniupkan) maksudnya telah mengalirkan (ke dalam tubuhnya roh ciptaan-Ku) sehingga ia menjadi hidup; diidhafatkannya lafal ruuh kepada-Nya sebagai penghormatan kepada Adam (maka tunduklah kalian kepadanya dengan bersujud) yaitu sujud penghormatan dengan cara membungkuk.",[["فَإِذَا","So, when"],["سَوَّيْتُهُۥ","I have fashioned him"],["وَنَفَخْتُ","and [I] breathed"],["فِيهِ","into him"],["مِن","of"],["رُّوحِى","My spirit"],["فَقَعُوا۟","then fall down"],["لَهُۥ","to him"],["سَـٰجِدِينَ","prostrating"]]],"1832":["(Maka bersujudlah para malaikat itu semuanya bersama-sama) di dalam ayat ini terdapat dua taukid, yaitu lafal kulluhum dan lafal ajma'uuna.",[["فَسَجَدَ","So prostrated"],["ٱلْمَلَـٰٓئِكَةُ","the Angels"],["كُلُّهُمْ","all of them"],["أَجْمَعُونَ","together"]]],"1833":["(Kecuali iblis) dia adalah biangnya jin yang dahulu hidup di antara para malaikat (ia enggan) menolak untuk (ikut bersama-sama malaikat yang sujud itu.\")",[["إِلَّآ","Except"],["إِبْلِيسَ","Iblis"],["أَبَىٰٓ","He refused"],["أَن","to"],["يَكُونَ","be"],["مَعَ","with"],["ٱلسَّـٰجِدِينَ","those who prostrated"]]],"1834":["(Allah berfirman) Maha Tinggi Allah (\"Hai iblis! Apa sebabnya kamu) apa yang menyebabkan kamu enggan (tidak mau) huruf laa adalah zaidah (ikut sujud bersama-sama mereka yang sujud itu?\")",[["قَالَ","He said"],["يَـٰٓإِبْلِيسُ","O Iblis"],["مَا","What"],["لَكَ","(is) for you"],["أَلَّا","that not"],["تَكُونَ","you are"],["مَعَ","with"],["ٱلسَّـٰجِدِينَ","those who prostrated"]]],"1835":["(Berkata iblis, \"Aku sekali-kali tidak akan sujud) tidak layak bagiku untuk sujud (kepada manusia yang Engkau telah menciptakannya dari tanah liat kering yang berasal dari lumpur hitam yang diberi bentuk.\")",[["قَالَ","He said"],["لَمْ","I am not"],["أَكُن","I am not"],["لِّأَسْجُدَ","(one) to prostrate"],["لِبَشَرٍ","to a human"],["خَلَقْتَهُۥ","whom You created"],["مِن","(out) of"],["صَلْصَـٰلٍۢ","clay"],["مِّنْ","from"],["حَمَإٍۢ","black mud"],["مَّسْنُونٍۢ","altered"]]],"1836":["(Allah berfirman, \"Keluarlah dari surga) menurut suatu pendapat dari langit (karena sesungguhnya kamu terkutuk.\") terusir.",[["قَالَ","He said"],["فَٱخْرُجْ","Then get out"],["مِنْهَا","of it"],["فَإِنَّكَ","for indeed, you"],["رَجِيمٌۭ","(are) expelled"]]],"1837":["(Dan sesungguhnya kutukan itu tetap menimpamu sampai hari kiamat) sampai hari pembalasan",[["وَإِنَّ","And indeed"],["عَلَيْكَ","upon you"],["ٱللَّعْنَةَ","(will be) the curse"],["إِلَىٰ","till"],["يَوْمِ","(the) Day"],["ٱلدِّينِ","(of) [the] Judgment"]]],"1838":["(Berkata iblis, \"Ya Rabbku! Kalau begitu maka beri tangguhlah kepadaku sampai hari dibangkitkan.\") nya manusia",[["قَالَ","He said"],["رَبِّ","O my Lord"],["فَأَنظِرْنِىٓ","Then give me respite"],["إِلَىٰ","till"],["يَوْمِ","(the) Day"],["يُبْعَثُونَ","they are raised"]]],"1839":["(Allah berfirman, \"Kalau begitu, maka sesungguhnya kamu termasuk orang-orang yang diberi tangguh).",[["قَالَ","He said"],["فَإِنَّكَ","Then indeed you"],["مِنَ","(are) of"],["ٱلْمُنظَرِينَ","the ones given respite"]]],"1840":["(sampai hari suatu waktu yang telah ditentukan.\") yaitu sampai tiupan sangkakala yang pertama.",[["إِلَىٰ","Till"],["يَوْمِ","the Day"],["ٱلْوَقْتِ","(of) the time"],["ٱلْمَعْلُومِ","well-known"]]],"1841":["(Iblis berkata, \"Ya Rabbku! Oleh sebab Engkau telah memutuskan bahwa aku sesat) artinya disebabkan Engkau telah menetapkan aku sesat; huruf ba pada lafal bimaa adalah bermakna qasam, sedangkan jawabnya ialah (pasti aku akan menjadikan mereka memandang baik di muka bumi ini) terhadap perbuatan-perbuatan maksiat (dan pasti aku akan menyesatkan mereka semuanya).",[["قَالَ","He said"],["رَبِّ","My Lord"],["بِمَآ","Because"],["أَغْوَيْتَنِى","You misled me"],["لَأُزَيِّنَنَّ","surely, I will make (evil) fair-seeming"],["لَهُمْ","to them"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَلَأُغْوِيَنَّهُمْ","and I will mislead them"],["أَجْمَعِينَ","all"]]],"1842":["(Kecuali hamba-hamba Engkau yang mukhlis di antara mereka\") yakni orang-orang yang beriman.",[["إِلَّا","Except"],["عِبَادَكَ","Your slaves"],["مِنْهُمُ","among them"],["ٱلْمُخْلَصِينَ","the ones who are sincere"]]],"1843":["(Berfirmanlah Allah) swt. (\"Inilah jalan yang lurus; kewajiban Akulah memeliharanya\")",[["قَالَ","He said"],["هَـٰذَا","This"],["صِرَٰطٌ","(is) the way"],["عَلَىَّ","to Me"],["مُسْتَقِيمٌ","straight"]]],"1844":["(Sesungguhnya hamba-hamba-Ku) yang beriman (tidak ada kekuasaan bagimu terhadap mereka) kamu tidak mempunyai kekuatan (kecuali) hanyalah (orang-orang yang mengikut kalian; yaitu orang-orang yang sesat) yakni orang-orang kafir.",[["إِنَّ","Indeed"],["عِبَادِى","My slaves"],["لَيْسَ","not"],["لَكَ","you have"],["عَلَيْهِمْ","over them"],["سُلْطَـٰنٌ","any authority"],["إِلَّا","except"],["مَنِ","those who"],["ٱتَّبَعَكَ","follow you"],["مِنَ","of"],["ٱلْغَاوِينَ","the ones who go astray"]]],"1845":["(Dan sesungguhnya Jahanam itu benar-benar tempat yang telah dijanjikan kepada mereka semuanya) yaitu kepada orang-orang yang mengikutimu.",[["وَإِنَّ","And indeed"],["جَهَنَّمَ","Hell"],["لَمَوْعِدُهُمْ","(is) surely the promised place for them"],["أَجْمَعِينَ","all"]]],"1846":["(Jahanam itu mempunyai tujuh pintu) tujuh lapis (Tiap-tiap pintu) daripadanya (adalah untuk segolongan di antara mereka bagian) yakni jatah (yang tertentu).",[["لَهَا","For it"],["سَبْعَةُ","(are) seven"],["أَبْوَٰبٍۢ","gates"],["لِّكُلِّ","for each"],["بَابٍۢ","gate"],["مِّنْهُمْ","among them"],["جُزْءٌۭ","(is) a portion"],["مَّقْسُومٌ","assigned"]]],"1847":["(Sesungguhnya orang-orang yang bertakwa itu berada di dalam surga) kebun-kebun surga (dan mata air-mata air) yang mengalir di dalamnya.",[["إِنَّ","Indeed"],["ٱلْمُتَّقِينَ","the righteous"],["فِى","(will be) in"],["جَنَّـٰتٍۢ","Gardens"],["وَعُيُونٍ","and water springs"]]],"1848":["Dan dikatakan kepada mereka (\"Masuklah ke dalamnya dengan sejahtera) dengan perasaan yang aman dari setiap hal yang menakutkan. Atau masuklah ke dalamnya dengan bersalam artinya, bersalamlah lalu masuklah (lagi aman\") dari setiap hal-hal yang mengerikan.",[["ٱدْخُلُوهَا","Enter it"],["بِسَلَـٰمٍ","in peace"],["ءَامِنِينَ","secure"]]],"1849":["(Dan Kami lenyapkan segala rasa dendam yang berada dalam hati mereka) maksudnya semua perasaan dengki (sedangkan mereka merasa bersaudara) lafal ikhwaanan ini menjadi hal tentang keadaan mereka (duduk berhadap-hadapan di atas dipan-dipan) kalimat ayat ini pun menggambarkan tentang keadaan mereka; artinya sebagian dari mereka tidak melihat kepada tengkuk sebagian yang lain karena tempat duduk mereka saling berhadap-hadapan.",[["وَنَزَعْنَا","And We (will) remove"],["مَا","what"],["فِى","(is) in"],["صُدُورِهِم","their breasts"],["مِّنْ","of"],["غِلٍّ","rancor"],["إِخْوَٰنًا","(they will be) brothers"],["عَلَىٰ","on"],["سُرُرٍۢ","thrones"],["مُّتَقَـٰبِلِينَ","facing each other"]]],"1850":["(Mereka tidak merasa lelah di dalamnya) tidak pernah merasa penat (dan mereka sekali-kali tidak akan dikeluarkan daripadanya) untuk selama-lamanya.",[["لَا","Not"],["يَمَسُّهُمْ","will touch them"],["فِيهَا","therein"],["نَصَبٌۭ","fatigue"],["وَمَا","and not"],["هُم","they"],["مِّنْهَا","from it"],["بِمُخْرَجِينَ","will be removed"]]],"1851":["(Kabarkanlah) beritakanlah, hai Muhammad (kepada hamba-hamba-Ku bahwa sesungguhnya Akulah Yang Maha Pengampun) terhadap orang-orang mukmin (lagi Maha Penyayang) terhadap mereka yang beriman.",[["۞ نَبِّئْ","Inform"],["عِبَادِىٓ","My slaves"],["أَنِّىٓ","that I"],["أَنَا","I am"],["ٱلْغَفُورُ","the Oft-Forgiving"],["ٱلرَّحِيمُ","the Most Merciful"]]],"1852":["(Dan bahwa sesungguhnya azab-Ku) terhadap orang-orang yang durhaka (adalah azab yang sangat pedih) sangat menyakitkan.",[["وَأَنَّ","And that"],["عَذَابِى","My punishment"],["هُوَ","it"],["ٱلْعَذَابُ","(is) the punishment"],["ٱلْأَلِيمُ","the most painful"]]],"1853":["(Dan kabarkanlah kepada mereka tentang tamu-tamu Ibrahim) yaitu malaikat-malaikat yang berjumlah dua belas malaikat, atau sepuluh malaikat, atau tiga malaikat yang salah satu di antara mereka adalah malaikat Jibril.",[["وَنَبِّئْهُمْ","And inform them"],["عَن","about"],["ضَيْفِ","(the) guests"],["إِبْرَٰهِيمَ","(of) Ibrahim"]]],"1854":["(Ketika mereka masuk ke tempatnya, lalu mereka mengucapkan, \"Salam.\") mereka mengucapkan lafal itu. (Berkata Ibrahim) ketika disuguhkan hidangan makanan kepada mereka, akan tetapi mereka tidak memakannya (\"Sesungguhnya kami merasa takut kepada kalian.\") yakni merasa ngeri.",[["إِذْ","When"],["دَخَلُوا۟","they entered"],["عَلَيْهِ","upon him"],["فَقَالُوا۟","and said"],["سَلَـٰمًۭا","Peace"],["قَالَ","He said"],["إِنَّا","Indeed, we"],["مِنكُمْ","(are) of you"],["وَجِلُونَ","afraid"]]],"1855":["(Mereka berkata, \"Janganlah kamu merasa takut) merasa ngeri terhadap kami (sesungguhnya kami) adalah utusan-utusan Rabbmu (memberi kabar gembira kepadamu dengan kelahiran seorang anak laki-laki yang akan menjadi orang yang alim.\") anak yang mempunyai ilmu yang banyak, yaitu Nabi Ishak, seperti yang telah kami sebutkan dalam surah Hud.",[["قَالُوا۟","They said"],["لَا","(Do) not"],["تَوْجَلْ","be afraid"],["إِنَّا","indeed, we"],["نُبَشِّرُكَ","[we] bring glad tidings to you"],["بِغُلَـٰمٍ","of a boy"],["عَلِيمٍۢ","learned"]]],"1856":["(Berkata Ibrahim, \"Apakah kalian memberi kabar gembira kepadaku) dengan melahirkan seorang anak (padahal usiaku telah lanjut) kalimat ini menjadi hal; artinya padahal usia tua telah kualami (maka dengan cara manakah) dengan cara apakah (terlaksananya berita gembira seperti apa yang kalian katakan itu?\") Istifham di sini mengandung makna takjub.",[["قَالَ","He said"],["أَبَشَّرْتُمُونِى","Do you give me glad tidings"],["عَلَىٰٓ","Do you give me glad tidings"],["أَن","although"],["مَّسَّنِىَ","has overtaken me"],["ٱلْكِبَرُ","old age"],["فَبِمَ","Then about what"],["تُبَشِّرُونَ","you give glad tidings"]]],"1857":["(Mereka berkata, \"Kami menyampaikan kabar gembira kepadamu dengan benar) dengan sungguh-sungguh (maka janganlah kamu termasuk orang-orang yang berputus asa.\") putus harapan.",[["قَالُوا۟","They said"],["بَشَّرْنَـٰكَ","We give you glad tidings"],["بِٱلْحَقِّ","in truth"],["فَلَا","so (do) not"],["تَكُن","be"],["مِّنَ","of"],["ٱلْقَـٰنِطِينَ","the despairing"]]],"1858":["(Ibrahim berkata, \"Tiada) tidak ada (orang orang berputus asa) dapat dibaca yaqnithu dan yaqnathu (dari rahmat Rabbnya melainkan orang-orang yang sesat.\") yakni orang-orang kafir.",[["قَالَ","He said"],["وَمَن","And who"],["يَقْنَطُ","despairs"],["مِن","of"],["رَّحْمَةِ","(the) Mercy"],["رَبِّهِۦٓ","(of) his Lord"],["إِلَّا","except"],["ٱلضَّآلُّونَ","those who are astray"]]],"1859":["(Berkata pula Ibrahim, \"Apakah urusan kalian) yakni kepentingan kalian (hai para utusan?\").",[["قَالَ","He said"],["فَمَا","Then what"],["خَطْبُكُمْ","(is) your business"],["أَيُّهَا","O messengers"],["ٱلْمُرْسَلُونَ","O messengers"]]],"1860":["(Mereka menjawab, \"Kami sesungguhnya diutus kepada kaum yang berdosa) orang-orang kafir, yang dimaksud adalah kaum Nabi Luth, untuk membinasakan mereka.",[["قَالُوٓا۟","They said"],["إِنَّآ","Indeed, we"],["أُرْسِلْنَآ","[we] have been sent"],["إِلَىٰ","to"],["قَوْمٍۢ","a people "],["مُّجْرِمِينَ","criminals"]]],"1861":["(Kecuali Luth dan pengikut-pengikutnya. Sesungguhnya Kami akan menyelamatkan mereka-semuanya) karena mereka adalah orang-orang yang beriman.",[["إِلَّآ","Except"],["ءَالَ","the family"],["لُوطٍ","of Lut"],["إِنَّا","indeed, we"],["لَمُنَجُّوهُمْ","surely will save them"],["أَجْمَعِينَ","all"]]],"1862":["(Kecuali istrinya, kami telah menentukan, bahwa sesungguhnya ia itu termasuk orang-orang yang tertinggal.\") bersama orang-rang kafir lainnya yang tertimpa azab.",[["إِلَّا","Except"],["ٱمْرَأَتَهُۥ","his wife"],["قَدَّرْنَآ ۙ","We have decreed"],["إِنَّهَا","that she"],["لَمِنَ","(is) surely of"],["ٱلْغَـٰبِرِينَ","those who remain behind"]]],"1863":["(Maka tatkala datang kepada kaum Luth) yang dimaksud adalah Nabi Luth (para utusan itu).",[["فَلَمَّا","And when"],["جَآءَ","came"],["ءَالَ","(to the) family"],["لُوطٍ","(of) Lut"],["ٱلْمُرْسَلُونَ","the messengers"]]],"1864":["(Ia berkata) kepada para utusan itu (\"Sesungguhnya kalian adalah orang-orang yang tidak dikenal.\")",[["قَالَ","He said"],["إِنَّكُمْ","Indeed, you"],["قَوْمٌۭ","(are) a people"],["مُّنكَرُونَ","unknown"]]],"1865":["(Para utusan menjawab, \"Sebenarnya kami ini datang kepadamu dengan membawa apa yang mereka) yakni kaummu (mendustakannya.\") mereka meragukan tentangnya; subjek yang dimaksud adalah azab.",[["قَالُوا۟","They said"],["بَلْ","Nay"],["جِئْنَـٰكَ","we have come to you"],["بِمَا","with what"],["كَانُوا۟","they were"],["فِيهِ","in it"],["يَمْتَرُونَ","disputing"]]],"1866":["(\"Dan kami datang kepadamu membawa kebenaran dan sesungguhnya kami betul-betul orang-orang yang benar.\") di dalam pengakuan kami ini.",[["وَأَتَيْنَـٰكَ","And we have come to you"],["بِٱلْحَقِّ","with the truth"],["وَإِنَّا","and indeed, we"],["لَصَـٰدِقُونَ","surely (are) truthful"]]],"1867":["(Maka pergilah kamu di akhir malam dengan membawa keluargamu dan ikutilah mereka dari belakang) berjalanlah kamu di belakang keluargamu (dan janganlah seorang pun di antara kalian menoleh ke belakang) supaya ia tidak melihat besarnya azab yang menimpa mereka (dan teruskanlah perjalanan ke tempat yang diperintahkan kepada kalian) yaitu negeri Syam.",[["فَأَسْرِ","So travel"],["بِأَهْلِكَ","with your family"],["بِقِطْعٍۢ","in a portion"],["مِّنَ","of"],["ٱلَّيْلِ","the night"],["وَٱتَّبِعْ","and follow"],["أَدْبَـٰرَهُمْ","their backs"],["وَلَا","and not"],["يَلْتَفِتْ","let look back"],["مِنكُمْ","among you"],["أَحَدٌۭ","anyone"],["وَٱمْضُوا۟","and go on"],["حَيْثُ","where"],["تُؤْمَرُونَ","you are ordered"]]],"1868":["(Dan telah Kami putuskan) telah Kami wahyukan (kepada Luth perkara itu) yaitu (bahwa mereka akan ditumpas habis di waktu subuh) lafal mushbihiin menjadi hal; artinya pembinasaan mereka dilakukan pada waktu subuh.",[["وَقَضَيْنَآ","And We conveyed"],["إِلَيْهِ","to him"],["ذَٰلِكَ","[that]"],["ٱلْأَمْرَ","the matter"],["أَنَّ","that"],["دَابِرَ","(the) root"],["هَـٰٓؤُلَآءِ","(of) these"],["مَقْطُوعٌۭ","would be cut off"],["مُّصْبِحِينَ","(by) early morning"]]],"1869":["(Dan datanglah penduduk kota) yaitu kota Sodom yang para penduduknya adalah kaum Nabi Luth; mereka datang sewaktu mendengar bahwa di dalam rumah Nabi Luth terdapat beberapa laki-laki tampan yang masih muda-muda, mereka adalah para malaikat itu (dengan gembira) lafal yastabsyiruun menjadi hal, artinya keadaan mereka sangat gembira sekali dengan kedatangan para tamu itu, karena mereka berniat untuk melampiaskan nafsu homonya terhadap tamu-tamu itu.",[["وَجَآءَ","And came"],["أَهْلُ","(the) people"],["ٱلْمَدِينَةِ","(of) the city"],["يَسْتَبْشِرُونَ","rejoicing"]]],"1870":["(Ia berkata) yakni Nabi Luth (\"Sesungguhnya mereka adalah tamuku; maka janganlah kalian memberi malu kepadaku.\")",[["قَالَ","He said"],["إِنَّ","Indeed"],["هَـٰٓؤُلَآءِ","these"],["ضَيْفِى","(are) my guests"],["فَلَا","so (do) not"],["تَفْضَحُونِ","shame me"]]],"1871":["(\"Dan bertakwalah kepada Allah dan janganlah kalian membuat aku terhina.\") dengan niat kalian yang ingin melampiaskan nafsu homo kalian terhadap mereka itu.",[["وَٱتَّقُوا۟","And fear"],["ٱللَّهَ","Allah"],["وَلَا","and (do) not"],["تُخْزُونِ","disgrace me"]]],"1872":["(Mereka berkata, \"Bukankah kami telah melarangmu dari menerima manusia?\") yakni menerima mereka sebagai tamumu.",[["قَالُوٓا۟","They said"],["أَوَلَمْ","Did not"],["نَنْهَكَ","we forbid you"],["عَنِ","from"],["ٱلْعَـٰلَمِينَ","the world"]]],"1873":["(Luth berkata, \"Inilah putri-putriku, jika kalian hendak berbuat,\") untuk melampiaskan nafsu syahwat kalian, oleh sebab itu maka kawinilah mereka. Lalu Allah berfirman:",[["قَالَ","He said"],["هَـٰٓؤُلَآءِ","These"],["بَنَاتِىٓ","(are) my daughters"],["إِن","if"],["كُنتُمْ","you would be"],["فَـٰعِلِينَ","doers"]]],"1874":["(\"Demi umurmu) khithab atau pembicaraan ini ditujukan kepada Nabi saw.; artinya demi hidupmu (sesungguhnya mereka terombang-ambing di dalam kemabukan atau kesesatan\") yakni mereka bergelimang di dalam kesesatannya.",[["لَعَمْرُكَ","By your life"],["إِنَّهُمْ","indeed, they"],["لَفِى","were in"],["سَكْرَتِهِمْ","their intoxication"],["يَعْمَهُونَ","wandering blindly"]]],"1875":["(Maka mereka dibinasakan oleh suara keras yang mengguntur) oleh suara keras malaikat Jibril (ketika matahari akan terbit).",[["فَأَخَذَتْهُمُ","So, seized them"],["ٱلصَّيْحَةُ","the awful cry"],["مُشْرِقِينَ","at sunrise"]]],"1876":["(Maka Kami jadikan bagian atasnya) yakni bagian atas kota mereka (terbalik ke bawah) malaikat Jibril mengangkatnya ke langit kemudian menjatuhkannya dalam keadaan terbalik ke tanah (dan Kami hujani mereka dengan batu dari tanah yang keras) yaitu tanah liat yang dibakar dengan api.",[["فَجَعَلْنَا","And We made"],["عَـٰلِيَهَا","its highest (part)"],["سَافِلَهَا","its lowest"],["وَأَمْطَرْنَا","and We rained"],["عَلَيْهِمْ","upon them"],["حِجَارَةًۭ","stones"],["مِّن","of"],["سِجِّيلٍ","baked clay"]]],"1877":["(Sesungguhnya pada yang demikian itu) hal yang telah disebutkan itu (benar-benar terdapat tanda-tanda) yang menunjukkan kepada keesaan Allah (bagi orang-orang yang memperhatikan tanda-tanda) bagi orang-orang yang mau memperhatikannya kemudian mau mengambilnya sebagai pelajaran.",[["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَـٰتٍۢ","(are) the Signs"],["لِّلْمُتَوَسِّمِينَ","for those who discern"]]],"1878":["(Dan sesungguhnya kota itu) yaitu kota kaum Nabi Luth (benar-benar terletak di jalan yang masih tetap dilalui manusia) yakni jalan yang masih dipakai oleh orang-orang Quraisy untuk menuju ke negeri Syam; jalan itu masih tetap ada; mengapa mereka tidak mau menjadikannya sebagai pelajaran?",[["وَإِنَّهَا","And indeed, it"],["لَبِسَبِيلٍۢ","(is) on a road"],["مُّقِيمٍ","established"]]],"1879":["(Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda) yakni pelajaran-pelajaran (bagi orang-orang yang beriman).",[["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَةًۭ","surely (is) a Sign"],["لِّلْمُؤْمِنِينَ","for the believers"]]],"1880":["(Dan sesungguhnya) lafal in adalah bentuk takhfif daripada inna (adalah penduduk Aikah itu) yang terkenal dengan pohon-pohonnya yang subur dan rindang, terletak di dekat kota Madyan, dan mereka adalah kaum Nabi Syuaib (benar-benar kaum yang zalim) disebabkan mereka mendustakan Nabi Syuaib.",[["وَإِن","And were"],["كَانَ","And were"],["أَصْحَـٰبُ","(the) companions"],["ٱلْأَيْكَةِ","(of) the wood"],["لَظَـٰلِمِينَ","surely wrongdoers"]]],"1881":["(Maka Kami membalas perbuatan mereka itu) yaitu membinasakan mereka dengan musim panas yang sangat (Dan sesungguhnya kedua kota itu) yaitu kota kaum Nabi Luth dan kota kaum Nabi Syuaib (benar-benar terletak di jalan umum) yakni jalan raya (yang terang) jelas; mengapa kalian hai penduduk Mekah tidak mau mengambil pelajaran daripadanya?",[["فَٱنتَقَمْنَا","So We took retribution"],["مِنْهُمْ","from them"],["وَإِنَّهُمَا","and indeed, they both"],["لَبِإِمَامٍۢ","(were) on a highway"],["مُّبِينٍۢ","clear"]]],"1882":["(Dan sesungguhnya penduduk kota Al-Hijr telah mendustakan) Al-Hijr, nama sebuah lembah yang terletak di antara kota Madinah dan negeri Syam; tempatnya kaum Tsamud (rasul-rasulnya) mereka mendustakan nabi mereka yaitu Nabi Saleh, hal ini berarti sama saja dengan mendustakan rasul-rasul lainnya, karena sesungguhnya ajaran yang disampaikan oleh para rasul itu pada hakikatnya sama, yaitu ajaran tauhid.",[["وَلَقَدْ","And certainly"],["كَذَّبَ","denied"],["أَصْحَـٰبُ","(the) companions"],["ٱلْحِجْرِ","(of) the Rocky Tract"],["ٱلْمُرْسَلِينَ","the Messengers"]]],"1883":["(Dan Kami telah mendatangkan kepada mereka tanda-tanda kekuasaan Kami) melalui seekor unta betina tetapi mereka selalu berpaling daripadanya) tidak mau memikirkan tentangnya.",[["وَءَاتَيْنَـٰهُمْ","And We gave them"],["ءَايَـٰتِنَا","Our Signs"],["فَكَانُوا۟","but they were"],["عَنْهَا","from them"],["مُعْرِضِينَ","turning away"]]],"1884":["(Dan mereka memahat rumah-rumah dari gunung-gunung batu yang didiami dengan aman.)",[["وَكَانُوا۟","And they used (to)"],["يَنْحِتُونَ","carve"],["مِنَ","from"],["ٱلْجِبَالِ","the mountains"],["بُيُوتًا","houses"],["ءَامِنِينَ","secure"]]],"1885":["(Maka mereka dibinasakan oleh suara keras yang mengguntur di waktu pagi) pada waktu subuh.",[["فَأَخَذَتْهُمُ","But seized them"],["ٱلصَّيْحَةُ","the awful cry"],["مُصْبِحِينَ","(at) early morning"]]],"1886":["(Maka tidak dapat menolong) tidak dapat menolak (mereka) daripada azab (apa yang telah mereka usahakan) yaitu berupa bangunan-bangunan benteng dan harta benda yang mereka miliki dan mereka kumpulkan itu.",[["فَمَآ","And not"],["أَغْنَىٰ","availed"],["عَنْهُم","them"],["مَّا","what"],["كَانُوا۟","they used (to)"],["يَكْسِبُونَ","earn"]]],"1887":["(Dan tidaklah Kami ciptakan langit dan bumi dan apa yang ada di antara keduanya melainkan dengan benar. Dan sesungguhnya hari kiamat itu pasti akan datang) setiap orang akan menemukan pembalasan amal perbuatannya (maka maafkanlah) hai Muhammad kaummu (dengan cara yang baik) berpalinglah engkau dari mereka tanpa dibarengi dengan rasa menggerutu; akan tetapi ayat ini dinasakh oleh ayat yang memerintahkan memerangi mereka.",[["وَمَا","And not"],["خَلَقْنَا","We created"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضَ","and the earth"],["وَمَا","and whatever"],["بَيْنَهُمَآ","(is) between them"],["إِلَّا","except"],["بِٱلْحَقِّ ۗ","in truth"],["وَإِنَّ","And indeed"],["ٱلسَّاعَةَ","the Hour"],["لَـَٔاتِيَةٌۭ ۖ","(is) surely coming"],["فَٱصْفَحِ","So overlook"],["ٱلصَّفْحَ","(with) forgiveness"],["ٱلْجَمِيلَ","gracious"]]],"1888":["(Sesungguhnya Rabbmu, Dialah Yang Maha Pencipta) segala sesuatu (lagi Maha Mengetahui) segala sesuatu.",[["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["هُوَ","He"],["ٱلْخَلَّـٰقُ","(is) the Creator"],["ٱلْعَلِيمُ","the All-Knower"]]],"1889":["(Dan sesungguhnya Kami telah berikan kepadamu tujuh ayat yang dibaca berulang-ulang) Nabi saw. telah bersabda bahwa yang dimaksud adalah surah Al-Fatihah. Demikianlah menurut riwayat yang dikemukakan oleh Bukhari dan Muslim; surah Al-Fatihah dinamakan demikian karena selalu dibaca berulang-ulang dalam setiap salat (dan Alquran yang agung).",[["وَلَقَدْ","And certainly"],["ءَاتَيْنَـٰكَ","We have given you"],["سَبْعًۭا","seven"],["مِّنَ","of"],["ٱلْمَثَانِى","the oft-repeated"],["وَٱلْقُرْءَانَ","and the Quran"],["ٱلْعَظِيمَ","Great"]]],"1890":["(Janganlah sekali-kali kamu menunjukkan pandangan matamu kepada berbagai macam kenikmatan hidup yang telah Kami berikan kepada beberapa golongan) maksudnya terhadap berbagai macam kemewahan hidup (di antara mereka, dan janganlah kamu bersedih hati terhadap mereka) jika mereka tidak beriman (dan berendah dirilah kamu) bersikap lembutlah kamu (terhadap orang-orang yang beriman.)",[["لَا","(Do) not"],["تَمُدَّنَّ","extend"],["عَيْنَيْكَ","your eyes"],["إِلَىٰ","towards"],["مَا","what"],["مَتَّعْنَا","We have bestowed"],["بِهِۦٓ","with it"],["أَزْوَٰجًۭا","(to) categories"],["مِّنْهُمْ","of them"],["وَلَا","and (do) not"],["تَحْزَنْ","grieve"],["عَلَيْهِمْ","over them"],["وَٱخْفِضْ","And lower"],["جَنَاحَكَ","your wing"],["لِلْمُؤْمِنِينَ","to the believers"]]],"1891":["(Dan katakanlah, \"Sesungguhnya aku adalah pemberi peringatan) tentang azab Allah supaya jangan menimpa kalian (yang menjelaskan.\") artinya yang jelas peringatannya.",[["وَقُلْ","And say"],["إِنِّىٓ","Indeed, I"],["أَنَا","[I] am"],["ٱلنَّذِيرُ","a warner"],["ٱلْمُبِينُ","clear"]]],"1892":["(Sebagaimana Kami telah menurunkan) azab (kepada orang-orang yang membagi-bagi kitab Allah) yaitu Yahudi dan Nasrani.",[["كَمَآ","As"],["أَنزَلْنَا","We sent down"],["عَلَى","on"],["ٱلْمُقْتَسِمِينَ","those who divided"]]],"1893":["(Yaitu orang-orang yang telah menjadikan kitab bacaan) yaitu kitab-kitab yang diturunkan kepada mereka (terbagi-bagi) menjadi beberapa bagian; mereka beriman terhadap sebagiannya dan ingkar terhadap sebagian yang lainnya. Menurut pendapat orang lain dikatakan, yang dimaksud dengan mereka adalah orang-orang yang menguasai jalan-jalan yang menuju ke Mekah dengan maksud untuk menghalang-halangi manusia masuk Islam. Sebagian dari mereka mengatakan tentang Alquran, bahwa Alquran itu adalah sihir; sebagian lainnya mengatakan, Alquran adalah peramal; sedangkan sebagian yang lainnya lagi mengatakan, bahwa Alquran adalah syair.",[["ٱلَّذِينَ","Those who"],["جَعَلُوا۟","have made"],["ٱلْقُرْءَانَ","the Quran"],["عِضِينَ","(in) parts"]]],"1894":["(Maka demi Rabbmu, Kami pasti akan menanyai mereka semuanya) dengan pertanyaan yang bernada mengejek.",[["فَوَرَبِّكَ","So by your Lord"],["لَنَسْـَٔلَنَّهُمْ","surely We will question them"],["أَجْمَعِينَ","all"]]],"1895":["(Tentang apa yang telah mereka kerjakan dahulu.)",[["عَمَّا","About what"],["كَانُوا۟","they used (to)"],["يَعْمَلُونَ","do"]]],"1896":["(Maka sampaikanlah olehmu secara terang-terangan) hai Muhammad (segala apa yang diperintahkan kepadamu) untuk melakukannya, artinya sampaikanlah secara terang-terangan dan laksanakanlah dengan rutin (dan berpalinglah dari orang-orang yang musyrik) ayat ini diturunkan sebelum diperintahkan untuk berjihad.",[["فَٱصْدَعْ","So proclaim"],["بِمَا","of what"],["تُؤْمَرُ","you are ordered"],["وَأَعْرِضْ","and turn away"],["عَنِ","from"],["ٱلْمُشْرِكِينَ","the polytheists"]]],"1897":["(Sesungguhnya Kami memelihara kamu daripada kejahatan orang-orang yang memperolok-olokkan) kamu, Kami akan membinasakan masing-masing dari mereka dengan malapetaka. Mereka yang memperolok-olokkan ialah Walid bin Mughirah, Ashi bin Wa'il, Addi bin Qais, Aswad bin Abdul Mutthalib dan Aswad bin Abdu Yaghuts.",[["إِنَّا","Indeed, We"],["كَفَيْنَـٰكَ","[We] are sufficient for you"],["ٱلْمُسْتَهْزِءِينَ","(against) the mockers"]]],"1898":["(Yaitu orang-orang yang menganggap adanya tuhan yang lain di samping Allah) kalimat ayat ini berkedudukan menjadi sifat. Akan tetapi menurut suatu pendapat dianggap sebagai mubtada, oleh karena mengandung makna syarat, maka khabarnya dimasuki huruf fa, yaitu (maka mereka kelak akan mengetahui) akibat-akibat perbuatannya itu.",[["ٱلَّذِينَ","Those who"],["يَجْعَلُونَ","set up"],["مَعَ","with"],["ٱللَّهِ","Allah"],["إِلَـٰهًا","god"],["ءَاخَرَ ۚ","another"],["فَسَوْفَ","But soon"],["يَعْلَمُونَ","they will come to know"]]],"1899":["(Dan sungguh) lafal qad menunjukkan makna littahqiq (Kami telah mengetahui, bahwa dadamu menjadi sempit disebabkan apa yang mereka katakan) yaitu disebabkan perolok-olokkan dan pendustaan mereka itu.",[["وَلَقَدْ","And verily"],["نَعْلَمُ","We know"],["أَنَّكَ","that [you]"],["يَضِيقُ","(is) straitened"],["صَدْرُكَ","your breast"],["بِمَا","by what"],["يَقُولُونَ","they say"]]],"1900":["(Maka bertasbihlah) seraya (memuji Rabbmu) artinya katakanlah subhaanallaah wa bihamdihi (dan jadilah kamu di antara orang-orang yang bersujud) yakni orang-orang yang mendirikan salat.",[["فَسَبِّحْ","So glorify"],["بِحَمْدِ","with the praise"],["رَبِّكَ","(of) your Lord"],["وَكُن","and be"],["مِّنَ","of"],["ٱلسَّـٰجِدِينَ","those who prostrate"]]],"1901":["(Dan sembahlah Rabbmu sampai datang kepadamu yang diyakini) yaitu ajal.",[["وَٱعْبُدْ","And worship"],["رَبَّكَ","your Lord"],["حَتَّىٰ","until"],["يَأْتِيَكَ","comes to you"],["ٱلْيَقِينُ","the certainty"]]],"1902":["Ketika orang-orang musyrik merasa lambat akan datangnya azab yang diancamkan kepada mereka, lalu turunlah firman-Nya: (Telah pasti datangnya ketetapan Allah) yakni hari kiamat. Lafal ataa diungkapkan dalam bentuk fi`il madhi untuk menunjukkan kepastian kejadiannya, artinya telah dekat (maka janganlah kalian meminta disegerakan datangnya) artinya janganlah kalian meminta disegerakan sebelum saatnya karena sesungguhnya hari kiamat itu pasti akan terjadi (Maha Suci Allah) kalimat ini mengandung makna memahasucikan Dia (dan Maha Tinggi dari apa yang mereka persekutukan) di samping-Nya.",[["أَتَىٰٓ","Will come"],["أَمْرُ","(the) command of Allah"],["ٱللَّهِ","(the) command of Allah"],["فَلَا","so (do) not"],["تَسْتَعْجِلُوهُ ۚ","(be) impatient for it"],["سُبْحَـٰنَهُۥ","Glorified is He"],["وَتَعَـٰلَىٰ","and Exalted (is) He"],["عَمَّا","above what"],["يُشْرِكُونَ","they associate"]]],"1903":["(Dia menurunkan malaikat) yakni malaikat Jibril (dengan wahyu) dengan membawa wahyu (atas perintah-Nya) berdasarkan kehendak-Nya (kepada siapa yang Dia kehendaki di antara hamba-hamba-Nya) mereka adalah para nabi (yaitu) huruf an di sini bermakna mufassirah atau kata penafsir (peringatkanlah olehmu sekalian) peringatkanlah orang-orang kafir dengan azab, dan beritahukanlah kepada mereka (bahwasanya tidak ada Tuhan melainkan Aku, maka hendaklah kalian bertakwa kepada-Ku) artinya takutlah kalian kepada-Ku.",[["يُنَزِّلُ","He sends down"],["ٱلْمَلَـٰٓئِكَةَ","the Angels"],["بِٱلرُّوحِ","with the inspiration"],["مِنْ","of"],["أَمْرِهِۦ","His Command"],["عَلَىٰ","upon"],["مَن","whom"],["يَشَآءُ","He wills"],["مِنْ","of"],["عِبَادِهِۦٓ","His slaves"],["أَنْ","that"],["أَنذِرُوٓا۟","Warn"],["أَنَّهُۥ","that [He]"],["لَآ","(there is) no"],["إِلَـٰهَ","god"],["إِلَّآ","except"],["أَنَا۠","Me"],["فَٱتَّقُونِ","so fear Me"]]],"1904":["(Dia menciptakan langit dan bumi dengan hak) artinya secara sungguh-sungguh. (Maha Tinggi Allah daripada apa yang mereka persekutukan) bersama-Nya yaitu berhala-berhala.",[["خَلَقَ","He created"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضَ","and the earth"],["بِٱلْحَقِّ ۚ","in truth"],["تَعَـٰلَىٰ","Exalted is He"],["عَمَّا","above what"],["يُشْرِكُونَ","they associate"]]],"1905":["(Dia telah menciptakan manusia dari mani) mulai dari mani hingga menjadi manusia yang kuat lagi kekar (tiba-tiba ia menjadi pembantah) sangat memusuhi (yang nyata) lalu Allah menjelaskan tentang bantahan manusia itu yang tidak mempercayai adanya hari berbangkit, yaitu melalui firman-Nya yang lain: \"Siapakah yang dapat menghidupkan tulang-belulang yang telah hancur luluh.\" (Q.S. Yasin 78)",[["خَلَقَ","He created"],["ٱلْإِنسَـٰنَ","the human kind"],["مِن","from"],["نُّطْفَةٍۢ","a minute quantity of semen"],["فَإِذَا","then behold"],["هُوَ","he"],["خَصِيمٌۭ","(is) an opponent"],["مُّبِينٌۭ","clear"]]],"1906":["(Dan binatang ternak) yakni unta, sapi dan kambing. Lafal al-an`aam dibaca nashab karena dinashabkan oleh fi`il yang diperkirakan keberadaannya lalu fi`il tersebut ditafsirkan atau dijelaskan oleh lafal berikut ini, yaitu: (Dia telah menciptakannya untuk kalian) sebagian dari manusia (padanya ada kehangatan) yaitu bulu dan kulitnya dapat dibuat pakaian dan selimut untuk penghangat tubuh kalian (dan berbagai manfaat) yaitu dari anak-anaknya, air susunya dan dapat dijadikan sebagai kendaraan (dan sebagiannya kalian makan) zharaf didahulukan karena untuk tujuan fashilah.",[["وَٱلْأَنْعَـٰمَ","And the cattle"],["خَلَقَهَا ۗ","He created them"],["لَكُمْ","for you"],["فِيهَا","in them"],["دِفْءٌۭ","(is) warmth"],["وَمَنَـٰفِعُ","and benefits"],["وَمِنْهَا","and from them"],["تَأْكُلُونَ","you eat"]]],"1907":["(Dan kalian memperoleh pandangan yang indah padanya) yakni sebagai perhiasan kalian (ketika kalian membawanya kembali ke kandang) ketika kalian menggiringnya kembali ke kandangnya di waktu sore hari (dan ketika kalian melepaskannya ke tempat penggembalaan) kalian mengeluarkannya dari kandangnya menuju ke tempat penggembalaan di waktu pagi hari.",[["وَلَكُمْ","And for you"],["فِيهَا","in them"],["جَمَالٌ","(is) beauty"],["حِينَ","when"],["تُرِيحُونَ","you bring them in"],["وَحِينَ","and when"],["تَسْرَحُونَ","you take them out"]]],"1908":["(Dan ia dapat memikul beban-beban kalian) barang-barang kalian (ke suatu negeri yang kalian tidak sanggup sampai kepadanya) kalian tidak sanggup mencapainya tanpa memakai kendaraan unta (melainkan dengan kesukaran-kesukaran yang memayahkan diri) yang membuat payah diri kalian. (Sesungguhnya Rabb kalian benar-benar Maha Pengasih lagi Maha Penyayang) terhadap kalian, Dia telah menciptakannya untuk kalian manfaatkan.",[["وَتَحْمِلُ","And they carry"],["أَثْقَالَكُمْ","your loads"],["إِلَىٰ","to"],["بَلَدٍۢ","a land"],["لَّمْ","not"],["تَكُونُوا۟","you could"],["بَـٰلِغِيهِ","reach it"],["إِلَّا","except"],["بِشِقِّ","with great trouble"],["ٱلْأَنفُسِ ۚ","(to) yourselves"],["إِنَّ","Indeed"],["رَبَّكُمْ","your Lord"],["لَرَءُوفٌۭ","surely is Most Kind"],["رَّحِيمٌۭ","Most Merciful"]]],"1909":["(Dan) Dia telah menciptakan (kuda, bighal dan keledai agar kalian menungganginya dan menjadikannya sebagai perhiasan) lafal ziinatan menjadi maf`ul lah. Disebutkannya kedua `illat itu, yaitu untuk ditunggangi dan dianggap sebagai perhiasan hal ini sama sekali tidak bertentangan dengan manfaat lain yang ada padanya. Seperti halnya pada kuda, selain dapat ditunggangi dan dijadikan perhiasan dagingnya dapat dimakan, hal ini telah ditetapkan berdasarkan hadis kitab Sahih Bukhari dan Muslim. (Dan Allah menciptakan apa yang kalian tidak mengetahuinya) berupa hal-hal yang aneh dan menakjubkan.",[["وَٱلْخَيْلَ","And horses"],["وَٱلْبِغَالَ","and mules"],["وَٱلْحَمِيرَ","and donkeys"],["لِتَرْكَبُوهَا","for you to ride them"],["وَزِينَةًۭ ۚ","and (as) adornment"],["وَيَخْلُقُ","And He creates"],["مَا","what"],["لَا","not"],["تَعْلَمُونَ","you know"]]],"1910":["(Dan hak bagi Allah menerangkan jalan yang lurus) hak bagi Allah menjelaskannya (dan di antara jalan-jalan) tersebut (ada yang bengkok) menyimpang dari jalan yang lurus. (Dan jika Dia menghendaki) untuk memberi petunjuk kepada kalian (niscaya Dia memberi petunjuk kepada kalian) ke jalan yang lurus (semuanya) sehingga kalian semua mendapat petunjuk ke jalan yang lurus itu atas kehendak kalian sendiri.",[["وَعَلَى","And upon"],["ٱللَّهِ","Allah"],["قَصْدُ","(is) the direction"],["ٱلسَّبِيلِ","(of) the way"],["وَمِنْهَا","and among them"],["جَآئِرٌۭ ۚ","(are) crooked"],["وَلَوْ","And if"],["شَآءَ","He willed"],["لَهَدَىٰكُمْ","surely He would have guided you"],["أَجْمَعِينَ","all"]]],"1911":["(Dialah Yang telah menurunkan air hujan itu dari langit untuk kalian, sebagiannya menjadi minuman) untuk kalian minum (dan sebagiannya menjadi tumbuh-tumbuhan) maksudnya oleh sebab air itu menjadi suburlah tumbuh-tumbuhan (yang pada tempat tumbuhnya kalian menggembalakan ternak kalian) kalian jadikan sebagai tempat menggembalakan ternak.",[["هُوَ","He"],["ٱلَّذِىٓ","(is) the One Who"],["أَنزَلَ","sends down"],["مِنَ","from"],["ٱلسَّمَآءِ","the sky"],["مَآءًۭ ۖ","water"],["لَّكُم","for you"],["مِّنْهُ","of it"],["شَرَابٌۭ","(is) drink"],["وَمِنْهُ","and from it"],["شَجَرٌۭ","(grows) vegetation"],["فِيهِ","in which"],["تُسِيمُونَ","you pasture your cattle"]]],"1912":["(Dia menumbuhkan bagi kalian dengan air itu tanam-tanaman, zaitun, kurma, anggur dan segala macam buah-buahan. Sesungguhnya pada yang demikian itu) hal yang telah disebutkan itu (benar-benar ada tanda) yang menunjukkan akan keesaan Allah swt. (bagi kaum yang memikirkan) mengenai ciptaan-Nya sehingga mereka mau beriman karenanya.",[["يُنۢبِتُ","He causes to grow"],["لَكُم","for you"],["بِهِ","with it"],["ٱلزَّرْعَ","the crops"],["وَٱلزَّيْتُونَ","and the olives"],["وَٱلنَّخِيلَ","and the date-palms"],["وَٱلْأَعْنَـٰبَ","and the grapes"],["وَمِن","and of"],["كُلِّ","every kind"],["ٱلثَّمَرَٰتِ ۗ","(of) fruits"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَةًۭ","surely (is) a sign"],["لِّقَوْمٍۢ","for a people"],["يَتَفَكَّرُونَ","who reflect"]]],"1913":["(Dan Dia menundukkan malam dan siang untuk kalian, dan matahari) lafal wasysyamsa bila dibaca nashab berarti diathafkan kepada lafal sebelumnya, bila dibaca rafa' berarti menjadi mubtada (bulan dan bintang-bintang) kedua lafal ini dapat dibaca nashab dan rafa` (ditundukkan) kalau dibaca nashab, maka berkedudukan menjadi hal, dan kalau dibaca rafa` maka menjadi khabar (dengan perintah-Nya) berdasarkan kehendak-Nya (Sesungguhnya pada yang demikian itu benar-benar ada tanda-tanda kekuasaan Allah bagi kaum yang memahami-Nya) bagi kaum yang mau memikirkannya.",[["وَسَخَّرَ","And He has subjected"],["لَكُمُ","for you"],["ٱلَّيْلَ","the night"],["وَٱلنَّهَارَ","and the day"],["وَٱلشَّمْسَ","and the sun"],["وَٱلْقَمَرَ ۖ","and the moon"],["وَٱلنُّجُومُ","and the stars"],["مُسَخَّرَٰتٌۢ","(are) subjected"],["بِأَمْرِهِۦٓ ۗ","by His command"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَـٰتٍۢ","surely (are) signs"],["لِّقَوْمٍۢ","for a people"],["يَعْقِلُونَ","who use reason"]]],"1914":["(Dan) Dia menundukkan pula bagi kalian (apa yang Dia ciptakan) makhluk yang telah Dia ciptakan (untuk kalian di bumi ini) berupa hewan-hewan dan tumbuh-tumbuhan serta lain-lainnya (dengan berlain-lainan warnanya) seperti ada yang merah, kuning, hijau dan lain sebagainya (Sesungguhnya pada yang demikian itu benar-benar terdapat tanda kekuasaan Allah bagi kaum yang mengingatnya) mengambilnya sebagai pelajaran.",[["وَمَا","And whatever"],["ذَرَأَ","He multiplied"],["لَكُمْ","for you"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["مُخْتَلِفًا","(of) varying"],["أَلْوَٰنُهُۥٓ ۗ","colors"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَةًۭ","surely (is) a sign"],["لِّقَوْمٍۢ","for a people"],["يَذَّكَّرُونَ","who remember"]]],"1915":["(Dan Dialah yang menundukkan lautan) Dia telah membuatnya jinak sehingga dapat dinaiki dan diselami (agar kalian dapat memakan daripadanya daging yang segar) yaitu ikan (dan kalian mengeluarkan dari lautan itu perhiasan yang kalian pakai) yaitu berupa mutiara dan marjan (dan kamu melihat) menyaksikan (bahtera) perahu-perahu (berlayar padanya) dapat melaju di atas air; artinya dapat membelah ombak melaju ke depan atau ke belakang hanya ditiup oleh satu arah angin (dan supaya kalian mencari) lafal ini diathafkan kepada lafal lita'kuluu, artinya supaya kalian mencari keuntungan (dari karunia-Nya) karunia Allah swt. lewat berniaga (dan supaya kalian bersyukur) kepada Allah swt. atas karunia itu.",[["وَهُوَ","And He"],["ٱلَّذِى","(is) the One Who"],["سَخَّرَ","subjected"],["ٱلْبَحْرَ","the sea"],["لِتَأْكُلُوا۟","for you to eat"],["مِنْهُ","from it"],["لَحْمًۭا","meat"],["طَرِيًّۭا","fresh"],["وَتَسْتَخْرِجُوا۟","and that you bring forth"],["مِنْهُ","from it"],["حِلْيَةًۭ","ornaments"],["تَلْبَسُونَهَا","(that) you wear them"],["وَتَرَى","And you see"],["ٱلْفُلْكَ","the ships"],["مَوَاخِرَ","ploughing"],["فِيهِ","through it"],["وَلِتَبْتَغُوا۟","and that you may seek"],["مِن","of"],["فَضْلِهِۦ","His Bounty"],["وَلَعَلَّكُمْ","and that you may"],["تَشْكُرُونَ","(be) grateful"]]],"1916":["(Dan Dia menancapkan gunung-gunung di bumi dengan kokohnya) gunung-gunung yang tegak kokoh supaya (tidak) jangan (bumi itu goncang) bergerak (bersama kalian dan) Dia telah menciptakan padanya (sungai-sungai) seperti sungai Nil (dan jalan-jalan) jalan untuk dilalui (agar kalian mendapat petunjuk) untuk sampai kepada tujuan-tujuan kalian.",[["وَأَلْقَىٰ","And He has cast"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["رَوَٰسِىَ","firm mountains"],["أَن","lest"],["تَمِيدَ","it should shake"],["بِكُمْ","with you"],["وَأَنْهَـٰرًۭا","and rivers"],["وَسُبُلًۭا","and roads"],["لَّعَلَّكُمْ","so that you may"],["تَهْتَدُونَ","be guided"]]],"1917":["(Dan Dia ciptakan, tanda-tanda) dengan melaluinya kalian mendapat petunjuk arah jalan yang kalian lalui, seperti gunung-gunung dan sungai-sungai. (Dan dengan bintang-bintang itulah) yang dimaksud adalah bentuk jamak sekalipun lafalnya mufrad (mereka mendapat petunjuk) jalan dan arah kiblat di waktu malam hari.",[["وَعَلَـٰمَـٰتٍۢ ۚ","And landmarks"],["وَبِٱلنَّجْمِ","And by the stars"],["هُمْ","they"],["يَهْتَدُونَ","guide themselves"]]],"1918":["(Maka apakah Tuhan yang menciptakan itu) itu Allah (sama dengan yang tidak menciptakan apa-apa) yang dimaksud adalah berhala-berhala, karena mereka menyekutukannya bersama dengan Allah dalam hal beribadah? Tentu saja tidak. (Maka mengapa kalian tidak mengambil pelajaran) dari hal ini, karenanya kemudian kalian beriman?",[["أَفَمَن","Then is He Who"],["يَخْلُقُ","creates"],["كَمَن","like one who"],["لَّا","(does) not"],["يَخْلُقُ ۗ","create"],["أَفَلَا","Then will you not"],["تَذَكَّرُونَ","remember"]]],"1919":["(Dan jika kalian menghitung-hitung nikmat Allah, niscaya kalian tak dapat menentukan jumlahnya) tidak dapat menghitungnya terlebih lagi untuk mensyukurinya secara layak kalian tidak akan mampu melakukannya (Sesungguhnya Allah benar-benar Maha Pengampun lagi Maha Penyayang) karena Dia telah melimpahkan nikmat-Nya kepada kalian padahal kalian meremehkan dan mendurhakai-Nya.",[["وَإِن","And if"],["تَعُدُّوا۟","you should count"],["نِعْمَةَ","the Favors of Allah"],["ٱللَّهِ","the Favors of Allah"],["لَا","not"],["تُحْصُوهَآ ۗ","you could enumerate them"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَغَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"1920":["(Dan Allah mengetahui apa yang kalian rahasiakan dan apa yang kalian lahirkan.)",[["وَٱللَّهُ","And Allah"],["يَعْلَمُ","knows"],["مَا","what"],["تُسِرُّونَ","you conceal"],["وَمَا","and what"],["تُعْلِنُونَ","you reveal"]]],"1921":["(Dan berhala-berhala yang mereka seru) dapat dibaca yad`uuna dan tad`uuna, artinya yang mereka sembah (selain Allah) yang dimaksud adalah berhala-berhala (tidak dapat membuat sesuatu apa pun sedangkan berhala-berhala itu sendiri dibuat orang) mereka pahat dari batu atau dari bahan-bahan yang lain.",[["وَٱلَّذِينَ","And those whom"],["يَدْعُونَ","they invoke"],["مِن","besides"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["لَا","not"],["يَخْلُقُونَ","they create"],["شَيْـًۭٔا","anything"],["وَهُمْ","but (are) themselves"],["يُخْلَقُونَ","created"]]],"1922":["(Berhala-berhala itu benda mati) tidak ada rohnya; lafal ini menjadi khabar yang kedua (tidak hidup) berkedudukan menjadi taukid atau pengukuh (dan mereka tidak mengetahui) berhala-berhala tersebut tidak mengetahui (bilakah) menunjukkan makna waktu (mereka akan dibangkitkan) yang dimaksud adalah makhluk semuanya; maka jika keadaannya demikian mengapa berhala-berhala itu mereka sembah? Kalau demikian berarti tiada tuhan melainkan hanya Yang Maha Pencipta, Yang Maha Hidup dan Yang Maha Mengetahui semua yang gaib.",[["أَمْوَٰتٌ","(They are) dead"],["غَيْرُ","not alive"],["أَحْيَآءٍۢ ۖ","not alive"],["وَمَا","And not"],["يَشْعُرُونَ","they perceive"],["أَيَّانَ","when"],["يُبْعَثُونَ","they will be resurrected"]]],"1923":["(Tuhan kalian) berhak untuk disembah oleh kalian (adalah Tuhan Yang Maha Esa) tidak ada tandingan-Nya, baik dalam Dzat-Nya maupun sifat-Nya, yaitu Allah swt. (Maka orang-orang yang tidak beriman kepada akhirat hati mereka mengingkari) keesaan Allah (sedangkan mereka sendiri adalah orang-orang yang sombong) orang-orang yang takabur tidak mau beriman kepada adanya hari akhirat.",[["إِلَـٰهُكُمْ","Your god"],["إِلَـٰهٌۭ","(is) God"],["وَٰحِدٌۭ ۚ","One"],["فَٱلَّذِينَ","But those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"],["بِٱلْـَٔاخِرَةِ","in the Hereafter"],["قُلُوبُهُم","their hearts"],["مُّنكِرَةٌۭ","refuse"],["وَهُم","and they"],["مُّسْتَكْبِرُونَ","(are) arrogant"]]],"1924":["(Tidak diragukan lagi) memang benar (bahwa sesungguhnya Allah mengetahui apa yang mereka rahasiakan dan apa yang mereka lahirkan) maka Dia membalas mereka berdasarkan hal tersebut. (Sesungguhnya Allah tidak menyukai orang-orang yang sombong) dengan pengertian, bahwa Dia akan menyiksa mereka.",[["لَا","No doubt"],["جَرَمَ","No doubt"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["يَعْلَمُ","knows"],["مَا","what"],["يُسِرُّونَ","they conceal"],["وَمَا","and what"],["يُعْلِنُونَ ۚ","they reveal"],["إِنَّهُۥ","Indeed, He"],["لَا","(does) not"],["يُحِبُّ","love"],["ٱلْمُسْتَكْبِرِينَ","the arrogant ones"]]],"1925":["Ayat ini diturunkan berkenaan dengan Nadhr bin Harits (Dan apabila dikatakan kepada mereka, \"Apakah) maa di sini bermakna istifham atau kata tanya (yang) dzaa di sini berfungsi sebagai maushul (telah diturunkan Rabb kalian?\") kepada Muhammad. (Mereka menjawab,) yaitu (\"Dongeng-dongengan) buat-buatan (orang-orang dahulu.\") untuk menyesatkan manusia.",[["وَإِذَا","And when"],["قِيلَ","it is said"],["لَهُم","to them"],["مَّاذَآ","What"],["أَنزَلَ","has your Lord sent down"],["رَبُّكُمْ ۙ","has your Lord sent down"],["قَالُوٓا۟","They say"],["أَسَـٰطِيرُ","Tales"],["ٱلْأَوَّلِينَ","(of) the ancient"]]],"1926":["(Ucapan mereka, menyebabkan mereka memikul) akibatnya mereka akan memikul (dosa-dosanya) kesalahan-kesalahannya (dengan sepenuhnya) artinya tidak ada sesuatu pun yang dapat dijadikan sebagai tebusan daripadanya (pada hari kiamat, dan sebagian) ditimpakan pula kepada mereka sebagian (dosa-dosa orang-orang yang mereka sesatkan yang tidak mengetahui sedikit pun) bahwa mereka disesatkan, karena mereka mengajak orang-orang yang diserunya ke jalan yang sesat, kemudian orang-orang yang diserunya itu mengikuti langkah mereka. Dengan demikian maka orang-orang yang menyeru mereka ikut andil dalam dosanya. (Ingatlah, amat buruklah) amat jeleklah (apa yang mereka pikul itu) yakni, dosa-dosa yang mereka pikul itu adalah seburuk-buruk dosa.",[["لِيَحْمِلُوٓا۟","That they may bear"],["أَوْزَارَهُمْ","their own burdens"],["كَامِلَةًۭ","(in) full"],["يَوْمَ","on (the) Day"],["ٱلْقِيَـٰمَةِ ۙ","(of) the Resurrection"],["وَمِنْ","and of"],["أَوْزَارِ","the burdens"],["ٱلَّذِينَ","(of) those whom"],["يُضِلُّونَهُم","they misled [them]"],["بِغَيْرِ","without"],["عِلْمٍ ۗ","knowledge"],["أَلَا","Unquestionably"],["سَآءَ","evil"],["مَا","(is) what"],["يَزِرُونَ","they will bear"]]],"1927":["(Sesungguhnya orang-orang yang sebelum mereka telah mengadakan makar) yaitu seperti apa yang telah dilakukan oleh raja Namrudz; ia membangun sebuah pencakar langit, lalu ia menaikinya dengan maksud untuk memerangi penduduk langit (maka Allah menghancurkan) bertujuan untuk menghancurkan (rumah-rumah mereka dari fondasinya) untuk itu maka Allah mengirimkan angin topan dan gempa bumi yang keras sehingga hancur leburlah apa yang telah mereka bangun itu (lalu atap rumah-rumah mereka jatuh menimpa mereka dari atas) artinya mereka ada di bawahnya lalu tertimpa hal tersebut (dan datanglah azab itu kepada mereka dari tempat yang tidak mereka sadari) artinya azab itu datang kepada mereka dari arah yang tidak mereka duga sebelumnya. Akan tetapi menurut pendapat yang lain dikatakan bahwa ini hanya tamtsil tentang dibinasakannya makar mereka yang telah direncanakan sebelumnya terhadap rasul.",[["قَدْ","Verily"],["مَكَرَ","plotted"],["ٱلَّذِينَ","those who"],["مِن","(were) before them"],["قَبْلِهِمْ","(were) before them"],["فَأَتَى","but Allah came"],["ٱللَّهُ","but Allah came"],["بُنْيَـٰنَهُم","(at) their building"],["مِّنَ","from"],["ٱلْقَوَاعِدِ","the foundations"],["فَخَرَّ","so fell"],["عَلَيْهِمُ","upon them"],["ٱلسَّقْفُ","the roof"],["مِن","from"],["فَوْقِهِمْ","above them"],["وَأَتَىٰهُمُ","and came to them"],["ٱلْعَذَابُ","the punishment"],["مِنْ","from"],["حَيْثُ","where"],["لَا","they (did) not perceive"],["يَشْعُرُونَ","they (did) not perceive"]]],"1928":["(Kemudian Allah menghinakan mereka di hari kiamat) membuat mereka hina (dan berfirman)-lah Allah kepada mereka melalui lisan malaikat-Nya dengan nada mengejek (\"Di manakah sekutu-sekutu-Ku itu?) yang menurut dugaan kalian itu (yang karena membelanya kalian selalu memusuhi) menentang kaum mukminin (tentang perihal mereka.\") mengenai perkara mereka. (Berkatalah) artinya nanti akan berkata/menjawab (orang-orang yang diberi ilmu) yaitu para nabi dan orang-orang mukmin (\"Sesungguhnya kehinaan dan azab hari ini ditimpakan atas orang-orang yang kafir.\") para nabi dan orang-orang mukmin mengatakan demikian sebagai ejekan yang ditujukan kepada orang-orang kafir.",[["ثُمَّ","Then"],["يَوْمَ","(on) the Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["يُخْزِيهِمْ","He will disgrace them"],["وَيَقُولُ","and say"],["أَيْنَ","Where"],["شُرَكَآءِىَ","(are) My partners"],["ٱلَّذِينَ","those (for) whom"],["كُنتُمْ","you used (to)"],["تُشَـٰٓقُّونَ","oppose"],["فِيهِمْ ۚ","[in them]"],["قَالَ","Will say"],["ٱلَّذِينَ","those who"],["أُوتُوا۟","were given"],["ٱلْعِلْمَ","the knowledge"],["إِنَّ","Indeed"],["ٱلْخِزْىَ","the disgrace"],["ٱلْيَوْمَ","this Day"],["وَٱلسُّوٓءَ","and evil"],["عَلَى","(are) upon"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"1929":["(Orang-orang yang dimatikan) dapat dibaca tatawaffaahum dan yatawaffaahum (oleh para malaikat dalam keadaan berbuat zalim kepada diri mereka sendiri) karena melakukan kekufuran (lalu mereka menyerahkan diri) mereka tunduk dan berserah diri ketika maut menjelang mereka seraya berkata (\"Kami sekali-kali tidak ada mengerjakan suatu kejahatan pun.\") yaitu perbuatan musyrik. Maka para malaikat berkata kepada mereka (\"Ada, sesungguhnya Allah Maha Mengetahui apa yang telah kalian kerjakan.\") oleh sebab itu Dia membalaskannya kepada diri kalian.",[["ٱلَّذِينَ","Those whom "],["تَتَوَفَّىٰهُمُ","take them in death"],["ٱلْمَلَـٰٓئِكَةُ","the Angels"],["ظَالِمِىٓ","(while) wronging"],["أَنفُسِهِمْ ۖ","themselves"],["فَأَلْقَوُا۟","then they would offer"],["ٱلسَّلَمَ","the submission"],["مَا","Not"],["كُنَّا","we were"],["نَعْمَلُ","doing"],["مِن","any"],["سُوٓءٍۭ ۚ","evil"],["بَلَىٰٓ","Nay"],["إِنَّ","indeed"],["ٱللَّهَ","Allah"],["عَلِيمٌۢ","(is) All-Knower"],["بِمَا","of what"],["كُنتُمْ","you used (to)"],["تَعْمَلُونَ","do"]]],"1930":["Lalu dikatakan kepada mereka (\"Maka masukilah pintu-pintu neraka Jahanam, kalian kekal di dalamnya. Maka amat buruklah tempat) menetap (orang-orang yang menyombongkan diri itu.\")",[["فَٱدْخُلُوٓا۟","So enter"],["أَبْوَٰبَ","(the) gates"],["جَهَنَّمَ","(of) Hell"],["خَـٰلِدِينَ","(to) abide forever"],["فِيهَا ۖ","in it"],["فَلَبِئْسَ","Surely, wretched"],["مَثْوَى","(is the) abode"],["ٱلْمُتَكَبِّرِينَ","(of) the arrogant"]]],"1931":["(Dan dikatakan kepada orang-orang yang bertakwa) yang memelihara diri dari kemusyrikan (\"Apakah yang telah diturunkan oleh Rabb kalian?\" Mereka menjawab, \"Kebaikan.\" Orang-orang yang telah berbuat baik) karena beriman (di dunia ini mendapat pembalasan yang baik) yakni kehidupan yang baik. (Dan sesungguhnya kampung akhirat) yakni surga (lebih baik) daripada kehidupan dunia berikut semua isinya. Lalu Allah berfirman di dalam kampung akhirat itu. (Dan sebaik-baik tempat bagi orang-orang yang bertakwa) adalah surga itu.",[["۞ وَقِيلَ","And it will be said"],["لِلَّذِينَ","to those who"],["ٱتَّقَوْا۟","fear Allah"],["مَاذَآ","What"],["أَنزَلَ","has your Lord sent down"],["رَبُّكُمْ ۚ","has your Lord sent down"],["قَالُوا۟","They will say"],["خَيْرًۭا ۗ","Good"],["لِّلَّذِينَ","For those who"],["أَحْسَنُوا۟","do good"],["فِى","in"],["هَـٰذِهِ","this"],["ٱلدُّنْيَا","world"],["حَسَنَةٌۭ ۚ","(is) a good"],["وَلَدَارُ","and the home"],["ٱلْـَٔاخِرَةِ","of the Hereafter"],["خَيْرٌۭ ۚ","(is) better"],["وَلَنِعْمَ","And surely excellent"],["دَارُ","(is) the home"],["ٱلْمُتَّقِينَ","(of) the righteous"]]],"1932":["(Yaitu surga Adn) sebagai tempat tinggal. Lafal jannaatu Adn adalah mubtada sedangkan khabarnya ialah (mereka masuk ke dalamnya; mengalir di bawahnya sungai-sungai, di dalam surga itu mereka mendapat segala apa yang mereka kehendaki. Demikianlah) pembalasan itu (Allah memberi balasan kepada orang-orang yang bertakwa.)",[["جَنَّـٰتُ","Gardens"],["عَدْنٍۢ","(of) Eden "],["يَدْخُلُونَهَا","which they will enter"],["تَجْرِى","flows"],["مِن","from"],["تَحْتِهَا","underneath them"],["ٱلْأَنْهَـٰرُ ۖ","the rivers"],["لَهُمْ","For them"],["فِيهَا","therein"],["مَا","(will be) whatever"],["يَشَآءُونَ ۚ","they wish"],["كَذَٰلِكَ","Thus"],["يَجْزِى","Allah rewards"],["ٱللَّهُ","Allah rewards"],["ٱلْمُتَّقِينَ","the righteous"]]],"1933":["(Yaitu orang-orang) lafal alladziina di sini menjadi na`at atau sifat (yang diwafatkan oleh para malaikat dalam keadaan baik) yakni suci dari kekafiran (dengan mengatakan) para malaikat itu berkata kepada mereka ketika akan diwafatkan (\"Salaamun `alaikum.\") dan dikatakan pula kepada mereka kelak di hari akhirat (\"Masuklah kalian ke dalam surga itu disebabkan apa yang telah kalian kerjakan.\")",[["ٱلَّذِينَ","Those whom"],["تَتَوَفَّىٰهُمُ","take them in death"],["ٱلْمَلَـٰٓئِكَةُ","the Angels"],["طَيِّبِينَ ۙ","(when they are) pure"],["يَقُولُونَ","saying"],["سَلَـٰمٌ","Peace"],["عَلَيْكُمُ","(be) upon you"],["ٱدْخُلُوا۟","Enter"],["ٱلْجَنَّةَ","Paradise"],["بِمَا","for what"],["كُنتُمْ","you used (to)"],["تَعْمَلُونَ","do"]]],"1934":["(Tidak ada) tiada (yang ditunggu-tunggu) oleh orang-orang kafir (selain datang kepada mereka) dapat dibaca ta'tiyahum atau ya'tiyahum (para malaikat) untuk mencabut nyawa mereka (atau datangnya perintah Rabbmu) yakni azab atau hari kiamat yang terdapat di dalamnya azab buat mereka. (Demikianlah) seperti apa yang telah dilakukan oleh mereka (telah dilakukan pula oleh orang-orang sebelum mereka) daripada umat-umat terdahulu yang mendustakan rasul-rasul mereka kemudian mereka dibinasakan. (Dan sekali-kali Allah tidak menganiaya mereka) dengan membinasakan mereka tanpa dosa (akan tetapi merekalah yang selalu menganiaya diri mereka sendiri) karena melakukan kekafiran.",[["هَلْ","Do"],["يَنظُرُونَ","they wait"],["إِلَّآ","except"],["أَن","that"],["تَأْتِيَهُمُ","(should) come to them"],["ٱلْمَلَـٰٓئِكَةُ","the Angels"],["أَوْ","or"],["يَأْتِىَ","(should) come"],["أَمْرُ","(the) Command"],["رَبِّكَ ۚ","(of) your Lord"],["كَذَٰلِكَ","Thus"],["فَعَلَ","did"],["ٱلَّذِينَ","those who"],["مِن","(were) before them"],["قَبْلِهِمْ ۚ","(were) before them"],["وَمَا","And not"],["ظَلَمَهُمُ","wronged them"],["ٱللَّهُ","Allah"],["وَلَـٰكِن","but"],["كَانُوٓا۟","they were"],["أَنفُسَهُمْ","themselves"],["يَظْلِمُونَ","wronging"]]],"1935":["(Maka mereka ditimpa oleh akibat kejahatan perbuatan mereka sendiri) yakni pembalasannya (dan dibinasakanlah) diazablah (mereka oleh apa yang selalu mereka perolok-olokkan) yaitu azab.",[["فَأَصَابَهُمْ","Then struck them"],["سَيِّـَٔاتُ","(the) evil (results)"],["مَا","(of) what"],["عَمِلُوا۟","they did"],["وَحَاقَ","and surrounded"],["بِهِم","them"],["مَّا","what"],["كَانُوا۟","they used (to)"],["بِهِۦ","[of it]"],["يَسْتَهْزِءُونَ","mock"]]],"1936":["(Dan berkatalah orang-orang musyrik) dari kalangan penduduk Mekah (\"Jika Allah menghendaki niscaya kami tidak akan menyembah sesuatu apa pun selain Dia, baik kami maupun bapak-bapak kami, dan tidak pula kami mengharamkan sesuatu pun tanda izin-Nya) yaitu mengharamkan bahirah dan saibah. Ini berarti bahwa kemusyrikan kami dan pengharaman kami ini berdasarkan kehendak-Nya karena Dia rela terhadapnya. Maka Allah berfirman menyanggah mereka: (Demikianlah yang diperbuat oleh orang-orang sebelum mereka) artinya mereka telah mendustakan rasul-rasul mereka tentang apa yang didatangkan oleh para rasul itu (maka tidak ada) (kewajiban atas para rasul selain dari menyampaikan amanat Allah dengan terang) dan mereka tidak berkewajiban untuk memberi hidayah.",[["وَقَالَ","And said"],["ٱلَّذِينَ","those who"],["أَشْرَكُوا۟","associate partners (with Allah)"],["لَوْ","If"],["شَآءَ","Allah (had) willed"],["ٱللَّهُ","Allah (had) willed"],["مَا","not"],["عَبَدْنَا","we (would) have worshipped"],["مِن","other than Him"],["دُونِهِۦ","other than Him"],["مِن","any"],["شَىْءٍۢ","thing"],["نَّحْنُ","we"],["وَلَآ","and not"],["ءَابَآؤُنَا","our forefathers"],["وَلَا","and not"],["حَرَّمْنَا","we (would) have forbidden"],["مِن","other than Him"],["دُونِهِۦ","other than Him"],["مِن","anything"],["شَىْءٍۢ ۚ","anything"],["كَذَٰلِكَ","Thus"],["فَعَلَ","did"],["ٱلَّذِينَ","those who"],["مِن","(were) before them"],["قَبْلِهِمْ ۚ","(were) before them"],["فَهَلْ","Then is (there)"],["عَلَى","on"],["ٱلرُّسُلِ","the messengers"],["إِلَّا","except"],["ٱلْبَلَـٰغُ","the conveyance"],["ٱلْمُبِينُ","clear"]]],"1937":["(Dan sesungguhnya Kami telah mengutus rasul pada tiap-tiap umat) seperti Aku mengutus kamu kepada mereka (untuk) artinya untuk menyerukan ('Sembahlah Allah) esakanlah Dia (dan jauhilah thaghut,') berhala-berhala itu janganlah kalian sembah (maka di antara umat itu ada orang-orang yang diberi petunjuk oleh Allah) lalu ia beriman (dan ada pula di antaranya orang-orang yang telah pasti) telah ditentukan (kesesatan baginya) menurut ilmu Allah, sehingga ia tidak beriman. (Maka berjalanlah kalian) hai orang-orang kafir Mekah (di muka bumi dan perhatikanlah bagaimana kesudahan orang-orang yang mendustakan) rasul-rasul mereka, yakni kebinasaan yang akan mereka alami nanti.",[["وَلَقَدْ","And certainly"],["بَعَثْنَا","We sent"],["فِى","into"],["كُلِّ","every"],["أُمَّةٍۢ","nation"],["رَّسُولًا","a Messenger"],["أَنِ","that"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["وَٱجْتَنِبُوا۟","and avoid"],["ٱلطَّـٰغُوتَ ۖ","the false deities"],["فَمِنْهُم","Then among them"],["مَّنْ","(were some) whom"],["هَدَى","Allah guided"],["ٱللَّهُ","Allah guided"],["وَمِنْهُم","and among them"],["مَّنْ","(were) some"],["حَقَّتْ","was justified"],["عَلَيْهِ","on them"],["ٱلضَّلَـٰلَةُ ۚ","the straying"],["فَسِيرُوا۟","So travel"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["فَٱنظُرُوا۟","and see"],["كَيْفَ","how"],["كَانَ","was"],["عَـٰقِبَةُ","the end"],["ٱلْمُكَذِّبِينَ","(of) the deniers"]]],"1938":["(Jika kamu sangat mengharapkan) hai Muhammad (agar mereka dapat petunjuk) sedangkan Allah telah menyesatkan mereka niscaya kamu tidak akan mampu melakukan hal itu (maka sesungguhnya Allah tiada memberi petunjuk kepada orang yang disesatkan-Nya) dapat dibaca yudhillu dan yudhallu, artinya orang yang dikehendaki-Nya sesat (dan sekali-kali mereka tiada mempunyai penolong\") yang dapat mencegah azab Allah atas diri mereka.",[["إِن","If"],["تَحْرِصْ","you desire"],["عَلَىٰ","[for]"],["هُدَىٰهُمْ","their guidance"],["فَإِنَّ","then indeed"],["ٱللَّهَ","Allah"],["لَا","(will) not"],["يَهْدِى","guide"],["مَن","whom"],["يُضِلُّ ۖ","He lets go astray"],["وَمَا","and not (are)"],["لَهُم","for them"],["مِّن","any"],["نَّـٰصِرِينَ","helpers"]]],"1939":["(Mereka bersumpah dengan nama Allah dengan sumpahnya yang sungguh-sungguh) artinya mereka bersumpah dengan sungguh-sungguh (\"Allah tidak akan membangkitkan orang yang mati.\") maka Allah berfirman menyanggah mereka (Tidak demikian, bahkan) Allah pasti akan membangkitkan mereka (sebagai suatu janji yang benar dari Allah) lafal wa`dan dan haqqan kedua-duanya adalah bentuk mashdar yang fungsinya mengukuhkan makna fi`ilnya dan dinashabkan oleh fi`ilnya yang keberadaannya diperkirakan; artinya Allah sungguh telah menjanjikan hal tersebut dan Allah akan membuktikannya dengan benar (akan tetapi kebanyakan manusia) penduduk Mekah (tiada mengetahui) hal tersebut.",[["وَأَقْسَمُوا۟","And they swear"],["بِٱللَّهِ","by Allah"],["جَهْدَ","strongest"],["أَيْمَـٰنِهِمْ ۙ","(of) their oaths"],["لَا","Allah will not resurrect"],["يَبْعَثُ","Allah will not resurrect"],["ٱللَّهُ","Allah will not resurrect"],["مَن","(one) who"],["يَمُوتُ ۚ","dies"],["بَلَىٰ","Nay"],["وَعْدًا","(it is) a promise"],["عَلَيْهِ","upon Him"],["حَقًّۭا","(in) truth"],["وَلَـٰكِنَّ","but"],["أَكْثَرَ","most"],["ٱلنَّاسِ","(of) the mankind"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"1940":["(Agar Allah menjelaskan) lafal liyubayyina ini berta`lluq kepada lafal yab`atsuhum yang keberadaannya diperkirakan (kepada mereka apa yang mereka perselisihkan itu) bersama dengan orang-orang mukmin (tentangnya) tentang masalah agama; melalui cara mengazab orang-orang kafir dan memberi pahala orang-orang mukmin (agar orang-orang kafir itu mengetahui bahwasanya mereka adalah orang-orang yang berdusta) disebabkan mereka mengingkari adanya hari berbangkit.",[["لِيُبَيِّنَ","That He will make clear"],["لَهُمُ","to them"],["ٱلَّذِى","that"],["يَخْتَلِفُونَ","they differ"],["فِيهِ","wherein"],["وَلِيَعْلَمَ","and that may know"],["ٱلَّذِينَ","those who"],["كَفَرُوٓا۟","disbelieved"],["أَنَّهُمْ","that they"],["كَانُوا۟","were"],["كَـٰذِبِينَ","liars"]]],"1941":["(Sesungguhnya perkataan Kami terhadap sesuatu apabila Kami menghendakinya) artinya Kami berkehendak untuk mengadakannya. Lafal qaulunaa adalah mubtada sedangkan khabarnya ialah (Kami hanya mengatakan kepadanya, \"Jadilah,\" maka jadilah ia) artinya, maka sesuatu yang dikehendaki-Nya itu ada seketika. Menurut qiraat lafal fayakuunu dibaca nashab sehingga menjadi fayakuuna karena diathafkan kepada lafal naquula. Ayat ini menunjukkan makna menetapkan kekuasaan Allah di dalam membangkitkan makhluk.",[["إِنَّمَا","Only"],["قَوْلُنَا","Our Word"],["لِشَىْءٍ","to a thing"],["إِذَآ","when"],["أَرَدْنَـٰهُ","We intend it"],["أَن","(is) that"],["نَّقُولَ","We say"],["لَهُۥ","to it"],["كُن","Be"],["فَيَكُونُ","and it is"]]],"1942":["(Dan orang-orang yang berhijrah karena Allah) untuk menegakkan agama-Nya (sesudah mereka dianiaya) mengalami penganiayaan dari penduduk kota Mekah yang dimaksud adalah Nabi saw. dan para sahabatnya (pasti Kami akan memberikan tempat buat mereka) menempatkan mereka (di dunia ini) pada suatu tempat tinggal (yang baik) yakni kota Madinah. (Dan sesungguhnya pahala di akhirat) yaitu surga itu (adalah lebih besar) lebih agung (kalau mereka mengetahui) maksudnya kalau orang-orang kafir itu atau orang-orang yang tidak ikut hijrah benar-benar mengetahui tentang kemuliaan yang diperoleh oleh orang-orang yang berhijrah, niscaya mereka akan ikut hijrah bersama dengan orang-orang yang berhijrah.",[["وَٱلَّذِينَ","And those who"],["هَاجَرُوا۟","emigrated"],["فِى","in (the way)"],["ٱللَّهِ","(of) Allah"],["مِنۢ","after"],["بَعْدِ","after"],["مَا","[what]"],["ظُلِمُوا۟","they were wronged"],["لَنُبَوِّئَنَّهُمْ","surely We will give them position"],["فِى","in"],["ٱلدُّنْيَا","the world"],["حَسَنَةًۭ ۖ","good"],["وَلَأَجْرُ","but surely the reward"],["ٱلْـَٔاخِرَةِ","(of) the Hereafter"],["أَكْبَرُ ۚ","(is) greater"],["لَوْ","if"],["كَانُوا۟","they"],["يَعْلَمُونَ","know"]]],"1943":["Mereka adalah (orang-orang yang sabar) di dalam menghadapi penganiayaan kaum musyrikin dan berhijrah demi untuk memenangkan agama Islam (dan hanya kepada Rabb saja mereka bertawakal) maka Allah pasti memberi mereka rezeki dari jalan yang tiada mereka perhitungkan sebelumnya.",[["ٱلَّذِينَ","Those who"],["صَبَرُوا۟","(are) patient"],["وَعَلَىٰ","and on"],["رَبِّهِمْ","their Lord"],["يَتَوَكَّلُونَ","they put their trust"]]],"1944":["(Dan Kami tidak mengutus sebelum kamu kecuali orang-orang lelaki yang Kami beri wahyu kepada mereka) bukannya para malaikat (maka bertanyalah kepada orang yang mempunyai pengetahuan) yakni para ulama yang ahli dalam kitab Taurat dan kitab Injil (jika kalian tidak mengetahui) hal tersebut, mereka pasti mengetahuinya karena kepercayaan kalian kepada mereka lebih dekat daripada kepercayaan kalian terhadap Nabi Muhammad saw.",[["وَمَآ","And not"],["أَرْسَلْنَا","We sent"],["مِن","before you"],["قَبْلِكَ","before you"],["إِلَّا","except"],["رِجَالًۭا","men"],["نُّوحِىٓ","We revealed"],["إِلَيْهِمْ ۚ","to them"],["فَسْـَٔلُوٓا۟","so ask"],["أَهْلَ","(the) people"],["ٱلذِّكْرِ","(of) the Reminder"],["إِن","if"],["كُنتُمْ","you"],["لَا","(do) not"],["تَعْلَمُونَ","know"]]],"1945":["(Dengan membawa keterangan-keterangan) lafal ini berta`alluq kepada fi`il yang tidak disebutkan; artinya Kami utus mereka dengan membawa hujah-hujah yang jelas (dan kitab-kitab) yakni kitab-kitab suci. (Dan Kami turunkan kepadamu Adz-Dzikr) yakni Alquran (agar kamu menerangkan kepada umat manusia apa yang diturunkan kepada mereka) yang di dalamnya dibedakan antara halal dan haram (dan supaya mereka memikirkan) tentang hal tersebut kemudian mereka mengambil pelajaran daripadanya.",[["بِٱلْبَيِّنَـٰتِ","With the clear proofs"],["وَٱلزُّبُرِ ۗ","and the Books"],["وَأَنزَلْنَآ","And We sent down"],["إِلَيْكَ","to you"],["ٱلذِّكْرَ","the Remembrance"],["لِتُبَيِّنَ","that you may make clear"],["لِلنَّاسِ","to the mankind"],["مَا","what"],["نُزِّلَ","has been sent down"],["إِلَيْهِمْ","to them"],["وَلَعَلَّهُمْ","and that they may"],["يَتَفَكَّرُونَ","reflect"]]],"1946":["(Maka apakah merasa aman orang-orang yang membuat makar) tipu daya (yang jahat itu) terhadap diri Nabi saw. sewaktu mereka berunding di Darun Nadwah untuk mengikatnya, atau membunuhnya atau mengusirnya sebagaimana penjelasan yang telah dikemukakan dalam surah Al-Anfal (dari bencana ditenggelamkannya bumi oleh Allah bersama mereka) seperti apa yang terjadi terhadap diri Qarun (atau datangnya azab kepada mereka dari tempat yang tidak mereka sadari) dari arah yang tidak pernah mereka duga sebelumnya; dan sungguh mereka benar-benar dibinasakan dalam perang Badar, hal tersebut tidak masuk ke dalam perhitungan mereka sebelumnya.",[["أَفَأَمِنَ","Do then feel secure"],["ٱلَّذِينَ","those who"],["مَكَرُوا۟","plotted"],["ٱلسَّيِّـَٔاتِ","the evil deeds"],["أَن","that"],["يَخْسِفَ","Allah will cave"],["ٱللَّهُ","Allah will cave"],["بِهِمُ","with them"],["ٱلْأَرْضَ","the earth"],["أَوْ","or"],["يَأْتِيَهُمُ","will come to them"],["ٱلْعَذَابُ","the punishment"],["مِنْ","from"],["حَيْثُ","where"],["لَا","not"],["يَشْعُرُونَ","they perceive"]]],"1947":["(Atau Allah mengazab mereka di waktu mereka dalam perjalanan) sewaktu mereka sedang dalam perjalanan untuk berniaga (maka sekali-kali mereka tidak dapat menolak) azab itu.",[["أَوْ","Or"],["يَأْخُذَهُمْ","that He may seize them"],["فِى","in"],["تَقَلُّبِهِمْ","their going to and fro"],["فَمَا","then not"],["هُم","they"],["بِمُعْجِزِينَ","will be able to escape"]]],"1948":["(Atau Allah mengazab mereka secara berangsur-angsur) sedikit demi sedikit hingga semuanya binasa; lafal takhawwufin menjadi hal dari fa`il atau dari maf'ul (maka sesungguhnya Rabb kalian adalah Maha Pengasih lagi Maha Penyayang) karena Dia tidak menyegerakan siksa-Nya terhadap mereka.",[["أَوْ","Or"],["يَأْخُذَهُمْ","that He may seize them"],["عَلَىٰ","with"],["تَخَوُّفٍۢ","a gradual wasting"],["فَإِنَّ","But indeed"],["رَبَّكُمْ","your Lord"],["لَرَءُوفٌۭ","(is) surely Full of Kindness"],["رَّحِيمٌ","Most Merciful"]]],"1949":["(Dan apakah mereka tidak memperhatikan segala sesuatu yang telah diciptakan Allah) yang ia mempunyai bayangan, seperti pohon dan gunung (yang berbolak-balik) condong ke sana dan condong ke mari (bayangannya ke kanan dan ke kiri) lafal asysyamaail adalah bentuk jamak dari lafal syimaal; artinya bayangan itu condong ke arah dua sisinya, pertama di permulaan siang hari dan yang kedua pada sore harinya (dalam keadaan sujud kepada Allah) lafal sujjadan menjadi hal; artinya mereka lakukan demikian dalam keadaan tunduk kepada Allah sesuai dengan karakter mereka (sedangkan mereka) yakni bayangan-bayangan itu (berendah diri?) merendahkan dirinya terhadap Allah; bayangan-bayangan tersebut diungkapkan seolah-olah mereka berakal.",[["أَوَلَمْ","Have not"],["يَرَوْا۟","they seen"],["إِلَىٰ","[towards]"],["مَا","what"],["خَلَقَ","Allah has created"],["ٱللَّهُ","Allah has created"],["مِن","from"],["شَىْءٍۢ","a thing"],["يَتَفَيَّؤُا۟","Incline"],["ظِلَـٰلُهُۥ","their shadows"],["عَنِ","to"],["ٱلْيَمِينِ","the right"],["وَٱلشَّمَآئِلِ","and to the left"],["سُجَّدًۭا","prostrating"],["لِّلَّهِ","to Allah"],["وَهُمْ","while they"],["دَٰخِرُونَ","(are) humble"]]],"1950":["(Dan kepada Allah sajalah bersujud segala apa yang berada di langit dan semua makhluk yang melata di bumi) artinya semua makhluk itu tunduk kepada-Nya. Sesuai dengan karakternya; kemudian mereka diungkapkan dalam bentuk yang tidak berakal, mengingat mereka yang tidak berakal jumlahnya lebih banyak (dan juga para malaikat) mereka disebutkan secara khusus di sini karena mengingat keutamaan yang mereka miliki (sedangkan para malaikat itu tidak menyombongkan diri) tidak pernah sekejap pun meninggalkan beribadah kepada-Nya.",[["وَلِلَّهِ","And to Allah"],["يَسْجُدُ","prostrate"],["مَا","whatever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَمَا","and whatever"],["فِى","(is) in"],["ٱلْأَرْضِ","the earth"],["مِن","of"],["دَآبَّةٍۢ","moving creatures"],["وَٱلْمَلَـٰٓئِكَةُ","and the Angels"],["وَهُمْ","and they"],["لَا","(are) not"],["يَسْتَكْبِرُونَ","arrogant"]]],"1951":["(Mereka takut) yakni para malaikat; lafal ini menjadi hal dari dhamir yang terkandung di dalam lafal yastakbiruuna (kepada Rabb mereka yang berkuasa atas mereka) lafal fauqahum menjadi hal daripada dhamir hum; artinya yang menguasai mereka dengan keperkasaan-Nya (dan melaksanakan apa yang diperintahkan kepada mereka) untuk melakukannya.",[["يَخَافُونَ","They fear"],["رَبَّهُم","their Lord"],["مِّن","above them"],["فَوْقِهِمْ","above them"],["وَيَفْعَلُونَ","and they do"],["مَا","what"],["يُؤْمَرُونَ ۩","they are commanded"]]],"1952":["(Allah berfirman, \"Janganlah kalian menyembah dua tuhan) lafal istnaini berfungsi sebagai taukid atau pengukuhan makna (Sesungguhnya Dialah Tuhan Yang Maha Esa) disebutkannya lafal ilaahun dan waahidun untuk menetapkan sifat uluhiah dan sifat wahdaniah Allah (maka hendaklah kepada-Ku saja kalian takut.\") janganlah kalian takut kepada selain Aku. Di dalam ungkapan ini terkandung pengertian iltifat dari dhamir gaib.",[["۞ وَقَالَ","And Allah has said"],["ٱللَّهُ","And Allah has said"],["لَا","(Do) not"],["تَتَّخِذُوٓا۟","take"],["إِلَـٰهَيْنِ","[two] gods"],["ٱثْنَيْنِ ۖ","two"],["إِنَّمَا","only"],["هُوَ","He"],["إِلَـٰهٌۭ","(is) God"],["وَٰحِدٌۭ ۖ","One"],["فَإِيَّـٰىَ","so Me Alone"],["فَٱرْهَبُونِ","you fear [Me]"]]],"1953":["(Dan kepunyaan-Nyalah segala apa yang ada di langit dan di bumi) sebagai milik, makhluk dan hamba-Nya (dan untuk-Nyalah agama itu) ketaatan itu (selama-lamanya) untuk selamanya; lafal waashiban menjadi hal dari lafal ad-diin, sedangkan sebagai `amilnya adalah makna zharaf. (Maka mengapa kalian bertakwa kepada selain Allah?) sedangkan Dia adalah Tuhan yang sebenarnya, dan tiada Tuhan selain-Nya. Istifham atau kata tanya di sini mengandung pengertian ingkar dan celaan.",[["وَلَهُۥ","And to Him (belongs)"],["مَا","whatever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَلَهُ","and to Him"],["ٱلدِّينُ","(is due) the worship"],["وَاصِبًا ۚ","constantly"],["أَفَغَيْرَ","Then is it other (than)"],["ٱللَّهِ","Allah"],["تَتَّقُونَ","you fear"]]],"1954":["(Dan apa saja nikmat yang ada pada kalian maka dari Allahlah datangnya) tiada yang dapat mendatangkannya selain Dia. Huruf maa di sini adalah syarthiyah atau maushulah (dan bila kalian ditimpa) tertimpa (kemudaratan) seperti kemiskinan dan sakit (maka hanya kepada-Nyalah kalian meminta pertolongan) mengangkat suara kalian untuk meminta pertolongan seraya berdoa kepada-Nya, dan niscaya kalian tidak akan meminta kepada selain-Nya.",[["وَمَا","And whatever"],["بِكُم","you have"],["مِّن","of"],["نِّعْمَةٍۢ","favor"],["فَمِنَ","(is) from"],["ٱللَّهِ ۖ","Allah"],["ثُمَّ","Then"],["إِذَا","when"],["مَسَّكُمُ","touches you"],["ٱلضُّرُّ","the adversity"],["فَإِلَيْهِ","then to Him"],["تَجْـَٔرُونَ","you cry for help"]]],"1955":["(Kemudian apabila Dia telah menghilangkan kemudaratan itu daripada kalian, tiba-tiba sebagian daripada kalian mempersekutukan Rabbnya dengan yang lain).",[["ثُمَّ","Then"],["إِذَا","when"],["كَشَفَ","He removes"],["ٱلضُّرَّ","the adversity"],["عَنكُمْ","from you"],["إِذَا","behold"],["فَرِيقٌۭ","A group"],["مِّنكُم","of you"],["بِرَبِّهِمْ","with their Lord"],["يُشْرِكُونَ","associate others"]]],"1956":["(Biarkanlah mereka mengingkari apa yang telah Kami berikan kepada mereka) yaitu nikmat (maka bersenang-senanglah kalian) sebab kesepakatan kalian untuk menyembah berhala-berhala. Amar atau perintah di sini mengandung pengertian ancaman. (Kelak kalian akan mengetahui) akibat daripada hal tersebut.",[["لِيَكْفُرُوا۟","So as to deny"],["بِمَآ","that which"],["ءَاتَيْنَـٰهُمْ ۚ","We have given them"],["فَتَمَتَّعُوا۟ ۖ","Then enjoy yourselves"],["فَسَوْفَ","soon"],["تَعْلَمُونَ","you will know"]]],"1957":["(Dan mereka menyediakan) yakni orang-orang musyrik itu (untuk apa-apa yang mereka tiada mengetahui) bahwa hal itu mendatangkan mudarat dan tidak bermanfaat sama sekali; yang dimaksud adalah untuk berhala-berhala (satu bagian dari rezeki yang telah Kami berikan kepada mereka) berupa ladang dan ternak, yaitu melalui perkataan mereka, ini adalah untuk Allah dan ini adalah untuk sekutu-sekutu kami. (Demi Allah sesungguhnya kalian akan ditanya) dengan pertanyaan yang bernada mencela; di dalam ungkapan ini iltifat dari ghaibah (tentang apa yang telah kalian ada-adakan) terhadap Allah di mana kalian telah mengatakan bahwa Allah telah memerintahkan kalian untuk berbuat hal itu.",[["وَيَجْعَلُونَ","And they assign"],["لِمَا","to what"],["لَا","not"],["يَعْلَمُونَ","they know "],["نَصِيبًۭا","a portion"],["مِّمَّا","of what"],["رَزَقْنَـٰهُمْ ۗ","We have provided them"],["تَٱللَّهِ","By Allah"],["لَتُسْـَٔلُنَّ","surely you will be asked"],["عَمَّا","about what"],["كُنتُمْ","you used (to)"],["تَفْتَرُونَ","invent"]]],"1958":["(Dan mereka menetapkan bagi Allah anak-anak perempuan) yaitu melalui perkataan mereka, bahwa para malaikat itu adalah anak-anak perempuan Allah (Maha Suci Allah) ungkapan yang menyucikan-Nya daripada apa yang mereka duga (sedangkan untuk mereka sendiri apa yang mereka sukai) memilihnya, artinya anak-anak lelaki. Jumlah kalimat ini menjadi mahal rafa', atau menjadi mahal nashab dari fi'il yaj'aluuna. Artinya mereka menetapkan bagi Allah anak-anak perempuan yang mereka sendiri membencinya, sedangkan pada kenyataannya Dia Maha Suci dari mempunyai anak, kemudian mereka menetapkan untuk diri mereka sendiri anak-anak lelaki yang mereka pilih sendiri. Dengan demikian berarti mereka ingin merasa lebih unggul, sebagaimana yang telah dijelaskan oleh firman-Nya yang lain, yaitu, \"Tanyakanlah (hai Muhammad) kepada mereka (orang-orang kafir Mekah) apakah untuk Rabb kalian anak-anak perempuan dan untuk mereka anak-anak laki-laki.\" (Ash-Shaffat 149).",[["وَيَجْعَلُونَ","And they assign"],["لِلَّهِ","to Allah"],["ٱلْبَنَـٰتِ","daughters"],["سُبْحَـٰنَهُۥ ۙ","Glory be to Him"],["وَلَهُم","And for them"],["مَّا","(is) what"],["يَشْتَهُونَ","they desire"]]],"1959":["(Dan apabila seorang dari mereka diberi kabar dengan kelahiran anak perempuan) ia mempunyai anak perempuan yang baru dilahirkan (maka jadilah) maka berubahlah (roman mukanya menjadi hitam) dengan perubahan yang menunjukkan kedukaan dan kesusahan (dan dia sangat marah) marah sekali, maka mengapa mereka menisbatkan anak-anak perempuan terhadap Allah swt.?",[["وَإِذَا","And when"],["بُشِّرَ","is given good news"],["أَحَدُهُم","(to) one of them"],["بِٱلْأُنثَىٰ","of a female"],["ظَلَّ","turns"],["وَجْهُهُۥ","his face"],["مُسْوَدًّۭا","dark"],["وَهُوَ","and he"],["كَظِيمٌۭ","suppresses grief"]]],"1960":["(Ia menyembunyikan dirinya) menghilang (dari orang banyak) dari pandangan kaumnya (disebabkan buruknya berita yang disampaikan kepadanya) karena ia takut akan mendapat celaan, sedangkan ia dalam keadaan bingung untuk melakukan tindakan selanjutnya sebagai pemecahannya. (Apakah dia akan memeliharanya) yakni membiarkannya tanpa dibunuh (dengan menanggung kehinaan) hina dan direndahkan (ataukah akan menguburkannya ke dalam tanah hidup-hidup) seumpamanya ia memendam anak perempuan itu ke dalam tanah. (Ketahuilah, alangkah buruknya) alangkah jeleknya (apa yang mereka tetapkan itu) keputusan mereka itu karena mereka telah menisbatkan kepada Tuhan yang menciptakan mereka mempunyai anak-anak perempuan padahal anak-anak perempuan itu kedudukannya di kalangan mereka serendah itu.",[["يَتَوَٰرَىٰ","He hides himself"],["مِنَ","from"],["ٱلْقَوْمِ","the people"],["مِن","(because) of"],["سُوٓءِ","the evil"],["مَا","of what"],["بُشِّرَ","he has been given good news"],["بِهِۦٓ ۚ","about"],["أَيُمْسِكُهُۥ","Should he keep it"],["عَلَىٰ","in"],["هُونٍ","humiliation"],["أَمْ","or"],["يَدُسُّهُۥ","bury it"],["فِى","in"],["ٱلتُّرَابِ ۗ","the dust"],["أَلَا","Unquestionably"],["سَآءَ","evil"],["مَا","(is) what"],["يَحْكُمُونَ","they decide"]]],"1961":["(Bagi orang-orang yang tidak beriman kepada kehidupan akhirat) yaitu orang-orang kafir (ada perumpamaan yang buruk) sifat yang buruk, yaitu kebiasaan mereka mengubur hidup-hidup anak-anak perempuan padahal mereka membutuhkannya (dan bagi Allah ada perumpamaan yang maha tinggi) sifat yang maha tinggi, yaitu bahwasanya tidak ada Tuhan selain Dia (dan Dialah Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) di dalam mengatur makhluk-Nya.",[["لِلَّذِينَ","For those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"],["بِٱلْـَٔاخِرَةِ","in the Hereafter"],["مَثَلُ","(is) a similitude"],["ٱلسَّوْءِ ۖ","(of) the evil"],["وَلِلَّهِ","and for Allah"],["ٱلْمَثَلُ","(is) the similitude"],["ٱلْأَعْلَىٰ ۚ","the Highest"],["وَهُوَ","And He"],["ٱلْعَزِيزُ","(is) the All-Mighty"],["ٱلْحَكِيمُ","All-Wise"]]],"1962":["(Jika Allah menghukum manusia karena kezalimannya) disebabkan kedurhakaan-kedurhakaan mereka (niscaya tidak akan ditinggalkan-Nya padanya) yakni di muka bumi ini sesuatu pun (dari makhluk yang melata) makhluk yang hidup di permukaannya (tetapi Allah menangguhkan mereka sampai pada waktu yang ditentukan. Maka apabila telah tiba waktu yang ditentukan bagi mereka, tidaklah mereka dapat mengundurkan) waktunya (barang sesaat pun dan tidak pula mendahulukan) waktunya.",[["وَلَوْ","And if"],["يُؤَاخِذُ","Allah were to seize"],["ٱللَّهُ","Allah were to seize"],["ٱلنَّاسَ","the mankind"],["بِظُلْمِهِم","for their wrongdoing"],["مَّا","not"],["تَرَكَ","He (would) have left"],["عَلَيْهَا","upon it"],["مِن","any"],["دَآبَّةٍۢ","moving creature"],["وَلَـٰكِن","but"],["يُؤَخِّرُهُمْ","He defers them"],["إِلَىٰٓ","for"],["أَجَلٍۢ","a term"],["مُّسَمًّۭى ۖ","appointed"],["فَإِذَا","Then when"],["جَآءَ","comes"],["أَجَلُهُمْ","their terms"],["لَا","not"],["يَسْتَـْٔخِرُونَ","they (will) remain behind"],["سَاعَةًۭ ۖ","an hour"],["وَلَا","and not"],["يَسْتَقْدِمُونَ","they can advance (it)"]]],"1963":["(Dan mereka menetapkan bagi Allah apa yang mereka sendiri membencinya) untuk diri mereka sendiri, yaitu anak-anak perempuan; menisbatkan sekutu kepada-Nya dan menghina rasul-rasul (dan keluarlah) perkataan (dari lidah mereka) selain dari hal-hal tersebut (kedustaan) yaitu (bahwa sesungguhnya merekalah yang akan mendapat kebaikan) di sisi Allah, yaitu mendapat surga; hal ini dijelaskan oleh firman Allah swt. yang lain, yaitu, \"Dan jika aku dikembalikan kepada Rabbku, maka sesungguhnya aku akan memperoleh kebaikan pada sisi-Nya.\" (Fushshilat 50). Selanjutnya Allah swt. berfirman: (Tiadalah diragukan) sudah dipastikan (bahwa nerakalah bagi mereka, dan sesungguhnya mereka segera dimasukkan ke dalamnya) artinya mereka dibiarkan di dalam neraka, atau mereka dijebloskan ke dalamnya. Menurut suatu qiraat lafal mufrathuuna dibaca mufrithuuna, artinya sesungguhnya mereka adalah orang-orang yang melampaui batas.",[["وَيَجْعَلُونَ","And they assign"],["لِلَّهِ","to Allah"],["مَا","what"],["يَكْرَهُونَ","they dislike"],["وَتَصِفُ","and assert"],["أَلْسِنَتُهُمُ","their tongues"],["ٱلْكَذِبَ","the lie"],["أَنَّ","that"],["لَهُمُ","for them"],["ٱلْحُسْنَىٰ ۖ","(is) the best"],["لَا","No"],["جَرَمَ","doubt"],["أَنَّ","that"],["لَهُمُ","for them"],["ٱلنَّارَ","(is) the Fire"],["وَأَنَّهُم","and that they"],["مُّفْرَطُونَ","(will) be abandoned"]]],"1964":["(Demi Allah, sesungguhnya Kami telah mengutus kepada umat-umat sebelum kamu) telah mengutus rasul-rasul Kami (tetapi setan menjadikan umat-umat itu memandang baik perbuatan mereka) yang buruk itu sehingga perbuatan-perbuatan mereka yang buruk itu dilihatnya baik; oleh karenanya mereka mendustakan rasul-rasul (maka setan menjadi pemimpin mereka) yang mengatur urusan-urusan mereka (di hari itu) yakni di dalam kehidupan dunia (dan bagi mereka azab yang sangat pedih) yang sangat menyakitkan kelak di hari kemudian. Menurut suatu pendapat dikatakan bahwa makna yang dimaksud dengan hari ini ialah hari kiamat; ungkapan ini menggambarkan tentang kejadian di masa mendatang dalam bentuk sekarang; artinya tidak ada seorang penolong pun bagi mereka selain Dia, sedangkan setan sendiri tidak mampu untuk menyelamatkan dirinya sendiri, mana mungkin ia dapat menyelamatkan orang lain.",[["تَٱللَّهِ","By Allah"],["لَقَدْ","certainly"],["أَرْسَلْنَآ","We have sent"],["إِلَىٰٓ","to"],["أُمَمٍۢ","nations"],["مِّن","before you"],["قَبْلِكَ","before you"],["فَزَيَّنَ","but made fair-seeming"],["لَهُمُ","to them"],["ٱلشَّيْطَـٰنُ","the Shaitaan"],["أَعْمَـٰلَهُمْ","their deeds"],["فَهُوَ","So he"],["وَلِيُّهُمُ","(is) their ally"],["ٱلْيَوْمَ","today"],["وَلَهُمْ","and for them"],["عَذَابٌ","(is) a punishment"],["أَلِيمٌۭ","painful"]]],"1965":["(Dan Kami tidak menurunkan kepadamu) hai Muhammad (Alkitab ini) Alquran ini (melainkan agar kamu dapat menjelaskan kepada mereka apa yang mereka perselisihkan itu) yaitu tentang perkara agama (dan menjadi petunjuk) diathafkan kepada lafal litubayyina (dan rahmat bagi kaum yang beriman) kepada Alquran itu.",[["وَمَآ","And not"],["أَنزَلْنَا","We revealed"],["عَلَيْكَ","to you"],["ٱلْكِتَـٰبَ","the Book"],["إِلَّا","except"],["لِتُبَيِّنَ","that you make clear"],["لَهُمُ","to them"],["ٱلَّذِى","that which"],["ٱخْتَلَفُوا۟","they differed"],["فِيهِ ۙ","in it"],["وَهُدًۭى","and (as) a guidance"],["وَرَحْمَةًۭ","and mercy"],["لِّقَوْمٍۢ","for a people"],["يُؤْمِنُونَ","who believe"]]],"1966":["(Dan Allah menurunkan dari langit air hujan dan dengan air itu dihidupkan-Nya bumi) dengan tumbuh-tumbuhan (sesudah matinya) dimaksud sesudah mengalami kekeringan. (Sesungguhnya pada yang demikian itu) dalam hal yang telah disebutkan itu (benar benar terdapat tanda) yang menunjukkan adanya hari berbangkit (bagi orang-orang yang mendengarkan) dengan pendengaran dibarengi dengan pemikiran.",[["وَٱللَّهُ","And Allah"],["أَنزَلَ","has sent down"],["مِنَ","from"],["ٱلسَّمَآءِ","the sky"],["مَآءًۭ","water"],["فَأَحْيَا","then gives life"],["بِهِ","by it"],["ٱلْأَرْضَ","(to) the earth"],["بَعْدَ","after"],["مَوْتِهَآ ۚ","its death"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَةًۭ","(is) surely a Sign"],["لِّقَوْمٍۢ","for a people"],["يَسْمَعُونَ","who listen"]]],"1967":["(Dan sesungguhnya pada binatang ternak itu benar-benar terdapat pelajaran bagi kalian) bahan pelajaran. (Kami memberi kalian minum) lafal ini berfungsi sebagai penjelas daripada pengertian pelajaran tadi (daripada apa yang berada dalam perutnya) dalam perut binatang ternak itu (di) huruf min di sini menunjukkan makna ibtida dan bertaalluq kepada lafal nusqiikum (antara kotoran) yakni lemak ususnya (dan darah berupa air susu yang bersih) sedikit pun tidak bercampur kotoran dan darah baik dari segi rasa, bau atau warnanya atau campuran di antara keduanya (yang mudah ditelan bagi orang-orang yang meminumnya) lewat dengan mudah di tenggorokan mereka dan tidak sulit untuk ditelan.",[["وَإِنَّ","And indeed"],["لَكُمْ","for you"],["فِى","in"],["ٱلْأَنْعَـٰمِ","the cattle"],["لَعِبْرَةًۭ ۖ","(is) a lesson"],["نُّسْقِيكُم","We give you to drink"],["مِّمَّا","from what"],["فِى","(is) in"],["بُطُونِهِۦ","their bellies"],["مِنۢ","from"],["بَيْنِ","between"],["فَرْثٍۢ","bowels"],["وَدَمٍۢ","and blood"],["لَّبَنًا","milk"],["خَالِصًۭا","pure"],["سَآئِغًۭا","palatable"],["لِّلشَّـٰرِبِينَ","to the drinkers"]]],"1968":["(Dan dari buah kurma dan anggur) terdapat jenis buah-buahan (yang kalian dapat membuat minuman yang memabukkan daripadanya) dimaksud khamar yang dapat memabukkan. Di sini kata muskiran disebutkan dengan memakai mashdarnya, yaitu sakaran. Hal ini diturunkan sebelum adanya pengharaman khamar (dan rezeki yang baik) seperti selai kurma, anggur kering, cuka dan sirup. (Sesungguhnya pada yang demikian itu) hal yang telah disebutkan itu (benar-benar terdapat tanda) yang menunjukkan kekuasaan Allah swt. (bagi orang-orang yang berakal) yang memikirkannya.",[["وَمِن","And from"],["ثَمَرَٰتِ","fruits"],["ٱلنَّخِيلِ","the date-palm"],["وَٱلْأَعْنَـٰبِ","and the grapes"],["تَتَّخِذُونَ","you take"],["مِنْهُ","from it"],["سَكَرًۭا","intoxicant"],["وَرِزْقًا","and a provision"],["حَسَنًا ۗ","good"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَةًۭ","(is) surely a Sign"],["لِّقَوْمٍۢ","for a people"],["يَعْقِلُونَ","who use reason"]]],"1969":["(Dan Rabbmu mewahyukan kepada lebah) dalam bentuk ilham (hendaknya) huruf an di sini dapat diartikan sebagai an mashdariyah atau an mufassirah (buatlah sarang-sarang di bukit-bukit) tempat kamu berdiam (dan di pohon-pohon) sebagai tempat tinggal (dan di tempat-tempat yang dibikin manusia) sarang-sarang buatan manusia untuk kamu, jika kamu tidak suka kepada sarang buatan manusia, kamu boleh menempati tempat yang lainnya.",[["وَأَوْحَىٰ","And inspired"],["رَبُّكَ","your Lord"],["إِلَى","to"],["ٱلنَّحْلِ","the bee"],["أَنِ","[that]"],["ٱتَّخِذِى","Take"],["مِنَ","among"],["ٱلْجِبَالِ","the mountains"],["بُيُوتًۭا","houses"],["وَمِنَ","and among"],["ٱلشَّجَرِ","the trees"],["وَمِمَّا","and in what"],["يَعْرِشُونَ","they construct"]]],"1970":["(Kemudian makanlah dari setiap buah-buahan dan tempuhlah) masukilah (jalan Rabbmu) jalan-jalan yang telah ditunjukkan oleh-Nya kepadamu di dalam mencari rezekimu (yang telah dimudahkan) lafal dzululan ini adalah bentuk jamak dari lafal tunggal dzaluulun; berkedudukan menjadi hal dari lafal subula rabbiki. Artinya jalan yang telah dimudahkan bagimu sehingga amat mudah ditempuh sekali pun sangat sulit dan kamu tidak akan sesat untuk kembali ke sarangmu dari tempat itu betapa pun jauhnya. Akan tetapi menurut pendapat yang lain dikatakan bahwa lafal dzululan ini menjadi hal daripada dhamir yang terdapat di dalam lafal uslukiy sehingga artinya menjadi: yang telah ditundukkan untuk memenuhi kehendakmu. (Dari perut lebah itu keluar minuman) yakni berupa madu (yang bermacam-macam warnanya di dalamnya terdapat obat yang menyembuhkan bagi manusia) dari berbagai macam penyakit. Menurut suatu pendapat dikatakan dari sebagian penyakit saja karena ditunjukkan oleh pengertian ungkapan lafal syifaaun yang memakai nakirah. Atau sebagai obat untuk berbagai macam penyakit bila digabungkan dengan obat-obat lainnya. Aku katakan bila tidak dicampur dengan obat yang lain, maka sesuai dengan niat peminumnya. Sungguh Nabi saw. telah memerintahkan untuk meminum madu bagi orang yang perutnya kembung demikianlah menurut riwayat yang telah dikemukakan oleh Imam Bukhari dan Muslim. (Sesungguhnya pada yang demikian itu benar-benar terdapat tanda kebesaran Allah bagi orang-orang yang memikirkan) ciptaan-Nya",[["ثُمَّ","Then"],["كُلِى","eat"],["مِن","from"],["كُلِّ","all"],["ٱلثَّمَرَٰتِ","the fruits"],["فَٱسْلُكِى","and follow"],["سُبُلَ","(the) ways"],["رَبِّكِ","(of) your Lord"],["ذُلُلًۭا ۚ","made smooth"],["يَخْرُجُ","Comes forth"],["مِنۢ","from"],["بُطُونِهَا","their bellies"],["شَرَابٌۭ","a drink"],["مُّخْتَلِفٌ","(of) varying"],["أَلْوَٰنُهُۥ","colors"],["فِيهِ","in it"],["شِفَآءٌۭ","(is) a healing"],["لِّلنَّاسِ ۗ","for the mankind"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَةًۭ","(is) surely a Sign"],["لِّقَوْمٍۢ","for a people"],["يَتَفَكَّرُونَ","who reflect"]]],"1971":["(Allah menciptakan kalian) yang sebelumnya kalian bukan merupakan apa-apa (kemudian mewafatkan kalian) bila ajal kalian telah tiba (dan di antara kalian ada yang dikembalikan kepada umur yang paling lemah) umur yang sangat lanjut dan pikun (supaya dia tidak mengetahui lagi sesuatu pun yang pernah diketahuinya) Ikrimah mengatakan, bahwa barang siapa yang selalu membaca Alquran, maka ia tidak akan sampai kepada keadaan seperti ini. (Sesungguhnya Allah Maha Mengetahui) di dalam mengatur makhluk-Nya (lagi Maha Kuasa) terhadap apa yang dikehendaki-Nya.",[["وَٱللَّهُ","And Allah"],["خَلَقَكُمْ","created you"],["ثُمَّ","then"],["يَتَوَفَّىٰكُمْ ۚ","will cause you to die"],["وَمِنكُم","And among you"],["مَّن","(is one) who"],["يُرَدُّ","is sent back"],["إِلَىٰٓ","to"],["أَرْذَلِ","the worst"],["ٱلْعُمُرِ","(of) the age"],["لِكَىْ","so that"],["لَا","not"],["يَعْلَمَ","he will know"],["بَعْدَ","after"],["عِلْمٍۢ","knowledge"],["شَيْـًٔا ۚ","a thing"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["عَلِيمٌۭ","(is) All-Knowing"],["قَدِيرٌۭ","All-Powerful"]]],"1972":["(Dan Allah melebihkan sebagian kalian dari sebagian yang lain dalam hal rezeki) di antara kalian ada yang kaya dan ada pula yang miskin, serta ada pula yang menjadi raja dan yang menjadi hamba sahaya (tetapi orang-orang yang dilebihkan rezekinya tidak mau) yakni tuan-tuan pemilik hamba sahaya (memberikan rezeki mereka kepada budak-budak yang mereka miliki) artinya mereka tidak mau menjadikan rezeki yang Kami limpahkan kepada mereka menjadi milik bersama antara mereka dan hamba-hamba sahaya mereka (agar mereka) yakni para pemilik hamba sahaya dan para hamba sahaya yang dimilikinya (sama merasakan rezeki itu) bersekutu memilikinya. Makna yang dimaksud ialah, bahwa mereka tidak akan mau menjadikan harta mereka untuk milik bersama dengan hamba-hamba sahaya mereka, maka mengapa mereka menjadikan sebagian daripada milik-milik Allah menjadi sekutu-sekutu-Nya. (Maka mengapa mereka mengingkari nikmat Allah?) karena ternyata mereka telah menjadikan bagi-Nya sekutu-sekutu.",[["وَٱللَّهُ","And Allah"],["فَضَّلَ","has favored"],["بَعْضَكُمْ","some of you"],["عَلَىٰ","over"],["بَعْضٍۢ","others"],["فِى","in"],["ٱلرِّزْقِ ۚ","[the] provision"],["فَمَا","But not"],["ٱلَّذِينَ","those who"],["فُضِّلُوا۟","were favored"],["بِرَآدِّى","would hand over"],["رِزْقِهِمْ","their provision"],["عَلَىٰ","to"],["مَا","whom"],["مَلَكَتْ","possess"],["أَيْمَـٰنُهُمْ","their right hands"],["فَهُمْ","so (that) they"],["فِيهِ","(are) in it"],["سَوَآءٌ ۚ","equal"],["أَفَبِنِعْمَةِ","Then is it the Favor"],["ٱللَّهِ","of Allah"],["يَجْحَدُونَ","they reject"]]],"1973":["(Allah menjadikan bagi kalian istri-istri dari jenis kalian sendiri) maka Allah menciptakan Siti Hawa dari tulang rusuk Nabi Adam dan semua manusia lainnya dari mani kaum laki-laki dan wanita (dan menjadikan bagi kalian dari istri-istri kalian itu, anak-anak dan cucu-cucu) keturunan dari anak-anaknya (dan memberi kalian rezeki dari yang baik-baik) berupa berbagai macam buah-buahan, biji-bijian dan hewan-hewan ternak (maka mengapa kepada yang batil) kepada berhala (mereka beriman dan mengapa mereka ingkar terhadap nikmat Allah) dengan menyekutukan-Nya.",[["وَٱللَّهُ","And Allah"],["جَعَلَ","(has) made"],["لَكُم","for you"],["مِّنْ","from"],["أَنفُسِكُمْ","yourselves"],["أَزْوَٰجًۭا","spouses"],["وَجَعَلَ","and has made"],["لَكُم","for you"],["مِّنْ","from"],["أَزْوَٰجِكُم","your spouses"],["بَنِينَ","sons"],["وَحَفَدَةًۭ","and grandsons"],["وَرَزَقَكُم","and has provided for you"],["مِّنَ","from"],["ٱلطَّيِّبَـٰتِ ۚ","the good things"],["أَفَبِٱلْبَـٰطِلِ","Then in falsehood do"],["يُؤْمِنُونَ","they believe"],["وَبِنِعْمَتِ","and the Favor"],["ٱللَّهِ","of Allah"],["هُمْ","they"],["يَكْفُرُونَ","disbelieve"]]],"1974":["(Dan mereka menyembah selain Allah) (sesuatu yang tidak dapat memberikan rezeki kepada mereka dari langit) yang dimaksud adalah hujan (dan bumi) yakni tumbuh-tumbuhan (barang sedikit pun) lafal syaian berkedudukan menjadi badal atau pengganti dari lafal rizqan (dan tidak berkuasa) tidak mampu berbuat apa-apa sedikit pun, yang dimaksud adalah berhala-berhala.",[["وَيَعْبُدُونَ","And they worship"],["مِن","other than"],["دُونِ","other than"],["ٱللَّهِ","Allah"],["مَا","which"],["لَا","not"],["يَمْلِكُ","possesses"],["لَهُمْ","for them"],["رِزْقًۭا","any provision"],["مِّنَ","from"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضِ","and the earth"],["شَيْـًۭٔا","[anything]"],["وَلَا","and not"],["يَسْتَطِيعُونَ","they are able"]]],"1975":["(Maka janganlah kalian menjadikan bagi Allah tandingan-tandingan) artinya janganlah kalian menjadikan bagi Allah persamaan-persamaan yang kalian sekutukan mereka dengan-Nya. (Sesungguhnya Allah mengetahui) bahwa tiada tandingan bagi-Nya (sedangkan kalian tidak mengetahui) hal tersebut.",[["فَلَا","So (do) not"],["تَضْرِبُوا۟","put forth"],["لِلَّهِ","for Allah"],["ٱلْأَمْثَالَ ۚ","the similitude"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يَعْلَمُ","knows"],["وَأَنتُمْ","and you"],["لَا","(do) not"],["تَعْلَمُونَ","know"]]],"1976":["(Allah membuat perumpamaan) lafal matsalan ini kemudian dijelaskan oleh badalnya yaitu (dengan seorang hamba sahaya yang dimiliki) lafal mamlukan ini berkedudukan menjadi sifat dari lafal `abdan, dimaksud untuk membedakannya dari manusia yang merdeka, karena manusia yang merdeka disebutkan dengan istilah Abdullaah atau hamba Allah (yang tidak dapat bertindak terhadap sesuatu) karena ia tidak memiliki apa pun (dan seorang) lafal man di sini nakirah maushufah, artinya seorang yang merdeka, bukan hamba sahaya (yang Kami beri rezeki yang baik dari Kami, lalu dia menafkahkan sebagian dari rezeki itu secara sembunyi dan secara terang-terangan) artinya dia menafkahkannya sekehendak hatinya. Misal yang pertama untuk menggambarkan tentang berhala dan misal yang kedua untuk menggambarkan tentang Allah swt. (adakah mereka itu sama?) antara hamba sahaya dan orang merdeka yang bebas dalam bertindak; tentu saja tidak. (Segala puji bagi Allah) semata (tetapi kebanyakan mereka) yakni penduduk kota Mekah (tidak mengetahui) apa yang bakal menimpa mereka kelak yaitu berupa azab, yang karena ketidaktahuan mereka itu akhirnya mereka menyekutukan Allah swt.",[["۞ ضَرَبَ","Allah sets forth"],["ٱللَّهُ","Allah sets forth"],["مَثَلًا","the example"],["عَبْدًۭا","(of) a slave"],["مَّمْلُوكًۭا","(who is) owned"],["لَّا","not"],["يَقْدِرُ","he has power"],["عَلَىٰ","on"],["شَىْءٍۢ","anything"],["وَمَن","and (one) whom"],["رَّزَقْنَـٰهُ","We provided him"],["مِنَّا","from Us"],["رِزْقًا","a provision"],["حَسَنًۭا","good"],["فَهُوَ","so he"],["يُنفِقُ","spends"],["مِنْهُ","from it"],["سِرًّۭا","secretly"],["وَجَهْرًا ۖ","and publicly"],["هَلْ","Can"],["يَسْتَوُۥنَ ۚ","they be equal"],["ٱلْحَمْدُ","All praise"],["لِلَّهِ ۚ","(is) for Allah"],["بَلْ","Nay"],["أَكْثَرُهُمْ","but most of them"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"1977":["(Dan Allah membuat pula perumpamaan) lafal matsalan ini kemudian dijelaskan oleh badalnya, yaitu (dua orang lelaki yang seorang bisu) dilahirkan dalam keadaan cacat tidak dapat berbicara (tidak dapat berbuat sesuatu pun) karenanya ia tidak dapat menangkap pemahaman dan tidak pula dapat memberikan pemahaman (dan dia menjadi beban) yang berat (atas orang yang menanggungnya) atas walinya (ke mana saja dia diarahkan) disuruh (dia tidak dapat mendatangkan) dari tindakannya itu (suatu kebaikan pun) artinya ia tidak pernah berhasil; ini perumpamaan orang kafir. (Samakah orang itu) orang yang bisu itu (dengan orang yang menyuruh berbuat keadilan) artinya dengan orang yang dapat berbicara dan pembicaraannya itu bermanfaat bagi manusia karena ia menyuruh dan menganjurkan manusia untuk berbuat keadilan (dan dia berada pula di atas jalan) di jalan (yang lurus) ini perumpamaan orang yang kedua, yaitu orang muslim. Tentu saja keduanya tidak sama. Akan tetapi menurut suatu pendapat dikatakan bahwa yang kedua ini merupakan misal bagi Allah sedangkan misal yang pertama ditujukan untuk berhala-berhala. Sedangkan perumpamaan yang ada pada ayat sebelumnya adalah perumpamaan antara orang kafir dan orang mukmin.",[["وَضَرَبَ","And Allah sets forth"],["ٱللَّهُ","And Allah sets forth"],["مَثَلًۭا","an example"],["رَّجُلَيْنِ","(of) two men"],["أَحَدُهُمَآ","one of them"],["أَبْكَمُ","(is) dumb"],["لَا","not"],["يَقْدِرُ","he has power"],["عَلَىٰ","on"],["شَىْءٍۢ","anything"],["وَهُوَ","while he"],["كَلٌّ","(is) a burden"],["عَلَىٰ","on"],["مَوْلَىٰهُ","his master"],["أَيْنَمَا","Wherever"],["يُوَجِّههُّ","he directs him"],["لَا","not"],["يَأْتِ","he comes"],["بِخَيْرٍ ۖ","with any good"],["هَلْ","Is"],["يَسْتَوِى","equal"],["هُوَ","he"],["وَمَن","and (the one) who"],["يَأْمُرُ","commands"],["بِٱلْعَدْلِ ۙ","[of] justice"],["وَهُوَ","and he"],["عَلَىٰ","(is) on"],["صِرَٰطٍۢ","a path"],["مُّسْتَقِيمٍۢ","straight"]]],"1978":["(Dan kepunyaan Allahlah segala apa yang tersembunyi di langit dan di bumi) artinya Allah mengetahui semua yang gaib pada keduanya (Tidak adalah kejadian kiamat itu melainkan seperti sekejap mata atau lebih cepat lagi) karena hal itu berlangsung hanya dengan kalimat kun terjadilah ia. (Sesungguhnya Allah Maha Kuasa atas segala sesuatu.)",[["وَلِلَّهِ","And to Allah (belongs)"],["غَيْبُ","(the) unseen"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۚ","and the earth"],["وَمَآ","And not"],["أَمْرُ","(is the) matter"],["ٱلسَّاعَةِ","(of) the Hour"],["إِلَّا","but"],["كَلَمْحِ","as a twinkling"],["ٱلْبَصَرِ","(of) the eye"],["أَوْ","or"],["هُوَ","it"],["أَقْرَبُ ۚ","(is) nearer"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["عَلَىٰ","on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["قَدِيرٌۭ","(is) All-Powerful"]]],"1979":["(Dan Allah mengeluarkan kalian dari perut ibu kalian dalam keadaan tidak mengetahui sesuatu pun) jumlah kalimat laa ta'lamuuna syaian berkedudukan menjadi hal atau kalimat keterangan (dan Dia memberi kalian pendengaran) lafal as-sam'u bermakna jamak sekali pun lafalnya mufrad (penglihatan dan hati) kalbu (agar kalian bersyukur) kepada-Nya atas hal-hal tersebut, oleh karenanya kalian beriman kepada-Nya.",[["وَٱللَّهُ","And Allah"],["أَخْرَجَكُم","brought you forth"],["مِّنۢ","from"],["بُطُونِ","the wombs"],["أُمَّهَـٰتِكُمْ","(of) your mothers"],["لَا","not"],["تَعْلَمُونَ","knowing"],["شَيْـًۭٔا","anything"],["وَجَعَلَ","and made"],["لَكُمُ","for you"],["ٱلسَّمْعَ","the hearing"],["وَٱلْأَبْصَـٰرَ","and the sight"],["وَٱلْأَفْـِٔدَةَ ۙ","and the hearts"],["لَعَلَّكُمْ","so that you may"],["تَشْكُرُونَ","give thanks"]]],"1980":["(Tidakkah mereka memperhatikan burung-burung yang dimudahkan) terbang (di angkasa bebas) di udara antara langit dan bumi. (Tidak ada yang menahannya) sewaktu ia melipat sayap atau mengembangkannya sehingga ia tidak jatuh ke bawah (selain daripada Allah) yakni dengan kekuasaan-Nya. (Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda kekuasaan Allah bagi orang-orang yang beriman) yaitu penciptaan burung itu sehingga dapat terbang dan penciptaan udara sehingga dapat memungkinkan bagi burung untuk terbang mengarunginya dan menahan burung untuk tidak jatuh ke tanah.",[["أَلَمْ","Do not"],["يَرَوْا۟","they see"],["إِلَى","towards"],["ٱلطَّيْرِ","the birds"],["مُسَخَّرَٰتٍۢ","controlled"],["فِى","in"],["جَوِّ","the midst"],["ٱلسَّمَآءِ","(of) the sky"],["مَا","None"],["يُمْسِكُهُنَّ","holds them up"],["إِلَّا","except"],["ٱللَّهُ ۗ","Allah"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَـٰتٍۢ","(are) Signs"],["لِّقَوْمٍۢ","for a people"],["يُؤْمِنُونَ","who believe"]]],"1981":["(Dan Allah menjadikan bagi kalian rumah-rumah kalian sebagai tempat tinggal) tempat kalian menetap di dalamnya (dan Dia menjadikan bagi kalian rumah-rumah dari kulit binatang ternak) seperti kemah-kemah dan tenda-tenda (yang kalian merasa ringan) ketika membawanya (di waktu kalian berjalan) mengadakan perjalanan (dan waktu kalian bermukim, dan dijadikan-Nya pula, dari bulunya) dari bulu domba (bulu unta) (dan bulu kambing) (alat-alat) perabot rumah tangga kalian; seperti permadani dan perhiasan dinding rumah (dan perhiasan) yang kalian dapat menikmatinya (sampai waktu yang tertentu) sehingga barang-barang itu rusak.",[["وَٱللَّهُ","And Allah"],["جَعَلَ","(has) made"],["لَكُم","for you"],["مِّنۢ","[from]"],["بُيُوتِكُمْ","your homes"],["سَكَنًۭا","a resting place"],["وَجَعَلَ","and made"],["لَكُم","for you"],["مِّن","from"],["جُلُودِ","the hides"],["ٱلْأَنْعَـٰمِ","(of) the cattle"],["بُيُوتًۭا","tents"],["تَسْتَخِفُّونَهَا","which you find light"],["يَوْمَ","(on) the day"],["ظَعْنِكُمْ","(of) your travel"],["وَيَوْمَ","and the day"],["إِقَامَتِكُمْ ۙ","(of) your encampment"],["وَمِنْ","and from"],["أَصْوَافِهَا","their wool"],["وَأَوْبَارِهَا","and their fur"],["وَأَشْعَارِهَآ","and their hair"],["أَثَـٰثًۭا","(is) furnishing"],["وَمَتَـٰعًا","and a provision"],["إِلَىٰ","for"],["حِينٍۢ","a time"]]],"1982":["(Dan Allah menjadikan bagi kalian dari apa yang telah Dia ciptakan) seperti rumah-rumah, pohon-pohon dan mendung (sebagai tempat bernaung) lafal zhilaalan adalah bentuk jamak dari lafal zhillun; yang dapat melindungi diri kalian dari sengatan panas matahari (dan Dia jadikan bagi kalian tempat-tempat tinggal di gunung-gunung) lafal aknaanan adalah bentuk jamak dari lafal kinnun, yang artinya tempat untuk tinggal seperti gua dan liang besar (dan Dia jadikan bagi kalian pakaian) baju-baju gamis (yang memelihara kalian dari panas) dan dari dingin (dan pakaian/baju besi yang memelihara kalian dalam peperangan) sewaktu kalian berperang yakni dari tusukan dan pukulan senjata di dalam peperangan, seperti baju dan topi besi. (Demikianlah) sebagaimana Dia telah menciptakan semuanya itu (Allah menyempurnakan nikmat-Nya) di dunia (atas kalian) dengan menciptakan segala sesuatu yang menjadi keperluan kalian (agar kalian) hai penduduk Mekah (masuk Islam) agar kalian mengesakan-Nya.",[["وَٱللَّهُ","And Allah"],["جَعَلَ","(has) made"],["لَكُم","for you"],["مِّمَّا","from what"],["خَلَقَ","He created"],["ظِلَـٰلًۭا","shades"],["وَجَعَلَ","and (has) made"],["لَكُم","for you"],["مِّنَ","from"],["ٱلْجِبَالِ","the mountains"],["أَكْنَـٰنًۭا","shelters"],["وَجَعَلَ","and (has) made"],["لَكُمْ","for you"],["سَرَٰبِيلَ","garments"],["تَقِيكُمُ","to protect you"],["ٱلْحَرَّ","(from) the heat"],["وَسَرَٰبِيلَ","and garments"],["تَقِيكُم","to protect you"],["بَأْسَكُمْ ۚ","from your (mutual) violence"],["كَذَٰلِكَ","Thus"],["يُتِمُّ","He completes"],["نِعْمَتَهُۥ","His Favor"],["عَلَيْكُمْ","upon you"],["لَعَلَّكُمْ","so that you may"],["تُسْلِمُونَ","submit"]]],"1983":["(Jika mereka tetap berpaling) tidak juga mau masuk Islam (maka sesungguhnya kewajiban yang dibebankan kepadamu) hai Muhammad (hanyalah menyampaikan amanat Allah, dengan terang) ayat ini diturunkan sebelum ada perintah untuk memerangi orang-orang kafir.",[["فَإِن","Then, if"],["تَوَلَّوْا۟","they turn away"],["فَإِنَّمَا","then only"],["عَلَيْكَ","upon you"],["ٱلْبَلَـٰغُ","(is) the conveyance"],["ٱلْمُبِينُ","the clear"]]],"1984":["(Mereka mengetahui nikmat Allah) artinya mereka mengakui bahwa semua nikmat itu dari sisi-Nya (kemudian mereka mengingkarinya) karena ternyata mereka menyekutukan-Nya (dan kebanyakan mereka adalah orang-orang yang kafir).",[["يَعْرِفُونَ","They recognize"],["نِعْمَتَ","(the) Favor"],["ٱللَّهِ","(of) Allah"],["ثُمَّ","then"],["يُنكِرُونَهَا","they deny it"],["وَأَكْثَرُهُمُ","And most of them"],["ٱلْكَـٰفِرُونَ","(are) the disbelievers"]]],"1985":["(Dan) ingatlah (akan hari ketika Kami membangkitkan dari tiap-tiap umat seorang saksi) yakni nabinya yang berkesaksian tentang kebaikan atau keburukan yang dilakukan oleh umatnya, yaitu pada hari kiamat nanti (kemudian tidak diizinkan kepada orang-orang yang kafir) untuk mengemukakan alasannya (dan tidak pula mereka dibolehkan meminta maaf) artinya mereka tidak diperkenankan untuk minta maaf kepada Allah swt.",[["وَيَوْمَ","And the Day"],["نَبْعَثُ","We will resurrect"],["مِن","from"],["كُلِّ","every"],["أُمَّةٍۢ","nation"],["شَهِيدًۭا","a witness"],["ثُمَّ","then"],["لَا","not"],["يُؤْذَنُ","will be permitted"],["لِلَّذِينَ","to those who"],["كَفَرُوا۟","disbelieved"],["وَلَا","and not"],["هُمْ","they"],["يُسْتَعْتَبُونَ","will be asked to make amends"]]],"1986":["(Dan apabila orang-orang lalim telah menyaksikan) yang dimaksud adalah orang-orang yang kafir (azab) yakni neraka (maka tidak diringankan bagi mereka) azab itu (dan tidak pula mereka diberi tangguh) ditangguhkan dari siksa neraka bila mereka telah melihatnya.",[["وَإِذَا","And when"],["رَءَا","(will) see"],["ٱلَّذِينَ","those who"],["ظَلَمُوا۟","wronged"],["ٱلْعَذَابَ","the punishment"],["فَلَا","then not"],["يُخَفَّفُ","it will be lightened"],["عَنْهُمْ","for them"],["وَلَا","and not"],["هُمْ","they"],["يُنظَرُونَ","will be given respite"]]],"1987":["(Dan apabila orang-orang yang mempersekutukan Allah melihat sekutu-sekutu mereka) yang terdiri daripada setan-setan dan lain-lainnya (mereka berkata, \"Ya Rabb kami! Mereka inilah sekutu-sekutu kami yang dahulu kami seru) kami sembah (selain dari Engkau.\" Lalu sekutu-sekutu mereka mengatakan kepada mereka) artinya para sekutu mereka itu berkata kepada mereka (\"Sesungguhnya kalian benar-benar orang-orang yang dusta.\") di dalam pengakuan kalian itu, yang mengatakan bahwa kalian telah menyembah kami, sebagaimana yang telah dijelaskan di dalam ayat yang lain, yaitu melalui firman-Nya, \"Mereka sekali-kali tidak menyembah kami.\" (Al-Qashash 63). Sekutu-sekutu itu pasti akan mengingkari penyembahan mereka terhadap dirinya.",[["وَإِذَا","And when"],["رَءَا","(will) see"],["ٱلَّذِينَ","those who"],["أَشْرَكُوا۟","associated partners with Allah"],["شُرَكَآءَهُمْ","their partners"],["قَالُوا۟","They will say"],["رَبَّنَا","Our Lord"],["هَـٰٓؤُلَآءِ","these"],["شُرَكَآؤُنَا","(are) our partners"],["ٱلَّذِينَ","those whom"],["كُنَّا","we used to"],["نَدْعُوا۟","invoke"],["مِن","besides You"],["دُونِكَ ۖ","besides You"],["فَأَلْقَوْا۟","But they (will) throw back"],["إِلَيْهِمُ","at them"],["ٱلْقَوْلَ","(their) word"],["إِنَّكُمْ","Indeed, you"],["لَكَـٰذِبُونَ","(are) surely liars"]]],"1988":["(Dan mereka menyatakan ketundukannya kepada Allah pada hari itu) artinya mereka tunduk terhadap keputusan Allah (dan hilanglah) lenyaplah (dari mereka apa yang selalu mereka ada-adakan) yang menyatakan bahwa sekutu-sekutu mereka itu dapat memberikan syafaat bagi mereka.",[["وَأَلْقَوْا۟","And they (will) offer"],["إِلَى","to"],["ٱللَّهِ","Allah"],["يَوْمَئِذٍ","(on) that Day"],["ٱلسَّلَمَ ۖ","the submission"],["وَضَلَّ","and (is) lost"],["عَنْهُم","from them"],["مَّا","what"],["كَانُوا۟","they used (to)"],["يَفْتَرُونَ","invent"]]],"1989":["(Orang-orang yang kafir dan menghalang-halangi) manusia (dari jalan Allah) dari agama-Nya (Kami tambahkan kepada mereka siksaan di atas siksaan) yakni di atas siksaan yang berhak mereka terima dikarenakan kekafiran mereka. Ibnu Masud r.a. mengatakan, bahwa siksaan tambahan itu berupa kelabang-kelabang yang taringnya bagaikan batang-batang pohon kurma yang tinggi (disebabkan mereka selalu berbuat kerusakan) karena mereka telah mencegah manusia untuk beriman kepada Allah.",[["ٱلَّذِينَ","And those who"],["كَفَرُوا۟","disbelieved"],["وَصَدُّوا۟","and hindered"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["زِدْنَـٰهُمْ","We will increase them"],["عَذَابًۭا","(in) punishment"],["فَوْقَ","over"],["ٱلْعَذَابِ","punishment"],["بِمَا","because"],["كَانُوا۟","they used (to)"],["يُفْسِدُونَ","spread corruption"]]],"1990":["(Dan) ingatlah (akan hari ketika Kami bangkitkan pada tiap-tiap umat seorang saksi atas mereka dari mereka sendiri) yakni nabi mereka sendiri (dan Kami datangkan kamu) hai Muhammad (menjadi saksi atas mereka) bagi kaummu. (Dan Kami turunkan kepadamu Alkitab) yakni Alquran (untuk menjelaskan) untuk menerangkan (segala sesuatu) yang diperlukan oleh umat manusia menyangkut masalah syariat (dan petunjuk) supaya jangan tersesat (serta rahmat dan kabar gembira) memperoleh surga (bagi orang-orang yang beriman) bagi orang-orang yang mentauhidkan Allah.",[["وَيَوْمَ","And the Day"],["نَبْعَثُ","We will resurrect"],["فِى","among"],["كُلِّ","every"],["أُمَّةٍۢ","nation"],["شَهِيدًا","a witness"],["عَلَيْهِم","over them"],["مِّنْ","from"],["أَنفُسِهِمْ ۖ","themselves"],["وَجِئْنَا","And We (will) bring"],["بِكَ","you"],["شَهِيدًا","(as) a witness"],["عَلَىٰ","over"],["هَـٰٓؤُلَآءِ ۚ","these"],["وَنَزَّلْنَا","And We sent down"],["عَلَيْكَ","to you"],["ٱلْكِتَـٰبَ","the Book"],["تِبْيَـٰنًۭا","(as) a clarification"],["لِّكُلِّ","of every"],["شَىْءٍۢ","thing"],["وَهُدًۭى","and a guidance"],["وَرَحْمَةًۭ","and mercy"],["وَبُشْرَىٰ","and glad tidings"],["لِلْمُسْلِمِينَ","for the Muslims"]]],"1991":["(Sesungguhnya Allah menyuruh kalian berlaku adil) bertauhid atau berlaku adil dengan sesungguhnya (dan berbuat kebaikan) menunaikan fardu-fardu, atau hendaknya kamu menyembah Allah seolah-olah kamu melihat-Nya sebagaimana yang telah dijelaskan oleh hadis (memberi) bantuan (kepada kaum kerabat) famili; mereka disebutkan secara khusus di sini, sebagai pertanda bahwa mereka harus dipentingkan terlebih dahulu (dan Allah melarang dari perbuatan keji) yakni zina (dan kemungkaran) menurut hukum syariat, yaitu berupa perbuatan kekafiran dan kemaksiatan (dan permusuhan) menganiaya orang lain. Lafal al-baghyu disebutkan di sini secara khusus sebagai pertanda, bahwa ia harus lebih dijauhi; dan demikian pula halnya dengan penyebutan lafal al-fahsyaa (Dia memberi pengajaran kepada kalian) melalui perintah dan larangan-Nya (agar kalian dapat mengambil pelajaran) mengambil pelajaran dari hal tersebut. Di dalam lafal tadzakkaruuna menurut bentuk asalnya ialah huruf ta-nya diidghamkan kepada huruf dzal. Di dalam kitab Al-Mustadrak disebutkan suatu riwayat yang bersumber dari Ibnu Masud yang telah mengatakan, bahwa ayat ini yakni ayat 90 surah An-Nahl, adalah ayat yang paling padat mengandung anjuran melakukan kebaikan dan menjauhi keburukan di dalam Alquran.",[["۞ إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يَأْمُرُ","commands"],["بِٱلْعَدْلِ","justice"],["وَٱلْإِحْسَـٰنِ","and the good"],["وَإِيتَآئِ","and giving"],["ذِى","(to) relatives"],["ٱلْقُرْبَىٰ","(to) relatives"],["وَيَنْهَىٰ","and forbids"],["عَنِ","[from]"],["ٱلْفَحْشَآءِ","the immorality"],["وَٱلْمُنكَرِ","and the bad"],["وَٱلْبَغْىِ ۚ","and the oppression"],["يَعِظُكُمْ","He admonishes you"],["لَعَلَّكُمْ","so that you may"],["تَذَكَّرُونَ","take heed"]]],"1992":["(Dan tepatilah perjanjian dengan Allah) dalam masalah jual beli dan sumpah-sumpah serta masalah-masalah yang lain (apabila kalian berjanji dan janganlah kalian membatalkan sumpah-sumpah itu sesudah meneguhkannya) artinya sesudah sumpah-sumpah itu kalian teguhkan (sedangkan kalian telah menjadikan Allah sebagai saksi kalian) untuk memenuhinya, karena kalian telah bersumpah dengan memakai nama-Nya; jumlah ayat ini berkedudukan menjadi hal atau kalimat keterangan. (Sesungguhnya Allah mengetahui apa yang kalian perbuat) ayat ini merupakan ancaman buat mereka yang membatalkan sumpahnya.",[["وَأَوْفُوا۟","And fulfil"],["بِعَهْدِ","the covenant"],["ٱللَّهِ","(of) Allah"],["إِذَا","when"],["عَـٰهَدتُّمْ","you have taken a covenant"],["وَلَا","and (do) not"],["تَنقُضُوا۟","break"],["ٱلْأَيْمَـٰنَ","oaths"],["بَعْدَ","after"],["تَوْكِيدِهَا","their confirmation"],["وَقَدْ","while verily"],["جَعَلْتُمُ","you have made"],["ٱللَّهَ","Allah"],["عَلَيْكُمْ","over you"],["كَفِيلًا ۚ","a surety"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يَعْلَمُ","knows"],["مَا","what"],["تَفْعَلُونَ","you do"]]],"1993":["(Dan janganlah kalian seperti seorang perempuan yang menguraikan) merusak (benangnya) hasil apa yang telah dipintalnya (yang sudah dipintal dengan kuat) sudah dijadikan benang (menjadi cerai-berai kembali) lafal ankaatsan berkedudukan menjadi hal, bentuk jamak daripada lafal naktsun; artinya mencerai-beraikan benang yang sudah dipintal kuat. Hal ini merupakan gambaran tentang seorang wanita penduduk kota Mekah; ia setiap hari memintal benang, tetapi sesudah benang itu jadi, lalu ia uraikan kembali; wanita itu dikenal sebagai wanita yang tolol (kalian menjadikan) lafal tattakhidzuuna menjadi hal dari dhamir lafal takuunuu; artinya janganlah kalian seperti wanita yang tolol itu, yaitu kalian menjadikan (sumpah kalian sebagai alat penipu) arti dakhalan ialah memasukkan sesuatu bukan pada tempatnya dan ia bukan merupakan bagian daripadanya; makna yang dimaksud ialah menimbulkan kerusakan atau tipu muslihat (di antara kalian) seumpamanya kalian merusak sumpah itu (disebabkan) lafal an di sini asalnya lian (adanya satu golongan) satu kelompok (yang lebih banyak) jumlahnya (dari golongan yang lain). Disebutkan bahwa mereka mengadakan sumpah perjanjian pertahanan dengan suatu golongan, tetapi bila mereka melihat ada golongan yang lain yang lebih kuat dan lebih banyak jumlahnya, lalu mereka merusak dan membatalkan perjanjiannya dengan golongan yang pertama itu, kemudian mereka mengadakan perjanjian pertahanan dengan golongan yang baru dan yang lebih kuat itu. (Sesungguhnya kalian dicoba) diuji (oleh Allah dengannya) yakni dengan perintah supaya kalian memenuhi sumpah, agar Dia melihat siapakah yang taat di antara kalian dan siapa yang durhaka. Atau membuat suatu umat yang kuat agar Dia melihat apakah mereka memenuhi janjinya atau tidak. (Dan sesungguhnya di hari kiamat akan dijelaskan-Nya kepada kalian apa yang dahulu kalian perselisihkan itu) sewaktu di dunia menyangkut masalah sumpah dan masalah-masalah lainnya; kelak Dia akan mengazab orang yang melanggar sumpahnya dan akan memberi pahala kepada orang yang memenuhinya.",[["وَلَا","And (do) not"],["تَكُونُوا۟","be"],["كَٱلَّتِى","like her who"],["نَقَضَتْ","untwists"],["غَزْلَهَا","her spun yarn"],["مِنۢ","after"],["بَعْدِ","after"],["قُوَّةٍ","strength"],["أَنكَـٰثًۭا","(into) untwisted strands"],["تَتَّخِذُونَ","you take"],["أَيْمَـٰنَكُمْ","your oaths"],["دَخَلًۢا","(as) a deception"],["بَيْنَكُمْ","between you"],["أَن","because"],["تَكُونَ","is"],["أُمَّةٌ","a community"],["هِىَ","[it]"],["أَرْبَىٰ","more numerous"],["مِنْ","than"],["أُمَّةٍ ۚ","(another) community"],["إِنَّمَا","Only"],["يَبْلُوكُمُ","Allah tests you"],["ٱللَّهُ","Allah tests you"],["بِهِۦ ۚ","by it"],["وَلَيُبَيِّنَنَّ","And He will make clear"],["لَكُمْ","to you"],["يَوْمَ","(on) the Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["مَا","what"],["كُنتُمْ","you used (to)"],["فِيهِ","in it"],["تَخْتَلِفُونَ","differ"]]],"1994":["(Dan kalau Allah menghendaki, niscaya Dia menjadikan kalian satu umat) menjadi pemeluk satu agama (tetapi Allah menyesatkan siapa yang dikehendaki-Nya dan memberi petunjuk kepada siapa yang dikehendaki-Nya. Dan sesungguhnya kalian akan ditanya) kelak di hari kiamat dengan pertanyaan yang keras (tentang apa yang telah kalian kerjakan) kemudian kalian mendapatkan balasannya.",[["وَلَوْ","And if"],["شَآءَ","Allah (had) willed"],["ٱللَّهُ","Allah (had) willed"],["لَجَعَلَكُمْ","surely He (could) have made you"],["أُمَّةًۭ","a nation"],["وَٰحِدَةًۭ","one"],["وَلَـٰكِن","but"],["يُضِلُّ","He lets go astray"],["مَن","whom"],["يَشَآءُ","He wills"],["وَيَهْدِى","and guides"],["مَن","whom"],["يَشَآءُ ۚ","He wills"],["وَلَتُسْـَٔلُنَّ","And surely you will be questioned"],["عَمَّا","about what"],["كُنتُمْ","you used (to)"],["تَعْمَلُونَ","do"]]],"1995":["(Dan janganlah kalian jadikan sumpah-sumpah kalian sebagai alat penipu di antara kalian) Allah swt. mengulang-ulang kalimat ini untuk mengukuhkannya (yang menyebabkan tergelincir kaki kalian) artinya kalian tergelincir dari ajaran Islam (sesudah kokoh tegaknya) sesudah kalian teguh memegangnya (dan kalian rasakan azab) siksaan (karena kalian menghalangi manusia dari jalan Allah) artinya disebabkan kalian tidak mau memenuhi janji kalian sendiri, atau disebabkan kalian menghalang-halangi orang lain untuk memenuhi sumpah dan janjinya, kemudian orang lain itu menuruti perintah kalian (dan bagi kalian azab yang besar) di akhirat nanti.",[["وَلَا","And (do) not"],["تَتَّخِذُوٓا۟","take"],["أَيْمَـٰنَكُمْ","your oaths"],["دَخَلًۢا","(as) a deception"],["بَيْنَكُمْ","between you"],["فَتَزِلَّ","lest, should slip"],["قَدَمٌۢ","a foot"],["بَعْدَ","after"],["ثُبُوتِهَا","it is firmly planted"],["وَتَذُوقُوا۟","and you would taste"],["ٱلسُّوٓءَ","the evil"],["بِمَا","for what"],["صَدَدتُّمْ","you hindered"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ ۖ","(of) Allah"],["وَلَكُمْ","and for you"],["عَذَابٌ","(is) a punishment"],["عَظِيمٌۭ","great"]]],"1996":["(Dan janganlah kalian tukar perjanjian kalian dengan Allah dengan harga yang sedikit) berupa keduniaan, seumpamanya kalian membatalkan janji itu demi karena perkara duniawi (sesungguhnya apa yang ada di sisi Allah) berupa pahala (itulah yang lebih baik bagi kalian) daripada apa yang terdapat di dunia (jika kalian mengetahui) hal tersebut; maka oleh sebab itu janganlah kalian merusak janji kalian.",[["وَلَا","And (do) not"],["تَشْتَرُوا۟","exchange"],["بِعَهْدِ","the covenant"],["ٱللَّهِ","(of) Allah"],["ثَمَنًۭا","(for) a price"],["قَلِيلًا ۚ","little"],["إِنَّمَا","Indeed, what"],["عِندَ","(is) with"],["ٱللَّهِ","Allah"],["هُوَ","it"],["خَيْرٌۭ","(is) better"],["لَّكُمْ","for you"],["إِن","if"],["كُنتُمْ","you were (to)"],["تَعْلَمُونَ","know"]]],"1997":["(Apa yang di sisi kalian) berupa duniawi (akan lenyap) akan musnah (dan apa yang ada di sisi Allah adalah kekal) abadi. (Dan sesungguhnya Kami akan memberi balasan) dapat dibaca walayajziyanna dan walanajziyanna (orang-orang yang sabar) demi menunaikan janjinya (dengan pahala yang lebih baik dari apa yang telah mereka kerjakan) lafal ahsana di sini maknanya sama dengan hasuna.",[["مَا","Whatever"],["عِندَكُمْ","(is) with you"],["يَنفَدُ ۖ","will be exhausted"],["وَمَا","and whatever"],["عِندَ","(is) with"],["ٱللَّهِ","Allah"],["بَاقٍۢ ۗ","(will) be remaining"],["وَلَنَجْزِيَنَّ","And surely We will pay"],["ٱلَّذِينَ","those who"],["صَبَرُوٓا۟","(are) patient"],["أَجْرَهُم","their reward"],["بِأَحْسَنِ","to (the) best"],["مَا","(of) what"],["كَانُوا۟","they used (to)"],["يَعْمَلُونَ","do"]]],"1998":["(Barang siapa yang mengerjakan amal saleh baik laki-laki maupun perempuan dalam keadaan beriman, maka sesungguhnya akan Kami berikan kepadanya kehidupan yang baik) menurut suatu pendapat dikatakan bahwa yang dimaksud adalah kehidupan di surga. Menurut pendapat yang lain dikatakan adalah kehidupan dunia, yaitu dengan mendapatkan rasa qana`ah atau menerima apa adanya atau ia mendapatkan rezeki yang halal (dan sesungguhnya akan Kami beri balasan kepada mereka dengan pahala yang lebih baik dari apa yang telah mereka kerjakan).",[["مَنْ","Whoever"],["عَمِلَ","does"],["صَـٰلِحًۭا","righteous deeds"],["مِّن","whether"],["ذَكَرٍ","male"],["أَوْ","or"],["أُنثَىٰ","female"],["وَهُوَ","while he"],["مُؤْمِنٌۭ","(is) a believer"],["فَلَنُحْيِيَنَّهُۥ","then surely We will give him life"],["حَيَوٰةًۭ","a life"],["طَيِّبَةًۭ ۖ","good"],["وَلَنَجْزِيَنَّهُمْ","and We will pay them"],["أَجْرَهُم","their reward"],["بِأَحْسَنِ","to (the) best"],["مَا","of what"],["كَانُوا۟","they used (to)"],["يَعْمَلُونَ","do"]]],"1999":["(Apabila kamu membaca Alquran) artinya bila kamu hendak membaca Alquran (hendaklah kamu meminta perlindungan kepada Allah dari setan yang terkutuk) artinya ucapkanlah a`uudzu billaahi minasy syaithaanirrajiim.",[["فَإِذَا","So when"],["قَرَأْتَ","you recite"],["ٱلْقُرْءَانَ","the Quran"],["فَٱسْتَعِذْ","seek refuge"],["بِٱللَّهِ","in Allah"],["مِنَ","from"],["ٱلشَّيْطَـٰنِ","the Shaitaan"],["ٱلرَّجِيمِ","the accursed"]]],"2000":["(Sesungguhnya setan itu tidak ada kekuasaan baginya) tidak mempunyai pengaruh (atas orang-orang yang beriman dan bertawakal kepada Rabbnya.)",[["إِنَّهُۥ","Indeed he"],["لَيْسَ","not"],["لَهُۥ","for him"],["سُلْطَـٰنٌ","(is) any authority"],["عَلَى","on"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَلَىٰ","and upon"],["رَبِّهِمْ","their Lord"],["يَتَوَكَّلُونَ","they put their trust"]]],"2001":["(Sesungguhnya kekuasaannya hanyalah atas orang-orang yang mengambilnya sebagai pemimpin) yaitu yang taat kepadanya (dan atas orang-orang yang terhadap-Nya) maksudnya kepada Allah (mereka mempersekutukan.)",[["إِنَّمَا","Only"],["سُلْطَـٰنُهُۥ","his authority"],["عَلَى","(is) over"],["ٱلَّذِينَ","those who"],["يَتَوَلَّوْنَهُۥ","take him as an ally"],["وَٱلَّذِينَ","and those who"],["هُم","[they]"],["بِهِۦ","with Him"],["مُشْرِكُونَ","associate partners"]]],"2002":["(Dan apabila Kami letakkan suatu ayat di tempat ayat yang lain) artinya dengan memansukhnya kemudian menggantinya dengan ayat yang lain demi kemaslahatan semua hamba (padahal Allah lebih mengetahui apa yang diturunkan-Nya, mereka berkata) orang-orang kafir kepada Nabi saw. (\"Sesungguhnya kamu adalah orang yang mengada-ada saja.\") seorang pendusta yang pandai membuat-buat perkataan dari dirimu sendiri. (Bahkan kebanyakan mereka tiada mengetahui) hakikat Alquran dan faedah yang terkandung di dalam penasikhan ini.",[["وَإِذَا","And when"],["بَدَّلْنَآ","We substitute"],["ءَايَةًۭ","a Verse"],["مَّكَانَ","(in) place"],["ءَايَةٍۢ ۙ","(of) a Verse"],["وَٱللَّهُ","and Allah "],["أَعْلَمُ","(is) most knowing"],["بِمَا","of what"],["يُنَزِّلُ","He sends down"],["قَالُوٓا۟","they say"],["إِنَّمَآ","Only"],["أَنتَ","you"],["مُفْتَرٍۭ ۚ","(are) an inventor"],["بَلْ","Nay"],["أَكْثَرُهُمْ","most of them"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"2003":["(Katakanlah) kepada mereka! (\"Ruh Quduslah yang telah menurunkannya) yakni Alquran itu (dari sisi Rabbmu dengan benar) lafal bilhaqqi berta`alluq kepada lafal nazzalahu (untuk meneguhkan hati orang-orang yang beriman) dengan keimanan mereka kepada Alquran (dan menjadi petunjuk serta kabar gembira bagi orang-orang yang berserah diri.\")",[["قُلْ","Say"],["نَزَّلَهُۥ","Has brought it down"],["رُوحُ","the Holy Spirit"],["ٱلْقُدُسِ","the Holy Spirit"],["مِن","from"],["رَّبِّكَ","your Lord"],["بِٱلْحَقِّ","in truth"],["لِيُثَبِّتَ","to make firm"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَهُدًۭى","and (as) a guidance"],["وَبُشْرَىٰ","and glad tidings"],["لِلْمُسْلِمِينَ","to the Muslims"]]],"2004":["(Dan sesungguhnya) lafal qad di sini menunjukkan makna tahqiq (Kami mengetahui bahwa mereka berkata, \"Sesungguhnya ia itu diajarkan kepadanya) yakni Alquran itu (oleh seorang manusia.\") dimaksud adalah seorang pendeta Nasrani yang Nabi saw. pernah berkunjung kepadanya; lalu Allah swt. menyanggah melalui firman-Nya: (Padahal bahasa) atau logat (yang mereka tuduhkan) mereka sangkakan (kepada Muhammad) bahwa ia belajar daripadanya (adalah bahasa ajam sedangkan ini) yakni Alquran ini (adalah dalam bahasa Arab yang terang) memiliki kejelasan dan kefasihan, maka mengapa bahasa ini diajarkan oleh orang asing?",[["وَلَقَدْ","And certainly"],["نَعْلَمُ","We know"],["أَنَّهُمْ","that they"],["يَقُولُونَ","say"],["إِنَّمَا","Only"],["يُعَلِّمُهُۥ","teaches him"],["بَشَرٌۭ ۗ","a human being"],["لِّسَانُ","(The) tongue"],["ٱلَّذِى","(of) the one"],["يُلْحِدُونَ","they refer"],["إِلَيْهِ","to him"],["أَعْجَمِىٌّۭ","(is) foreign"],["وَهَـٰذَا","while this"],["لِسَانٌ","(is) a language"],["عَرَبِىٌّۭ","Arabic"],["مُّبِينٌ","clear"]]],"2005":["(Sesungguhnya orang-orang yang tidak beriman kepada ayat-ayat Allah, Allah tidak akan memberi petunjuk kepada mereka dan bagi mereka azab yang pedih) azab yang menyakitkan.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"],["بِـَٔايَـٰتِ","in the Verses"],["ٱللَّهِ","(of) Allah"],["لَا","not"],["يَهْدِيهِمُ","Allah will guide them"],["ٱللَّهُ","Allah will guide them"],["وَلَهُمْ","and for them"],["عَذَابٌ","(is) a punishment"],["أَلِيمٌ","painful"]]],"2006":["(Sesungguhnya yang mengada-adakan kebohongan, hanyalah orang-orang yang tidak beriman kepada ayat-ayat Allah) yakni Alquran; melalui tuduhan mereka yang mengatakan, bahwa Alquran adalah perkataan manusia (dan mereka itulah orang-orang pendusta) pengertian taukid di sini disimpulkan dari pengulangan dhamir. Ayat ini merupakan sanggahan terhadap perkataan mereka sebagaimana yang disitir oleh firman-Nya yang lain, yaitu, \"Sesungguhnya kamu adalah orang yang mengada-ada saja.\" (Q.S. An-Nahl 101).",[["إِنَّمَا","Only"],["يَفْتَرِى","they invent"],["ٱلْكَذِبَ","the falsehood"],["ٱلَّذِينَ","those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"],["بِـَٔايَـٰتِ","in the Verses"],["ٱللَّهِ ۖ","(of) Allah"],["وَأُو۟لَـٰٓئِكَ","and those "],["هُمُ","they"],["ٱلْكَـٰذِبُونَ","(are) the liars"]]],"2007":["(Barang siapa yang kafir kepada Allah sesudah dia beriman, kecuali orang yang dipaksa) untuk mengucapkan kalimat kekafiran kemudian ia terpaksa mengucapkannya (padahal hatinya tetap tenang dalam beriman) lafal man dianggap sebagai mubtada, atau syarthiyah sedangkan khabar atau jawabnya ialah: maka bagi mereka ancaman yang keras. Pengertian ini ditunjukkan oleh firman selanjutnya, yaitu: (akan tetapi orang yang melapangkan dadanya untuk kekafiran) yakni hatinya menerima kekafiran dengan lapang (maka kemurkaan Allah menimpanya dan baginya azab yang besar).",[["مَن","Whoever"],["كَفَرَ","disbelieves"],["بِٱللَّهِ","in Allah"],["مِنۢ","after"],["بَعْدِ","after"],["إِيمَـٰنِهِۦٓ","his belief"],["إِلَّا","except"],["مَنْ","(one) who"],["أُكْرِهَ","is forced"],["وَقَلْبُهُۥ","while his heart"],["مُطْمَئِنٌّۢ","(is) content"],["بِٱلْإِيمَـٰنِ","with the faith"],["وَلَـٰكِن","But"],["مَّن","(one) who"],["شَرَحَ","opens"],["بِٱلْكُفْرِ","to disbelief"],["صَدْرًۭا","(his) breast"],["فَعَلَيْهِمْ","then upon them"],["غَضَبٌۭ","(is) a wrath"],["مِّنَ","of"],["ٱللَّهِ","Allah"],["وَلَهُمْ","and for them"],["عَذَابٌ","(is) a punishment"],["عَظِيمٌۭ","great"]]],"2008":["(Yang demikian itu) ancaman yang ditujukan kepada mereka itu (disebabkan karena sesungguhnya mereka mencintai kehidupan di dunia) mereka memilihnya (lebih dari akhirat dan bahwasanya Allah tiada memberi petunjuk kepada kaum yang kafir.)",[["ذَٰلِكَ","That (is)"],["بِأَنَّهُمُ","because"],["ٱسْتَحَبُّوا۟","they preferred"],["ٱلْحَيَوٰةَ","the life"],["ٱلدُّنْيَا","(of) the world"],["عَلَى","over"],["ٱلْـَٔاخِرَةِ","the Hereafter"],["وَأَنَّ","and that"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يَهْدِى","guide"],["ٱلْقَوْمَ","the people"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"2009":["(Mereka itulah orang-orang yang hatinya, pendengarannya dan penglihatannya telah dikunci mati oleh Allah dan mereka itulah orang-orang yang lalai) dari apa yang dikehendaki terhadap diri mereka.",[["أُو۟لَـٰٓئِكَ","Those"],["ٱلَّذِينَ","(are) the ones "],["طَبَعَ","Allah has set a seal"],["ٱللَّهُ","Allah has set a seal"],["عَلَىٰ","over"],["قُلُوبِهِمْ","their hearts"],["وَسَمْعِهِمْ","and their hearing"],["وَأَبْصَـٰرِهِمْ ۖ","and their sight"],["وَأُو۟لَـٰٓئِكَ","And those "],["هُمُ","they are"],["ٱلْغَـٰفِلُونَ","the heedless"]]],"2010":["(Tidak diragukan lagi) pastilah (bahwa mereka di akhirat nanti adalah orang-orang yang merugi) karena tempat kembali mereka adalah neraka dan mereka kekal di dalamnya.",[["لَا","No"],["جَرَمَ","doubt"],["أَنَّهُمْ","that they"],["فِى","in"],["ٱلْـَٔاخِرَةِ","the Hereafter"],["هُمُ","[they]"],["ٱلْخَـٰسِرُونَ","(are) the losers"]]],"2011":["(Dan sesungguhnya Rabbmu terhadap orang-orang yang berhijrah) ke Madinah (sesudah menderita cobaan) sesudah mereka disiksa dan dipaksa mengucapkan kalimat kekafiran. Menurut qiraat lafal futinuu dibaca fatanuu; artinya sesudah mereka kafir, atau sesudah mereka memfitnah manusia supaya jangan beriman (kemudian mereka berjihad dan sabar) di dalam melakukan ketaatan (sesungguhnya Rabbmu sesudah itu) sesudah cobaan itu (benar-benar Maha Pengampun) kepada mereka (lagi Maha Penyayang) terhadap mereka. Khabarnya inna yang pertama sama dengan khabar inna yang kedua.",[["ثُمَّ","Then"],["إِنَّ","indeed"],["رَبَّكَ","your Lord"],["لِلَّذِينَ","to those who"],["هَاجَرُوا۟","emigrated"],["مِنۢ","after"],["بَعْدِ","after"],["مَا","what"],["فُتِنُوا۟","they had been put to trials"],["ثُمَّ","then"],["جَـٰهَدُوا۟","strove hard"],["وَصَبَرُوٓا۟","and were patient"],["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["مِنۢ","after it"],["بَعْدِهَا","after it"],["لَغَفُورٌۭ","surely is Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"2012":["Ingatlah (suatu hari ketika tiap-tiap diri datang untuk membela) berhujah untuk membela (dirinya sendiri) ia tidak menghiraukan selain daripada dirinya sendiri, yaitu hari kiamat (dan bagi tiap-tiap diri disempurnakan) balasan (apa yang telah dikerjakannya, sedangkan mereka tidak dianiaya) sedikit pun juga.",[["۞ يَوْمَ","(On) the Day"],["تَأْتِى","(when) will come"],["كُلُّ","every"],["نَفْسٍۢ","soul"],["تُجَـٰدِلُ","pleading"],["عَن","for"],["نَّفْسِهَا","itself"],["وَتُوَفَّىٰ","and will be paid in full"],["كُلُّ","every"],["نَفْسٍۢ","soul"],["مَّا","what"],["عَمِلَتْ","it did"],["وَهُمْ","and they"],["لَا","(will) not"],["يُظْلَمُونَ","be wronged"]]],"2013":["(Dan Allah telah membuat suatu perumpamaan) kata perumpamaan ini dijelaskan oleh badalnya, yaitu (dengan sebuah negeri) yaitu Mekah, yang dimaksud adalah penduduknya (dahulunya aman) dari serbuan musuh dan tidak pernah ada kerusuhan (lagi tenteram) tidak perlu pindah karena alasan sempit atau takut (rezekinya datang kepadanya melimpah-ruah) dengan luas (dari segenap tempat, tetapi penduduknya mengingkari nikmat-nikmat Allah) disebabkan mereka mendustakan Nabi saw. (karena itu Allah merasakan kepada mereka pakaian kelaparan) sehingga mereka mengalami paceklik selama tujuh tahun (dan ketakutan) terhadap pasukan-pasukan tentara Nabi saw. (disebabkan apa yang selalu mereka perbuat).",[["وَضَرَبَ","And Allah sets forth"],["ٱللَّهُ","And Allah sets forth"],["مَثَلًۭا","a similitude"],["قَرْيَةًۭ","(of) a town"],["كَانَتْ","(that) was"],["ءَامِنَةًۭ","secure"],["مُّطْمَئِنَّةًۭ","and content"],["يَأْتِيهَا","coming to it"],["رِزْقُهَا","its provision"],["رَغَدًۭا","(in) abundance"],["مِّن","from"],["كُلِّ","every"],["مَكَانٍۢ","place"],["فَكَفَرَتْ","but it denied"],["بِأَنْعُمِ","(the) Favors of Allah"],["ٱللَّهِ","(the) Favors of Allah"],["فَأَذَٰقَهَا","so Allah made it taste"],["ٱللَّهُ","so Allah made it taste"],["لِبَاسَ","(the) garb"],["ٱلْجُوعِ","(of) the hunger"],["وَٱلْخَوْفِ","and the fear"],["بِمَا","for what"],["كَانُوا۟","they used (to)"],["يَصْنَعُونَ","do"]]],"2014":["(Dan sesungguhnya telah datang kepada mereka seorang rasul dari mereka sendiri) yaitu Nabi Muhammad saw. (tetapi mereka mendustakannya karena itu mereka ditimpa azab) yaitu berupa kelaparan dan dicekam rasa takut (sedangkan mereka adalah orang-orang yang zalim).",[["وَلَقَدْ","And certainly"],["جَآءَهُمْ","came to them"],["رَسُولٌۭ","a Messenger"],["مِّنْهُمْ","from among them"],["فَكَذَّبُوهُ","but they denied him"],["فَأَخَذَهُمُ","so seized them"],["ٱلْعَذَابُ","the punishment"],["وَهُمْ","while they"],["ظَـٰلِمُونَ","(were) wrongdoers"]]],"2015":["(Maka makanlah) hai orang-orang yang beriman (yang halal lagi baik dari rezeki yang telah diberikan Allah kepada kalian dan syukurilah nikmat Allah jika kalian hanya kepada-Nya saja menyembah).",[["فَكُلُوا۟","So eat"],["مِمَّا","of what"],["رَزَقَكُمُ","Allah has provided you "],["ٱللَّهُ","Allah has provided you "],["حَلَـٰلًۭا","lawful"],["طَيِّبًۭا","and good"],["وَٱشْكُرُوا۟","And be grateful"],["نِعْمَتَ","(for the) Favor"],["ٱللَّهِ","(of) Allah"],["إِن","if"],["كُنتُمْ","[you]"],["إِيَّاهُ","Him Alone"],["تَعْبُدُونَ","you worship"]]],"2016":["(Sesungguhnya Allah hanya mengharamkan atas kalian bangkai, darah, daging babi dan apa yang disembelih dengan menyebut nama selain Allah; tetapi barang siapa yang terpaksa memakannya dengan tidak menganiaya dan tidak pula melampaui batas, maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.)",[["إِنَّمَا","Only"],["حَرَّمَ","He has forbidden"],["عَلَيْكُمُ","to you"],["ٱلْمَيْتَةَ","the dead animal"],["وَٱلدَّمَ","and the blood"],["وَلَحْمَ","and the flesh"],["ٱلْخِنزِيرِ","(of) the swine"],["وَمَآ","and what"],["أُهِلَّ","has been dedicated"],["لِغَيْرِ","to other (than)"],["ٱللَّهِ","Allah"],["بِهِۦ ۖ","[with it]"],["فَمَنِ","But (if) one"],["ٱضْطُرَّ","(is) forced "],["غَيْرَ","without (being)"],["بَاغٍۢ","disobedient"],["وَلَا","and not"],["عَادٍۢ","a transgressor "],["فَإِنَّ","then indeed"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"2017":["(Dan janganlah kalian mengatakan terhadap apa yang disebut-sebut oleh lidah kalian) yang sering digambarkan oleh lisan kalian (secara dusta, \"Ini halal dan ini haram.\") terhadap apa yang tidak dihalalkan oleh Allah dan apa yang tidak diharamkan oleh-Nya (untuk mengada-adakan kebohongan terhadap Allah) dengan menisbatkan hal itu kepada-Nya. (Sesungguhnya orang-orang yang mengada-adakan kebohongan terhadap Allah tiadalah beruntung).",[["وَلَا","And (do) not"],["تَقُولُوا۟","say"],["لِمَا","for that which"],["تَصِفُ","assert"],["أَلْسِنَتُكُمُ","your tongues"],["ٱلْكَذِبَ","the lie"],["هَـٰذَا","This"],["حَلَـٰلٌۭ","(is) lawful"],["وَهَـٰذَا","and this"],["حَرَامٌۭ","(is) forbidden"],["لِّتَفْتَرُوا۟","so that you invent"],["عَلَى","about"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ ۚ","the lie"],["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يَفْتَرُونَ","invent"],["عَلَى","about"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ","the lie"],["لَا","they will not succeed"],["يُفْلِحُونَ","they will not succeed"]]],"2018":["Bagi mereka yang mengada-adakan kedustaan atas nama Allah (kesenangan yang sedikit) di dunia (dan bagi mereka) kelak di akhirat (azab yang pedih) azab yang menyakitkan.",[["مَتَـٰعٌۭ","An enjoyment"],["قَلِيلٌۭ","little"],["وَلَهُمْ","and for them"],["عَذَابٌ","(is) a punishment"],["أَلِيمٌۭ","painful"]]],"2019":["(Dan terhadap orang-orang Yahudi) dimaksud para pemeluk agama Yahudi (Kami haramkan apa yang telah Kami ceritakan dahulu kepadamu) di dalam firman-Nya yang lain, yaitu, \"Dan kepada orang-orang Yahudi, Kami haramkan segala binatang yang berkuku...\" (Q.S. Al-An'am 146) (dan Kami tiada menganiaya mereka) dengan mengharamkan hal tersebut kepada mereka (akan tetapi merekalah yang menganiaya diri mereka sendiri) dengan melakukan perbuatan-perbuatan maksiat yang menyebabkan diharamkannya hal-hal tersebut.",[["وَعَلَى","And to"],["ٱلَّذِينَ","those who"],["هَادُوا۟","are Jews"],["حَرَّمْنَا","We have forbidden"],["مَا","what"],["قَصَصْنَا","We related"],["عَلَيْكَ","to you"],["مِن","before"],["قَبْلُ ۖ","before"],["وَمَا","And not"],["ظَلَمْنَـٰهُمْ","We wronged them"],["وَلَـٰكِن","but"],["كَانُوٓا۟","they used (to)"],["أَنفُسَهُمْ","themselves"],["يَظْلِمُونَ","wrong"]]],"2020":["(Kemudian sesungguhnya Rabbmu terhadap orang-orang yang mengerjakan keburukan) kemusyrikan (karena kebodohannya kemudian mereka bertobat) kembali kepada Allah (sesudah itu dan memperbaiki dirinya) memperbaiki amal perbuatannya (sesungguhnya Rabbmu sesudah itu) sesudah kebodohannya dan sesudah bertobat (benar-benar Maha Pengampun) kepada mereka (lagi Maha Penyayang) kepada mereka.",[["ثُمَّ","Then"],["إِنَّ","indeed"],["رَبَّكَ","your Lord"],["لِلَّذِينَ","to those who"],["عَمِلُوا۟","did"],["ٱلسُّوٓءَ","evil"],["بِجَهَـٰلَةٍۢ","in ignorance"],["ثُمَّ","then"],["تَابُوا۟","repented"],["مِنۢ","after"],["بَعْدِ","after"],["ذَٰلِكَ","that"],["وَأَصْلَحُوٓا۟","and corrected themselves "],["إِنَّ","indeed"],["رَبَّكَ","your Lord"],["مِنۢ","after that"],["بَعْدِهَا","after that"],["لَغَفُورٌۭ","(is) surely Oft-Forgiving"],["رَّحِيمٌ","Most Merciful"]]],"2021":["(Sesungguhnya Ibrahim adalah seorang imam) seorang penghulu yang menjadi panutan dan di dalam dirinya terkandung semua akhlak yang baik (lagi patuh) sangat taat (kepada Allah dan hanif) cenderung kepada agama yang lurus. (Dan sekali-kali dia bukanlah termasuk orang-orang yang mempersekutukan Tuhan.)",[["إِنَّ","Indeed"],["إِبْرَٰهِيمَ","Ibrahim"],["كَانَ","was"],["أُمَّةًۭ","a nation"],["قَانِتًۭا","obedient"],["لِّلَّهِ","to Allah"],["حَنِيفًۭا","upright"],["وَلَمْ","and not"],["يَكُ","he was"],["مِنَ","of"],["ٱلْمُشْرِكِينَ","the polytheists"]]],"2022":["(Lagi yang mensyukuri nikmat-nikmat Allah, Allah telah memilihnya) menjadikannya sebagai pilihan-Nya (dan menunjukkannya kepada jalan yang lurus.)",[["شَاكِرًۭا","Thankful"],["لِّأَنْعُمِهِ ۚ","for His favors"],["ٱجْتَبَىٰهُ","He chose him"],["وَهَدَىٰهُ","and guided him"],["إِلَىٰ","to"],["صِرَٰطٍۢ","the way"],["مُّسْتَقِيمٍۢ","straight"]]],"2023":["(Dan Kami berikan kepadanya) di dalam ungkapan ini terkandung pengertian iltifat dari gaibah, atau perpindahan ungkapan dari dhamir gaib kepada dhamir mutakallim (kebaikan di dunia) yaitu mendapatkan pujian dari kalangan semua agama. (Dan sesungguhnya dia di akhirat benar-benar termasuk orang-orang yang saleh) yaitu orang-orang yang memiliki derajat yang tinggi di akhirat.",[["وَءَاتَيْنَـٰهُ","And We gave him"],["فِى","in"],["ٱلدُّنْيَا","the world"],["حَسَنَةًۭ ۖ","good"],["وَإِنَّهُۥ","and indeed, he"],["فِى","in"],["ٱلْـَٔاخِرَةِ","the Hereafter"],["لَمِنَ","(he) will surely (be) among"],["ٱلصَّـٰلِحِينَ","the righteous"]]],"2024":["(Kemudian Kami wahyukan kepadamu) hai Muhammad (ikutilah millah) yakni agama (Ibrahim seorang yang hanif. Dan bukanlah dia termasuk orang-orang yang mempersekutukan Tuhan) Allah swt. mengulangi ayat ini untuk menyanggah anggapan orang-orang Yahudi dan orang-orang Nasrani yang mengakui bahwa Nabi Ibrahim adalah pemeluk agama mereka.",[["ثُمَّ","Then"],["أَوْحَيْنَآ","We revealed"],["إِلَيْكَ","to you"],["أَنِ","that"],["ٱتَّبِعْ","You follow"],["مِلَّةَ","(the) religion"],["إِبْرَٰهِيمَ","(of) Ibrahim"],["حَنِيفًۭا ۖ","upright"],["وَمَا","and not"],["كَانَ","he was"],["مِنَ","of"],["ٱلْمُشْرِكِينَ","the polytheists"]]],"2025":["(Sesungguhnya telah dijadikan hari Sabtu) diwajibkan menghormatinya (atas orang-orang Yahudi yang berselisih mengenainya) dengan nabi mereka; mereka adalah orang-orang Yahudi yang diperintahkan oleh Allah supaya mereka menyibukkan dirinya untuk beribadah di hari Jumat, akan tetapi mereka mengatakan, \"Kami tidak menghendakinya,\" lalu mereka memilih hari Sabtu sebagai hari untuk ibadah. Akhirnya Allah memperketat peraturan kepada mereka di hari Sabtu. (Dan sesungguhnya Rabbmu benar-benar akan memberi putusan di antara mereka di hari kiamat terhadap apa yang telah mereka perselisihkan itu) yaitu Dia kelak akan memberi pahala kepada orang yang taat, dan Dia akan mengazab orang-orang yang durhaka melanggar hal-hal yang diharamkan-Nya.",[["إِنَّمَا","Only"],["جُعِلَ","was appointed"],["ٱلسَّبْتُ","the Sabbath"],["عَلَى","for"],["ٱلَّذِينَ","those who"],["ٱخْتَلَفُوا۟","differed"],["فِيهِ ۚ","in it"],["وَإِنَّ","And indeed"],["رَبَّكَ","your Lord"],["لَيَحْكُمُ","will surely judge"],["بَيْنَهُمْ","between them"],["يَوْمَ","(on) the Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["فِيمَا","in what"],["كَانُوا۟","they used (to)"],["فِيهِ","[in it]"],["يَخْتَلِفُونَ","differ"]]],"2026":["(Serulah) manusia, hai Muhammad (kepada jalan Rabbmu) yakni agama-Nya (dengan hikmah) dengan Alquran (dan pelajaran yang baik) pelajaran yang baik atau nasihat yang lembut (dan bantahlah mereka dengan cara) bantahan (yang baik) seperti menyeru mereka untuk menyembah Allah dengan menampilkan kepada mereka tanda-tanda kebesaran-Nya atau dengan hujah-hujah yang jelas. (Sesungguhnya Rabbmu Dialah Yang lebih mengetahui) Maha Mengetahui (tentang siapa yang tersesat dari jalan-Nya dan Dialah yang lebih mengetahui orang-orang yang mendapat petunjuk) maka Dia membalas mereka; ayat ini diturunkan sebelum diperintahkan untuk memerangi orang-orang kafir. Dan diturunkan ketika Hamzah gugur dalam keadaan tercincang; ketika Nabi saw. melihat keadaan jenazahnya, lalu beliau saw. bersumpah melalui sabdanya, \"Sungguh aku bersumpah akan membalas tujuh puluh orang dari mereka sebagai penggantimu.\"",[["ٱدْعُ","Call"],["إِلَىٰ","to"],["سَبِيلِ","(the) way"],["رَبِّكَ","(of) your Lord"],["بِٱلْحِكْمَةِ","with the wisdom"],["وَٱلْمَوْعِظَةِ","and the instruction"],["ٱلْحَسَنَةِ ۖ","the good"],["وَجَـٰدِلْهُم","and discuss with them"],["بِٱلَّتِى","in that"],["هِىَ","which"],["أَحْسَنُ ۚ","(is) best"],["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["هُوَ","He"],["أَعْلَمُ","(is) most knowing"],["بِمَن","of who"],["ضَلَّ","has strayed"],["عَن","from"],["سَبِيلِهِۦ ۖ","His way"],["وَهُوَ","And He"],["أَعْلَمُ","(is) most knowing"],["بِٱلْمُهْتَدِينَ","of the guided ones"]]],"2027":["(Dan jika kalian memberikan balasan, maka balaslah dengan balasan yang sama dengan siksaan yang ditimpakan kepada kalian. Akan tetapi jika kalian bersabar) tidak mau membalas (sesungguhnya itulah) bersikap sabar itulah (yang lebih baik bagi orang-orang yang sabar) kemudian Nabi saw. membatalkan sumpahnya itu, dan membayar kafaratnya. Demikianlah menurut hadis yang telah diriwayatkan oleh Imam Bazzar.",[["وَإِنْ","And if"],["عَاقَبْتُمْ","you retaliate"],["فَعَاقِبُوا۟","then retaliate"],["بِمِثْلِ","with the like"],["مَا","of what"],["عُوقِبْتُم","you were afflicted"],["بِهِۦ ۖ","with [it]"],["وَلَئِن","But if"],["صَبَرْتُمْ","you are patient"],["لَهُوَ","surely (it) is"],["خَيْرٌۭ","better"],["لِّلصَّـٰبِرِينَ","for those who are patient"]]],"2028":["(Bersabarlah dan tiadalah kesabaranmu itu melainkan dengan pertolongan Allah) berkat taufiq-Nya (dan janganlah kamu bersedih hati terhadap kekafiran mereka) terhadap kekafiran orang-orang kafir, jika mereka tidak juga mau beriman, karena kamu menginginkan dengan sangat akan keimanan mereka (dan janganlah kamu bersempit dada terhadap apa yang mereka tipu-dayakan) artinya janganlah engkau hiraukan tipu muslihat mereka, karena sesungguhnya Akulah yang akan menolongmu dalam menghadapi mereka.",[["وَٱصْبِرْ","And be patient"],["وَمَا","and not"],["صَبْرُكَ","(is) your patience"],["إِلَّا","but"],["بِٱللَّهِ ۚ","from Allah"],["وَلَا","And (do) not"],["تَحْزَنْ","grieve"],["عَلَيْهِمْ","over them"],["وَلَا","and (do) not"],["تَكُ","be"],["فِى","in"],["ضَيْقٍۢ","distress"],["مِّمَّا","for what"],["يَمْكُرُونَ","they plot"]]],"2029":["(Sesungguhnya Allah beserta orang-orang yang bertakwa) orang-orang yang takut terhadap kekafiran dan kemaksiatan (dan orang-orang yang berbuat kebaikan) dengan menjalankan ketaatan, kesabaran; Allah akan menolong mereka dengan bantuan dan pertolongan-Nya.",[["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["مَعَ","(is) with"],["ٱلَّذِينَ","those who"],["ٱتَّقَوا۟","fear (Him)"],["وَّٱلَّذِينَ","and those who"],["هُم","[they]"],["مُّحْسِنُونَ","(are) good-doers"]]]});